/** Kody twórców — panel właściciela w „Więcej" → Ustawienia dev.
 *
 *  Trzy rzeczy, których potrzeba przy kampanii z twórcami, bez otwierania Supabase:
 *  założenie kodu dla nowego twórcy, podgląd, jak jego kod działa w danym miesiącu,
 *  i GOTOWY tekst comiesięcznego maila (statystyki + prowizja) do skopiowania.
 *
 *  Liczby przychodzą z serwera (`bot/polecenia.py → raport`). Kwoty są w groszach.
 *  Serwer wpuszcza tu wyłącznie konto właściciela — kłódka jest po stronie API,
 *  a `isDev` tylko chowa sekcję przed resztą.
 */
import React, { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, Platform, StyleSheet, Text, TextInput, View } from "react-native";
import { getReferralReport, ReferralReport, ReferralStats, saveReferralCode } from "../api";
import { useAuth } from "../auth/AuthContext";
import { C } from "../theme";
import { Card, MetalButton, Press, SectionTitle } from "../ui";
import Icon from "../ui/Icon";

const zl = (grosze: number) =>
  (grosze / 100).toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " zł";

function miesiac(przesuniecie: number) {
  const d = new Date();
  d.setDate(1);
  d.setMonth(d.getMonth() + przesuniecie);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

const PUSTY = { code: "", creator_name: "", creator_handle: "", contact_email: "",
                free_slots: "5", free_days: "30", commission_pct: "50" };

export default function ReferralAdmin() {
  const { isDev } = useAuth();
  const [open, setOpen] = useState(false);
  if (!isDev) return null;

  return (
    <>
      <Press onPress={() => setOpen((o) => !o)} style={{ marginTop: 10 }}>
        <Card style={[s.head, open && s.headOn]}>
          <Icon name="serce" size={17} color={C.amber} />
          <View style={{ flex: 1 }}>
            <Text style={s.title}>Kody polecające twórców</Text>
            <Text style={s.sub}>{open ? "Zwiń" : "Zakładanie kodów, statystyki, maile z prowizją"}</Text>
          </View>
          <Text style={[s.arrow, open && s.arrowOn]}>›</Text>
        </Card>
      </Press>
      {open && <Panel />}
    </>
  );
}

function Panel() {
  const [przes, setPrzes] = useState(0);
  const [dane, setDane] = useState<ReferralReport | null>(null);
  const [blad, setBlad] = useState("");
  const [form, setForm] = useState<Record<string, string>>(PUSTY);
  const [zapis, setZapis] = useState("");

  const m = miesiac(przes);
  const wczytaj = useCallback(() => {
    setDane(null); setBlad("");
    getReferralReport(m)
      .then((r) => (r.ok ? setDane(r) : setBlad(r.message || "Nie udało się pobrać raportu.")))
      .catch((e) => setBlad(e?.message || "Nie udało się pobrać raportu."));
  }, [m]);
  useEffect(() => { wczytaj(); }, [wczytaj]);

  async function zapisz() {
    setZapis("…");
    try {
      const r = await saveReferralCode({
        ...form,
        free_slots: Number(form.free_slots), free_days: Number(form.free_days),
        commission_pct: Number(form.commission_pct.replace(",", ".")),
      });
      setZapis(r.ok ? `Zapisano kod ${r.code}. Link do bio: portevo.pl/k/${r.code}` : r.message || "Błąd zapisu");
      if (r.ok) { setForm(PUSTY); wczytaj(); }
    } catch (e: any) {
      setZapis(e?.message || "Błąd zapisu");
    }
  }

  const pole = (klucz: string, etykieta: string, wlasciwosci: object = {}) => (
    <View style={{ flex: 1, minWidth: 130 }}>
      <Text style={s.label}>{etykieta}</Text>
      <TextInput style={s.input} value={form[klucz]} placeholderTextColor={C.dim}
                 onChangeText={(t) => setForm((f) => ({ ...f, [klucz]: t }))}
                 autoCorrect={false} {...wlasciwosci} />
    </View>
  );

  return (
    <View style={{ marginTop: 10, gap: 10 }}>
      <Card>
        <Text style={s.cardTitle}>Nowy kod albo zmiana istniejącego</Text>
        <View style={s.grid}>
          {pole("code", "KOD", { placeholder: "KASIA", autoCapitalize: "characters" })}
          {pole("creator_name", "TWÓRCA", { placeholder: "Kasia Inwestuje" })}
        </View>
        <View style={s.grid}>
          {pole("creator_handle", "TIKTOK", { placeholder: "@kasia.inwestuje", autoCapitalize: "none" })}
          {pole("contact_email", "E-MAIL DO RAPORTU", { placeholder: "kasia@…", autoCapitalize: "none", keyboardType: "email-address" })}
        </View>
        <View style={s.grid}>
          {pole("free_slots", "DARMOWE MIEJSCA", { keyboardType: "number-pad" })}
          {pole("free_days", "DNI PREMIUM", { keyboardType: "number-pad" })}
          {pole("commission_pct", "% PROWIZJI (NETTO)", { keyboardType: "decimal-pad" })}
        </View>
        <MetalButton label="Zapisz kod" tone="green" active full style={{ marginTop: 12 }} onPress={zapisz} />
        {!!zapis && <Text style={s.note} selectable>{zapis}</Text>}
      </Card>

      <View style={s.monthRow}>
        <MetalButton label="‹" size="sm" onPress={() => setPrzes((p) => p - 1)} />
        <Text style={s.month}>{m}</Text>
        <MetalButton label="›" size="sm" disabled={przes >= 0} onPress={() => setPrzes((p) => p + 1)} />
      </View>

      {!dane && !blad && <ActivityIndicator color={C.amber} />}
      {!!blad && <Text style={s.err}>{blad}</Text>}
      {dane?.kody?.length === 0 && <Text style={s.note}>Nie ma jeszcze żadnego kodu — załóż pierwszy wyżej.</Text>}
      {dane?.kody?.map((k) => (
        <KodKarta key={k.code} k={k} onEdit={() => setForm({
          code: k.code, creator_name: k.creator || "", creator_handle: k.handle || "",
          contact_email: k.email || "", free_slots: String(k.free_slots ?? 5),
          free_days: String(k.free_days ?? 30), commission_pct: String(k.commission_pct ?? 50),
        })} />
      ))}
    </View>
  );
}

function KodKarta({ k, onEdit }: { k: ReferralStats; onEdit: () => void }) {
  const [mail, setMail] = useState(false);
  const [skopiowano, setSkopiowano] = useState(false);

  function kopiuj() {
    try {
      (navigator as any).clipboard.writeText(k.mail);
      setSkopiowano(true);
      setTimeout(() => setSkopiowano(false), 2000);
    } catch { /* zostaje zaznaczanie tekstu */ }
  }

  return (
    <Card>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
        <View style={{ flex: 1 }}>
          <Text style={s.code}>{k.code}{!k.active && <Text style={s.off}>  WYŁĄCZONY</Text>}</Text>
          <Text style={s.sub}>{k.creator}{k.handle ? ` · ${k.handle}` : ""}{k.email ? ` · ${k.email}` : ""}</Text>
        </View>
        <MetalButton label="Edytuj" size="sm" onPress={onEdit} />
      </View>

      <View style={s.stats}>
        <Stat v={String(k.nowe)} k="nowe konta" />
        <Stat v={String(k.razem)} k="razem" />
        <Stat v={String(k.placacy)} k="płaci teraz" />
        <Stat v={String(k.platnosci)} k="płatności" />
      </View>
      <Text style={s.line}>Darmowe premium: {k.free_used}/{k.free_slots} miejsc · {k.free_days} dni</Text>
      <Text style={s.line}>Wpływy: {zl(k.brutto)} brutto · {zl(k.netto)} netto{k.zwroty ? ` · zwroty: ${k.zwroty}` : ""}</Text>
      <Text style={[s.line, s.prowizja]}>Prowizja {k.commission_pct}%: {zl(k.prowizja)}</Text>
      {k.inne_waluty > 0 && <Text style={s.line}>Płatności w innej walucie: {k.inne_waluty} (do przeliczenia ręcznie)</Text>}
      <Text style={s.line} selectable>Link do bio: portevo.pl/k/{k.code}</Text>

      <View style={{ flexDirection: "row", gap: 8, marginTop: 12 }}>
        <MetalButton label={mail ? "Schowaj mail" : "Pokaż mail do twórcy"} size="sm" tone="amber"
                     active={mail} onPress={() => setMail((v) => !v)} />
        {mail && Platform.OS === "web" && (
          <MetalButton label={skopiowano ? "Skopiowano" : "Kopiuj"} size="sm" onPress={kopiuj} />
        )}
      </View>
      {mail && <Text style={s.mail} selectable>{k.mail}</Text>}
    </Card>
  );
}

function Stat({ v, k }: { v: string; k: string }) {
  return (
    <View style={s.stat}>
      <Text style={s.statV}>{v}</Text>
      <Text style={s.statK}>{k}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  head: { flexDirection: "row", alignItems: "center", gap: 12, paddingHorizontal: 15, paddingVertical: 14 },
  headOn: { borderColor: "rgba(255,180,84,.45)", backgroundColor: "rgba(255,180,84,.06)" },
  title: { color: C.text, fontSize: 14.5, fontWeight: "800", letterSpacing: -0.2 },
  sub: { color: C.dim, fontSize: 11.5, marginTop: 2 },
  arrow: { color: C.amber, fontSize: 20, fontWeight: "700" },
  arrowOn: { transform: [{ rotate: "90deg" }] },

  cardTitle: { color: C.text, fontSize: 14, fontWeight: "800" },
  grid: { flexDirection: "row", flexWrap: "wrap", gap: 9, marginTop: 10 },
  label: { color: C.dim, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.7, marginBottom: 5 },
  input: {
    backgroundColor: C.elev, borderWidth: 1, borderColor: C.border, borderRadius: 11,
    paddingHorizontal: 11, paddingVertical: 9, color: C.text, fontSize: 13.5,
  },
  note: { color: C.muted, fontSize: 12, lineHeight: 17, marginTop: 10 },
  err: { color: C.red, fontSize: 12.5, lineHeight: 18 },

  monthRow: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 14 },
  month: { color: C.text, fontSize: 15, fontWeight: "800", letterSpacing: 0.5 },

  code: { color: C.amber, fontSize: 16, fontWeight: "800", letterSpacing: 1 },
  off: { color: C.red, fontSize: 10, letterSpacing: 0.6 },
  stats: { flexDirection: "row", gap: 8, marginTop: 12 },
  stat: {
    flex: 1, backgroundColor: C.elev, borderRadius: 10, paddingVertical: 9, alignItems: "center",
    borderWidth: 1, borderColor: C.border,
  },
  statV: { color: C.text, fontSize: 17, fontWeight: "800" },
  statK: { color: C.dim, fontSize: 10, marginTop: 2, textAlign: "center" },
  line: { color: C.muted, fontSize: 12.3, lineHeight: 18, marginTop: 6 },
  prowizja: { color: C.green, fontWeight: "800" },
  mail: {
    color: C.text, fontSize: 12.3, lineHeight: 18, marginTop: 10, padding: 12,
    backgroundColor: C.elev, borderRadius: 10, borderWidth: 1, borderColor: C.border,
  },
});
