/** Logo instrumentu: parqet → financialmodelingprep → kółko z inicjałami i kolorem z tickera. */
import React, { useState } from "react";
import { Image, StyleSheet, Text, View } from "react-native";

export default function Logo({
  ticker, size = 38, radius, name,
}: {
  ticker: string;
  size?: number;
  /** promień rogów; domyślnie kółko */
  radius?: number;
  /** nazwa spółki — używana do inicjałów, gdy nie ma logo */
  name?: string;
}) {
  const base = (ticker || "?").split(".")[0].toUpperCase();
  const [step, setStep] = useState(0);
  const urls = [
    `https://assets.parqet.com/logos/symbol/${base}?format=png&size=64`,
    `https://financialmodelingprep.com/image-stock/${base}.png`,
  ];
  const box = { width: size, height: size, borderRadius: radius ?? size / 2 };

  if (step >= urls.length) {
    let h = 0;
    for (const ch of base) h = (h * 31 + ch.charCodeAt(0)) % 360;
    // Azjatyckie tickery są numeryczne („2330.TW"), więc „23" w kółku nic nie mówi.
    // Gdy znamy nazwę, bierzemy z niej inicjały — Taiwan Semiconductor daje „TS".
    const initials = (/^\d+$/.test(base) && name)
      ? name.trim().split(/\s+/).slice(0, 2).map((w) => w[0]).join("").toUpperCase()
      : base.slice(0, 2);
    return (
      <View style={[s.fallback, box, { backgroundColor: `hsl(${h},52%,58%)` }]}>
        <Text style={[s.txt, { fontSize: size * 0.34 }]}>{initials}</Text>
      </View>
    );
  }
  return (
    <Image
      source={{ uri: urls[step] }}
      style={[s.img, box, { padding: size * 0.08 }]}
      resizeMode="contain"
      onError={() => setStep((x) => x + 1)}
    />
  );
}

const s = StyleSheet.create({
  img: { backgroundColor: "#fff" },
  fallback: { alignItems: "center", justifyContent: "center" },
  txt: { color: "#0a0d13", fontWeight: "800" },
});
