/** Mapa korelacji — czy pozycje portfela naprawdę chodzą osobno.
 *
 *  Sama macierz jest ładna, ale mało kto umie z niej cokolwiek wyczytać. Dlatego
 *  najpierw dostajemy odpowiedź („kto realnie dywersyfikuje, a kto dubluje resztę"),
 *  a macierz jest dopiero pod spodem, dla tych, którzy chcą sprawdzić.
 */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { AllocationCorrelation, getAllocationCorrelation } from "../../api";
import { useAuth } from "../../auth/AuthContext";
import { openCompany } from "../../companyRouter";
import Logo from "../../components/Logo";
import { usePortfolioVersion } from "../../refresh";
import { C, fmtPLN0, T } from "../../theme";
import { Bar, Card } from "../../ui";

export default function CorrelationSection() {
  const { locked } = useAuth();
  const isLocked = locked("alloc.correlation");
  const [d, setD] = useState<AllocationCorrelation | null>(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [open, setOpen] = useState<string | null>(null);

  // te same dane co reszta zakładki — muszą przeliczyć się po imporcie
  const wersja = usePortfolioVersion();
  useEffect(() => {
    if (isLocked) return;
    let alive = true;
    setLoading(true);
    getAllocationCorrelation()
      .then((r) => { if (alive) setD(r); })
      .catch((e) => { if (alive) setErr(e?.message || "Nie udało się policzyć korelacji"); })
      .finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; };
  }, [isLocked, wersja]);

  const toggle = useCallback((k: string) => setOpen((o) => (o === k ? null : k)), []);

  if (isLocked) return <CorrSkeleton />;
  if (loading) return <Card style={s.pad}><ActivityIndicator color={C.green} /></Card>;
  if (err) return <Card style={s.pad}><Text style={s.dim}>{err}</Text></Card>;
  if (!d || d.empty) {
    return <Card style={s.pad}><Text style={s.dim}>{d?.reason || "Brak danych."}</Text></Card>;
  }

  return (
    <>
      {/* ---- odpowiedź na górze, dane pod spodem */}
      <Card style={s.pad}>
        {d.avg != null && (
          <>
            <View style={{ flexDirection: "row", alignItems: "baseline", gap: 9 }}>
              <Text style={[s.big, { color: corrColor(d.avg) }]}>{d.avg.toFixed(2)}</Text>
              <Text style={s.bigLabel}>średnia korelacja</Text>
            </View>
            <View style={{ marginTop: 11 }}>
              <Bar pct={Math.max(2, Math.abs(d.avg) * 100)} color={corrColor(d.avg)} />
              <View style={s.scale}>
                <Text style={s.scaleTxt}>0 — chodzą osobno</Text>
                <Text style={s.scaleTxt}>1 — jak jeden walor</Text>
              </View>
            </View>
          </>
        )}
        {!!d.verdict && <Text style={s.verdict}>{d.verdict}</Text>}
        <Text style={s.cardHint}>
          Liczone z {d.sessions} wspólnych sesji dla {d.tickers.length} największych pozycji.
        </Text>
      </Card>

      {(d.diversifier || d.crowd) && (
        <View style={s.twoCards}>
          {d.diversifier && (
            <Card style={[s.pad, s.half, { borderColor: "rgba(47,212,138,.3)" }]}>
              <Text style={s.halfLabel}>NAJLEPIEJ DYWERSYFIKUJE</Text>
              <View style={s.halfRow}>
                <Logo ticker={d.diversifier.ticker} size={26} />
                <Text style={s.halfTicker} numberOfLines={1}>{d.diversifier.ticker}</Text>
              </View>
              <Text style={[s.halfValue, { color: C.green }]}>{d.diversifier.avg.toFixed(2)}</Text>
              <Text style={s.halfHint}>
                Chodzi najbardziej własnym rytmem — to on realnie obniża wahania całości.
              </Text>
            </Card>
          )}
          {d.crowd && (
            <Card style={[s.pad, s.half, { borderColor: "rgba(255,180,84,.3)" }]}>
              <Text style={s.halfLabel}>NAJBARDZIEJ W TŁUMIE</Text>
              <View style={s.halfRow}>
                <Logo ticker={d.crowd.ticker} size={26} />
                <Text style={s.halfTicker} numberOfLines={1}>{d.crowd.ticker}</Text>
              </View>
              <Text style={[s.halfValue, { color: C.amber }]}>{d.crowd.avg.toFixed(2)}</Text>
              <Text style={s.halfHint}>
                Powiela ruch reszty portfela — dokładanie go niewiele zmienia.
              </Text>
            </Card>
          )}
        </View>
      )}

      {/* ---- ranking per spółka */}
      {d.per_ticker.length > 0 && (
        <Card style={[s.pad, { marginTop: 11 }]}>
          <Text style={s.cardTitle}>Każda pozycja osobno</Text>
          <Text style={s.cardHint}>
            Średnia korelacja danego waloru z resztą portfela. Im niżej na liście,
            tym bardziej dana pozycja powiela to, co już masz.
          </Text>
          {d.per_ticker.map((p, i) => (
            <Pressable key={p.ticker} onPress={() => toggle(`p${i}`)} style={s.row}>
              <View style={{ flexDirection: "row", alignItems: "center", gap: 11 }}>
                <Pressable onPress={() => openCompany(p.ticker)} hitSlop={6}>
                  <View style={s.logoRing}><Logo ticker={p.ticker} size={30} /></View>
                </Pressable>
                <View style={{ flex: 1 }}>
                  <Text style={s.rowTicker} numberOfLines={1}>{p.ticker}</Text>
                  <Text style={s.rowName} numberOfLines={1}>{p.name || " "}</Text>
                </View>
                <Text style={[s.rowVal, { color: corrColor(p.avg) }]}>{p.avg.toFixed(2)}</Text>
              </View>
              <View style={{ marginTop: 8 }}>
                <Bar pct={Math.max(2, Math.abs(p.avg) * 100)} color={corrColor(p.avg)} delay={i * 30} />
              </View>
              {open === `p${i}` && (
                <View style={s.rowOpen}>
                  <Text style={s.rowExplain}>
                    {p.avg < 0.25
                      ? "Ta pozycja chodzi niemal niezależnie od reszty portfela. To ona sprawia, "
                        + "że całość spada łagodniej niż jej najsłabsze składniki."
                      : p.avg < 0.5
                      ? "Umiarkowane powiązanie z resztą — częściowo się dubluje, ale nadal wnosi "
                        + "coś własnego."
                      : "Ta pozycja porusza się bardzo podobnie do reszty portfela. Dokładanie do "
                        + "niej kolejnych pieniędzy zwiększa ryzyko, nie zmniejsza."}
                  </Text>
                  <View style={s.miniRow}>
                    <Mini label="Najmocniej z" value={p.max.toFixed(2)} />
                    <Mini label="Najsłabiej z" value={p.min.toFixed(2)} />
                    <Mini label="Wartość" value={`${fmtPLN0(p.value_pln)} zł`} />
                  </View>
                  <Pressable onPress={() => openCompany(p.ticker)} hitSlop={6} style={{ marginTop: 11 }}>
                    <Text style={s.goTxt}>Otwórz kartę spółki →</Text>
                  </Pressable>
                </View>
              )}
            </Pressable>
          ))}
        </Card>
      )}

      {/* ---- macierz */}
      <Card style={[s.pad, { marginTop: 11 }]}>
        <Text style={s.cardTitle}>Pełna macierz</Text>
        <Text style={s.cardHint}>
          Im czerwieńsze pole, tym mocniej para chodzi razem. Zieleń oznacza ruch
          w przeciwne strony — najcenniejszy rodzaj dywersyfikacji.
        </Text>
        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginTop: 12 }}>
          <View>
            <View style={{ flexDirection: "row" }}>
              <View style={s.cell} />
              {d.tickers.map((t) => (
                <View key={t} style={s.cell}>
                  <Text style={s.cellHead} numberOfLines={1}>{short(t)}</Text>
                </View>
              ))}
            </View>
            {d.tickers.map((t, i) => (
              <View key={t} style={{ flexDirection: "row" }}>
                <View style={s.cell}>
                  <Text style={s.cellHead} numberOfLines={1}>{short(t)}</Text>
                </View>
                {d.matrix[i].map((v, j) => (
                  <View key={j} style={[s.cell, { backgroundColor: cellBg(v, i === j) }]}>
                    <Text style={[s.cellTxt, v != null && Math.abs(v) > 0.6 && { color: C.text }]}>
                      {v == null ? "–" : v.toFixed(2)}
                    </Text>
                  </View>
                ))}
              </View>
            ))}
          </View>
        </ScrollView>

        {d.highest.length > 0 && (
          <View style={{ marginTop: 18 }}>
            <Text style={s.cardTitle}>Pary chodzące najbliżej siebie</Text>
            {d.highest.slice(0, 4).map((p) => (
              <View key={p.a + p.b} style={s.pairRow}>
                <Logo ticker={p.a} size={20} />
                <Logo ticker={p.b} size={20} />
                <Text style={s.pairTxt} numberOfLines={1}>{p.a}  ·  {p.b}</Text>
                <Text style={[s.pairVal, { color: corrColor(p.corr) }]}>{p.corr.toFixed(2)}</Text>
              </View>
            ))}
          </View>
        )}
      </Card>
    </>
  );
}

function Mini({ label, value }: { label: string; value: string }) {
  return (
    <View style={{ flex: 1 }}>
      <Text style={s.miniLabel}>{label}</Text>
      <Text style={s.miniValue}>{value}</Text>
    </View>
  );
}

export function CorrSkeleton() {
  return (
    <Card style={s.pad}>
      <View style={{ width: 130, height: 26, borderRadius: 6, backgroundColor: "rgba(255,255,255,.09)" }} />
      <View style={{ marginTop: 18, gap: 4 }}>
        {[0, 1, 2, 3].map((r) => (
          <View key={r} style={{ flexDirection: "row", gap: 4 }}>
            {[0, 1, 2, 3, 4].map((c) => (
              <View key={c} style={[s.cell, { backgroundColor: cellBg(r === c ? 1 : 0.3 + c * 0.13, r === c) }]} />
            ))}
          </View>
        ))}
      </View>
    </Card>
  );
}

/* -------------------------------------------------------------- drobiazgi */

const short = (t: string) => t.replace(/\.(US|PL|DE|UK|FR|NL)$/i, "").slice(0, 6);

function corrColor(v: number) {
  if (v > 0.7) return C.red;
  if (v > 0.45) return C.amber;
  return C.green;
}

function cellBg(v: number | null, diagonal: boolean) {
  if (diagonal) return "rgba(255,255,255,.07)";
  if (v == null) return "rgba(255,255,255,.02)";
  const a = Math.min(0.42, Math.abs(v) * 0.42);
  return v >= 0 ? `rgba(255,92,108,${a})` : `rgba(47,212,138,${a})`;
}

const s = StyleSheet.create({
  pad: { padding: 16 },
  dim: { color: C.muted, ...T.small },
  cardTitle: { color: C.text, fontSize: 14, fontWeight: "800" },
  cardHint: { color: C.dim, fontSize: 12, lineHeight: 18, marginTop: 5 },

  big: { fontSize: 34, fontWeight: "800", letterSpacing: -1.4 },
  bigLabel: { color: C.muted, fontSize: 13, fontWeight: "600" },
  scale: { flexDirection: "row", justifyContent: "space-between", marginTop: 6 },
  scaleTxt: { color: C.dim, fontSize: 10 },
  verdict: { color: C.muted, fontSize: 12.5, lineHeight: 19, marginTop: 14 },

  twoCards: { flexDirection: "row", gap: 10, marginTop: 11 },
  half: { flex: 1 },
  halfLabel: { color: C.dim, fontSize: 9, fontWeight: "800", letterSpacing: 0.7 },
  halfRow: { flexDirection: "row", alignItems: "center", gap: 8, marginTop: 10 },
  halfTicker: { color: C.text, fontSize: 12.5, fontWeight: "800", flex: 1 },
  halfValue: { fontSize: 22, fontWeight: "800", marginTop: 8, letterSpacing: -0.8 },
  halfHint: { color: C.dim, fontSize: 11, lineHeight: 16, marginTop: 7 },

  row: { paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: "rgba(33,41,56,.6)" },
  logoRing: {
    width: 38, height: 38, borderRadius: 19, alignItems: "center", justifyContent: "center",
    borderWidth: 1.5, borderColor: C.border2, overflow: "hidden", backgroundColor: C.elev,
  },
  rowTicker: { color: C.text, fontSize: 13.5, fontWeight: "800" },
  rowName: { color: C.dim, fontSize: 11, marginTop: 2 },
  rowVal: { fontSize: 15, fontWeight: "800" },
  rowOpen: {
    marginTop: 12, backgroundColor: "rgba(255,255,255,.03)", borderRadius: 12, padding: 12,
  },
  rowExplain: { color: C.muted, fontSize: 12.3, lineHeight: 19 },
  miniRow: { flexDirection: "row", gap: 10, marginTop: 12 },
  miniLabel: { color: C.dim, fontSize: 9.5, fontWeight: "700" },
  miniValue: { color: C.text, fontSize: 12.5, fontWeight: "800", marginTop: 3 },
  goTxt: { color: C.accent, fontSize: 12.5, fontWeight: "700" },

  cell: {
    width: 52, height: 34, alignItems: "center", justifyContent: "center",
    marginRight: 4, marginBottom: 4, borderRadius: 7,
  },
  cellHead: { color: C.dim, fontSize: 10.5, fontWeight: "800" },
  cellTxt: { color: C.muted, fontSize: 11, fontWeight: "700" },

  pairRow: {
    flexDirection: "row", alignItems: "center", gap: 8, paddingVertical: 9,
    borderBottomWidth: 1, borderBottomColor: "rgba(33,41,56,.6)",
  },
  pairTxt: { color: C.muted, fontSize: 12.5, fontWeight: "600", flex: 1, marginLeft: 4 },
  pairVal: { fontSize: 13, fontWeight: "800" },
});
