/** Usunięcie konta — twardy wymóg App Store dla każdej aplikacji z rejestracją.
 *
 *  Trzy decyzje, które warto znać:
 *
 *  1. Potwierdzenie przez PRZEPISANIE słowa, nie przez `Alert`. `Alert.prompt`
 *     istnieje tylko na iOS, a ten sam ekran musi zadziałać w przeglądarce
 *     (patrz [[jeden-kod-telefon-i-web]]). Przy okazji to lepsza bariera niż „OK".
 *  2. Mówimy wprost, co zniknie — recenzent Apple sprawdza, czy kasowanie jest
 *     realne, a nie czy tylko wylogowuje.
 *  3. Po skasowaniu nie wracamy do listy: aplikacja przechodzi w stan gościa.
 */
import React, { useState } from "react";
import {
  ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, View,
} from "react-native";
import { deleteAccount } from "../api";
import { C, T } from "../theme";
import { Card, MetalButton } from "../ui";

import Icon from "../ui/Icon";
const SLOWO = "USUWAM";

export default function DeleteAccountScreen({
  email, onClose, onDeleted,
}: {
  email: string;
  onClose: () => void;
  /** wywoływane po skasowaniu — miejsce na wyczyszczenie sesji w aplikacji */
  onDeleted: () => void;
}) {
  const [txt, setTxt] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [done, setDone] = useState(false);

  const gotowe = txt.trim().toUpperCase() === SLOWO;

  async function usun() {
    setBusy(true);
    setErr("");
    try {
      await deleteAccount();
      setDone(true);
    } catch (e: any) {
      setErr(e?.message || "Nie udało się skasować konta. Spróbuj później.");
      setBusy(false);
    }
  }

  if (done) {
    return (
      <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onDeleted}>
        <View style={s.root}>
          <View style={s.center}>
            <Icon name="ptaszek" size={30} color={C.green} />
            <Text style={s.doneTitle}>Konto zostało usunięte</Text>
            <Text style={s.doneTxt}>
              Skasowaliśmy konto razem z portfelem, operacjami i ustawieniami.
              Nic nie zostało po naszej stronie.
            </Text>
            <MetalButton label="Zamknij" tone="steel" full style={{ marginTop: 24 }}
                         onPress={onDeleted} />
          </View>
        </View>
      </Modal>
    );
  }

  return (
    <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}>
      <View style={s.root}>
        <View style={s.bar}>
          <Text style={s.barTitle}>Usuń konto</Text>
          <Pressable onPress={onClose} hitSlop={12} style={s.close} disabled={busy}>
            <Icon name="zamknij" size={15} color={C.muted} />
          </Pressable>
        </View>

        <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
          <Card style={s.warn}>
            <Text style={s.warnTitle}>Tego nie da się cofnąć</Text>
            <Text style={s.warnTxt}>
              Kasujemy konto <Text style={s.mail}>{email}</Text> i wszystko, co do niego należy:
            </Text>
            <View style={{ marginTop: 12, gap: 8 }}>
              {[
                "portfel: pozycje, operacje i wgrane raporty",
                "historię zamkniętych transakcji",
                "obserwowane spółki i ustawienia aplikacji",
                "dostęp do wersji premium, jeśli go masz",
              ].map((x) => (
                <View key={x} style={s.li}>
                  <Text style={s.dot}>•</Text>
                  <Text style={s.liTxt}>{x}</Text>
                </View>
              ))}
            </View>
            <Text style={[s.warnTxt, { marginTop: 14 }]}>
              Nie odzyskamy tych danych na Twoją prośbę — kopii nie zostawiamy.
              Jeśli chcesz zachować historię, najpierw zapisz swoje raporty.
            </Text>
          </Card>

          <Text style={s.label}>
            Wpisz <Text style={s.slowo}>{SLOWO}</Text>, żeby potwierdzić
          </Text>
          <TextInput
            value={txt}
            onChangeText={setTxt}
            autoCapitalize="characters"
            autoCorrect={false}
            editable={!busy}
            placeholder={SLOWO}
            placeholderTextColor={C.dim}
            style={s.input}
          />

          {!!err && <Text style={s.err}>{err}</Text>}

          <MetalButton
            label={busy ? "Kasuję…" : "Usuń konto na zawsze"}
            tone="red" active={gotowe} liquid={gotowe} full
            disabled={!gotowe || busy}
            style={{ marginTop: 18 }}
            onPress={usun}
          />
          <MetalButton label="Zostaw konto" tone="steel" full style={{ marginTop: 10 }}
                       disabled={busy} onPress={onClose} />

          {busy && <ActivityIndicator color={C.red} style={{ marginTop: 18 }} />}

          <Text style={s.foot}>
            Subskrypcję kupioną w App Store wyłącz osobno w ustawieniach Apple —
            usunięcie konta u nas nie anuluje płatności po ich stronie.
          </Text>
        </ScrollView>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 28 },
  bar: {
    flexDirection: "row", alignItems: "center", gap: 10,
    paddingHorizontal: 16, paddingVertical: 13,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  barTitle: { flex: 1, color: C.text, ...T.h2 },
  close: {
    width: 32, height: 32, borderRadius: 10, alignItems: "center", justifyContent: "center",
    backgroundColor: C.cardHi,
  },
  closeTxt: { color: C.muted, fontSize: 15, fontWeight: "700" },

  wrap: { padding: 20, paddingBottom: 48, maxWidth: 620, width: "100%", alignSelf: "center" },
  warn: { padding: 17, borderColor: "rgba(255,92,108,.4)", backgroundColor: C.redDim },
  warnTitle: { color: C.red, ...T.h2 },
  warnTxt: { color: C.muted, fontSize: 14, lineHeight: 21, marginTop: 9 },
  mail: { color: C.text, fontWeight: "800" },
  li: { flexDirection: "row", gap: 9 },
  dot: { color: C.red, fontSize: 14, lineHeight: 20 },
  liTxt: { flex: 1, color: C.muted, fontSize: 14, lineHeight: 20 },

  label: { color: C.text, ...T.small, marginTop: 24 },
  slowo: { color: C.red, fontWeight: "800", letterSpacing: 1 },
  input: {
    marginTop: 9, borderWidth: 1, borderColor: C.border2, borderRadius: 13,
    backgroundColor: C.elev, color: C.text, paddingHorizontal: 14, paddingVertical: 12,
    fontSize: 16, fontWeight: "700", letterSpacing: 1.5,
  },
  err: { color: C.red, ...T.small, marginTop: 12, lineHeight: 18 },
  foot: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 24 },

  doneIcon: { color: C.green, fontSize: 44, fontWeight: "800" },
  doneTitle: { color: C.text, ...T.h1, marginTop: 14, textAlign: "center" },
  doneTxt: { color: C.muted, fontSize: 14, lineHeight: 21, marginTop: 10, textAlign: "center" },
});
