/** Tło „spadające gwiazdy" — smugi zorzy przelatujące w poprzek ekranu.
 *
 *  Port shadera z komponentu `animated-shader-background` (three.js). Sam shader
 *  przenosi się jeden do jednego, bo to czysty GLSL bez tekstur; trzy.js był tam
 *  tylko sposobem na wyświetlenie prostokąta, a u nas robi to `ShaderCanvas`.
 *
 *  Dwie zmiany wymuszone przez telefon i starszy dialekt GLSL:
 *    • `tanh` nie istnieje w GLSL ES 1.0 — liczymy go wprost z `exp`
 *    • pętla ma 24 przebiegi zamiast 35, a obraz powstaje w jednej trzeciej
 *      rozdzielczości: to najcięższy shader ze wszystkich teł, a rozmyte smugi
 *      i tak nie tracą na miękkości
 */
import React, { useRef } from "react";
import ShaderCanvas, { f, rgb } from "./ShaderCanvas";

const ITER = 24;

function frag(bg: [number, number, number], gain: number) {
  return `
precision highp float;

uniform float u_time;
uniform vec2  u_res;

const float ITER = ${ITER}.0;
const vec3  BG   = vec3(${f(bg[0])}, ${f(bg[1])}, ${f(bg[2])});
const float GAIN = ${f(gain)};

float rand(vec2 n) { return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453); }

float noise(vec2 p) {
  vec2 ip = floor(p);
  vec2 u = fract(p);
  u = u * u * (3.0 - 2.0 * u);
  float res = mix(
    mix(rand(ip), rand(ip + vec2(1.0, 0.0)), u.x),
    mix(rand(ip + vec2(0.0, 1.0)), rand(ip + vec2(1.0, 1.0)), u.x), u.y);
  return res * res;
}

float fbm(vec2 x) {
  float v = 0.0;
  float a = 0.3;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 3; ++i) {
    v += a * noise(x);
    x = rot * x * 2.0 + shift;
    a *= 0.4;
  }
  return v;
}

/** Zamiennik funkcji tanh — o jest zawsze dodatnie, więc wystarczy jedna gałąź. */
vec4 tanh4(vec4 x) {
  vec4 e = exp(-2.0 * clamp(x, 0.0, 12.0));
  return (1.0 - e) / (1.0 + e);
}

void main() {
  vec2 shake = vec2(sin(u_time * 1.2) * 0.005, cos(u_time * 2.1) * 0.005);
  vec2 p = ((gl_FragCoord.xy + shake * u_res) - u_res * 0.5) / u_res.y
           * mat2(6.0, -4.0, 4.0, 6.0);
  vec2 v;
  vec4 o = vec4(0.0);

  float f = 2.0 + fbm(p + vec2(u_time * 5.0, 0.0)) * 0.5;

  for (float i = 0.0; i < ITER; i++) {
    v = p + cos(i * i + (u_time + p.x * 0.08) * 0.025 + i * vec2(13.0, 11.0)) * 3.5
          + vec2(sin(u_time * 3.0 + i) * 0.003, cos(u_time * 3.5 - i) * 0.003);
    float tailNoise = fbm(v + vec2(u_time * 0.5, i)) * 0.3 * (1.0 - (i / ITER));
    vec4 aurora = vec4(
      0.1 + 0.3 * sin(i * 0.2 + u_time * 0.4),
      0.3 + 0.5 * cos(i * 0.3 + u_time * 0.5),
      0.7 + 0.3 * sin(i * 0.4 + u_time * 0.3),
      1.0);
    vec4 contribution = aurora * exp(sin(i * i + u_time * 0.8))
                        / length(max(v, vec2(v.x * f * 0.015, v.y * 1.5)));
    float thinness = smoothstep(0.0, 1.0, i / ITER) * 0.6;
    o += contribution * (1.0 + tailNoise * 0.8) * thinness;
  }

  // Barwy zorzy schodzą chwilami poniżej zera (cosinus w kanale zielonym), a potęga
  // z ujemnej podstawy to w GLSL wynik nieokreślony — bez tego przycięcia
  // kanały wychodziły jako NaN i całość świeciła na czerwono zamiast na błękit.
  o = max(o, vec4(0.0));
  // dzielnik przeskalowany razem z liczbą przebiegów, żeby jasność została ta sama
  o = tanh4(pow(o / (100.0 * ITER / 35.0), vec4(1.6)));
  gl_FragColor = vec4(BG + o.rgb * GAIN, 1.0);
}
`;
}

export default function AuroraEffect({
  fps = 20, downscale = 3, gain = 2.2, bg,
}: {
  fps?: number;
  downscale?: number;
  gain?: number;
  bg: [number, number, number];
}) {
  const locs = useRef<any>({});
  return (
    <ShaderCanvas
      frag={frag(bg, gain)}
      fps={fps}
      downscale={downscale}
      setup={(gl, prog) => {
        locs.current = {
          time: gl.getUniformLocation(prog, "u_time"),
          res: gl.getUniformLocation(prog, "u_res"),
        };
      }}
      frame={({ gl, w, h, t }) => {
        gl.uniform1f(locs.current.time, t);
        gl.uniform2f(locs.current.res, w, h);
      }}
    />
  );
}

export { rgb };
