/** Tło „shader" — miękkie plamy światła oddychające w ciemności.
 *
 *  Port komponentu `background-paper-shaders` (react-three-fiber). Struktura
 *  została z oryginału: falowanie płaszczyzny, wzór z dwóch nakładających się
 *  fal, mieszanie dwóch barw, poświata do środka i pierścień energii. Trzy.js
 *  robił tam tylko za wyświetlacz — u nas prostokąt daje `ShaderCanvas`.
 *
 *  Odstępstwo od kodu z promptu: częstotliwości fal są dużo niższe (5/4 zamiast
 *  20/15), a paleta to karmazyn i morska zieleń zamiast pomarańczu z bielą.
 *  Tak wygląda obrazek, który wybrałeś — oryginalne liczby dają na telefonie
 *  gęstą pasiastą kratę zamiast rozmytych plam.
 */
import React, { useRef } from "react";
import ShaderCanvas, { f, rgb } from "./ShaderCanvas";

function frag(
  bg: [number, number, number], c1: [number, number, number], c2: [number, number, number],
  ring: [number, number, number], ringRadius: number,
) {
  return `
precision highp float;

uniform float u_time;
uniform vec2  u_res;

const vec3  BG     = vec3(${f(bg[0])}, ${f(bg[1])}, ${f(bg[2])});
const vec3  C1     = vec3(${f(c1[0])}, ${f(c1[1])}, ${f(c1[2])});
const vec3  C2     = vec3(${f(c2[0])}, ${f(c2[1])}, ${f(c2[2])});
const vec3  RING   = vec3(${f(ring[0])}, ${f(ring[1])}, ${f(ring[2])});
const float RADIUS = ${f(ringRadius)};

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float t = u_time * 0.35;
  float intensity = 1.0 + sin(u_time * 0.7) * 0.3;

  // odpowiednik falowania płaszczyzny z oryginalnego vertex shadera
  uv.y += sin(uv.x * 10.0 + t) * 0.02 * intensity;
  uv.x += cos(uv.y * 8.0 + t * 1.5) * 0.015 * intensity;

  float n = sin(uv.x * 5.0 + t) * cos(uv.y * 4.0 + t * 0.8);
  n += sin(uv.x * 9.0 - t * 2.0) * cos(uv.y * 7.0 + t * 1.2) * 0.5;

  // ostrzejsze przejście między barwami — przy zwykłym mieszaniu wszystko lądowało
  // w błotnistej połowie zamiast w wyraźnych plamach karmazynu i zieleni
  vec3 col = mix(C1, C2, smoothstep(-0.55, 0.55, n));
  // rozbielenie tylko na grzbietach fali — przy mocniejszym barwy robiły się błotniste
  col = mix(col, vec3(1.0), pow(abs(n), 3.0) * 0.18 * intensity);

  // poświata do środka — na brzegach obraz gaśnie do tła apki
  vec2 d = (uv - 0.5) * vec2(u_res.x / u_res.y, 1.0);
  float glow = pow(clamp(1.0 - length(d) * 1.9, 0.0, 1.0), 2.8);

  // pierścień energii: jasność pulsuje, a obrót widać po przesuwającym się przetarciu
  float ang = atan(d.y, d.x);
  float r = length(d);
  float band = smoothstep(0.06, 0.0, abs(r - RADIUS));
  float wear = 0.55 + 0.45 * sin(ang * 3.0 + u_time * 1.1);
  float pulse = 0.5 + sin(u_time * 1.6) * 0.3;

  vec3 outCol = BG + col * glow * 0.85 + RING * band * wear * pulse * 0.30;
  gl_FragColor = vec4(outCol, 1.0);
}
`;
}

export default function PaperShaderEffect({
  fps = 22, downscale = 2, bg,
  color1 = "#c2334d", color2 = "#3aa8a0", ring = "#ff5722", radius = 0.42,
}: {
  fps?: number;
  downscale?: number;
  bg: [number, number, number];
  color1?: string;
  color2?: string;
  ring?: string;
  radius?: number;
}) {
  const locs = useRef<any>({});
  return (
    <ShaderCanvas
      frag={frag(bg, rgb(color1), rgb(color2), rgb(ring), radius)}
      fps={fps}
      downscale={downscale}
      setup={(gl, prog) => {
        locs.current = {
          time: gl.getUniformLocation(prog, "u_time"),
          res: gl.getUniformLocation(prog, "u_res"),
        };
      }}
      frame={({ gl, w, h, t }) => {
        gl.uniform1f(locs.current.time, t);
        gl.uniform2f(locs.current.res, w, h);
      }}
    />
  );
}
