/** Szczegóły pojedynczej spółki — wykres, wskaźniki z wyjaśnieniami i porównanie z branżą.
 *
 *  Wskaźniki przychodzą z serwera jako lista obiektów (etykieta, wartość, opis, mediana
 *  podobnych spółek, czy „mniej znaczy lepiej"), więc ten ekran renderuje je generycznie.
 *  Dołożenie kolejnego wskaźnika to jeden wpis w `market.METRICS` — tutaj nic nie trzeba ruszać.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator, Modal, Platform, Pressable, SafeAreaView, ScrollView, StatusBar, StyleSheet,
  Text, View,
} from "react-native";
import {
  Company, getCompany, getInsiderzySpolki, getInstrumentChart, getOperations, InsiderzySpolki,
  InstrumentChart, Metric, Operation, Position, Trade, TransakcjaInsidera, watchAdd, watchRemove,
} from "../api";
import { useAuth } from "../auth/AuthContext";
import type { FaceMark } from "../components/ChartFaces";
import ChartFullscreen from "../components/ChartFullscreen";
import Logo from "../components/Logo";
import PortfolioChart, { ChartMode } from "../components/PortfolioChart";
import { chartHeight, COLUMN_MAX, useLayout } from "../layout";
import { C, fmtBig, fmtCur, fmtPct, fmtPLN, plColor, sgnPLN, T } from "../theme";
import { Card, FadeIn, MetalButton, Press, SectionTitle, Segmented } from "../ui";
import Icon from "../ui/Icon";
import { openInsiders } from "../insiderRouter";
import EtfXrayCard from "./tools/EtfXrayCard";
import CompanyInsiders from "./tools/insiders/CompanyInsiders";
import Profile from "./tools/insiders/Profile";
import { Avatar, dzien, FEATURE as INSIDERS, kwota, useInsiderPrefs } from "./tools/insiders/shared";

/** Wysokość wykresu spółki — półtora raza więcej niż na przeglądzie portfela. */
const CHART_H = 360;

const MODES = [
  { id: "value", label: "Linia" },
  { id: "candle", label: "Świece" },
  { id: "compare", label: "Porównanie" },
];

/** Benchmarki dla pojedynczej spółki — te same nazwy co przy portfelu, tylko
 *  pobierane wprost z notowań (ten sam endpoint co wykres spółki).
 *
 *  Porównujemy ruch procentowy w walucie notowań, bez przeliczania na złotówki:
 *  na wykresie spółki pytanie brzmi „czy bije rynek", a nie „ile bym miał w PLN".
 *  WIG20 idzie przez ETF Beta WIG20TR — Yahoo ma dla samego indeksu tylko dziś.
 */
const CMP: Record<string, { label: string; color: string; symbol: string }> = {
  sp500: { label: "S&P 500", color: "#5b8cff", symbol: "^GSPC" },
  nasdaq100: { label: "Nasdaq 100", color: "#67e8f9", symbol: "^NDX" },
  wig20: { label: "WIG20 TR", color: "#ffb454", symbol: "ETFBW20TR.WA" },
  gold: { label: "Złoto", color: "#e6c15a", symbol: "GC=F" },
  btc: { label: "Bitcoin", color: "#f7931a", symbol: "BTC-USD" },
};

/** „OPEN BUY 0.1821 @ 57.38" — raport XTB trzyma wolumen i cenę tylko w komentarzu. */
const TRADE_NOTE = /(OPEN|CLOSE)\s+(BUY|SELL)\s+([\d.,]+)\s*@\s*([\d.,]+)/i;
const num = (s: string | undefined) => {
  const v = parseFloat((s || "").replace(",", "."));
  return Number.isFinite(v) ? v : null;
};

/** Twoje transakcje na tym walorze, wyliczone z historii operacji.
 *
 *  Panel podaje je gotowe w `company.trades`, ale tylko w nowszej wersji — a apka
 *  bywa świeższa niż serwer na komputerze. Ta ścieżka korzysta z endpointu operacji,
 *  który istniał od zawsze, więc znaczniki działają niezależnie od wersji panelu.
 *
 *  Ticker portfela i symbol notowań to dwa różne zapisy tego samego waloru
 *  (GDX.UK vs GDX.L), więc dopasowujemy po obu, a w ostateczności po samej nazwie
 *  przed kropką. Ryzyko pomyłki jest znikome: różne rynki tej samej spółki i tak
 *  mają wspólną historię, a inne walory mają inny rdzeń tickera.
 */
function tradesFromOps(ops: Operation[], keys: string[]): Trade[] {
  const full = new Set(keys.filter(Boolean).map((k) => k.toUpperCase()));
  const base = new Set([...full].map((k) => k.split(".")[0]));
  return ops
    .filter((o) => {
      if (o.type !== "Stock purchase" && o.type !== "Stock sell") return false;
      const t = (o.ticker || "").toUpperCase();
      return !!t && (full.has(t) || base.has(t.split(".")[0]));
    })
    .map((o) => {
      const m = TRADE_NOTE.exec(o.comment || "");
      return {
        time: o.time,
        side: o.type === "Stock purchase" ? "buy" : "sell",
        amount: o.amount,
        volume: m ? num(m[3]) : null,
        price: m ? num(m[4]) : null,
      } as Trade;
    });
}

const RANGES = [
  { id: "1d", label: "1D" }, { id: "5d", label: "5D" }, { id: "1m", label: "1M" },
  { id: "3m", label: "3M" }, { id: "6m", label: "6M" }, { id: "ytd", label: "YTD" },
  { id: "1y", label: "1R" }, { id: "5y", label: "5L" }, { id: "max", label: "MAX" },
];

/** Ile historii i jak gęstej daje każdy zakres — w sekundach.
 *
 *  Stąd wiadomo, czym odpowiedzieć na prośby wykresu: przy dojechaniu do początku
 *  serii szukamy zakresu sięgającego GŁĘBIEJ, a przy mocnym przybliżeniu — takiego
 *  z krótszym krokiem, ale wciąż obejmującego oglądane okno. Wartości muszą zgadzać
 *  się z tabelą `RANGES` w `bot/portfolio/market.py`, bo to ona decyduje, o co
 *  naprawdę pytamy Yahoo.
 */
const DEPTH: Record<string, { back: number; step: number }> = {
  "1d": { back: 1 * 86400, step: 300 },
  "5d": { back: 5 * 86400, step: 900 },
  "1m": { back: 31 * 86400, step: 86400 },
  "3m": { back: 93 * 86400, step: 86400 },
  "6m": { back: 186 * 86400, step: 86400 },
  ytd: { back: 200 * 86400, step: 86400 },
  "1y": { back: 366 * 86400, step: 86400 },
  "5y": { back: 1830 * 86400, step: 7 * 86400 },
  max: { back: 60 * 366 * 86400, step: 30 * 86400 },
};

const REKOMENDACJE: Record<string, { label: string; color: string }> = {
  strong_buy: { label: "zdecydowanie kupuj", color: C.green },
  buy: { label: "kupuj", color: C.green },
  hold: { label: "trzymaj", color: C.amber },
  underperform: { label: "poniżej rynku", color: C.red },
  sell: { label: "sprzedawaj", color: C.red },
};

const TYP: Record<string, string> = {
  EQUITY: "akcje", ETF: "ETF", CRYPTOCURRENCY: "krypto",
  INDEX: "indeks", MUTUALFUND: "fundusz",
};

export default function CompanyScreen({
  symbol: symbolProp, onClose, onWatchChange, obserwujOdRazu,
}: {
  symbol: string | null;
  onClose: () => void;
  onWatchChange?: () => void;
  /** Wejście z przycisku „Dodaj do obserwowanych" na podstronie pozycjonowanej.
   *  Spółka trafia na listę sama, zaraz po wczytaniu karty — bez tego człowiek
   *  kliknął konkretną obietnicę, a dostał zwykłe okno i musiał szukać serduszka. */
  obserwujOdRazu?: boolean;
}) {
  const { wide, modalColumn } = useLayout();
  // Symbol trzymamy w stanie, a nie tylko w propsie: z profilu insidera można
  // przejść do INNEJ spółki, a karta nie może w tym celu otwierać drugiego okna
  // obok siebie (na iPhonie by się nie pokazało).
  const [symbol, setSymbol] = useState<string | null>(symbolProp);
  useEffect(() => { setSymbol(symbolProp); }, [symbolProp]);
  const { locked } = useAuth();
  const insLocked = locked(INSIDERS);
  const insPrefs = useInsiderPrefs();
  const [ins, setIns] = useState<InsiderzySpolki | null>(null);
  const [profil, setProfil] = useState<string | null>(null);
  const [grupa, setGrupa] = useState<FaceMark[] | null>(null);
  const [data, setData] = useState<Company | null>(null);
  const [chart, setChart] = useState<InstrumentChart | null>(null);
  const [range, setRange] = useState("1y");
  const [mode, setMode] = useState<ChartMode>("value");
  // podbicie kasuje przybliżenie — tylko przy zmianie waloru albo świadomym
  // kliknięciu w zakres, nie przy danych dociągniętych przez sam wykres
  const [reset, setReset] = useState(0);
  const [loading, setLoading] = useState(true);
  const [chartBusy, setChartBusy] = useState(false);
  const [open, setOpen] = useState<string | null>(null);
  const [fullscreen, setFullscreen] = useState(false);
  // porównanie z rynkiem: wybrane benchmarki i ich notowania (klucz „id|zakres")
  const [cmpOn, setCmpOn] = useState<string[]>([]);
  const [cmpData, setCmpData] = useState<Record<string, InstrumentChart | null>>({});
  const [err, setErr] = useState("");
  const [ops, setOps] = useState<Operation[]>([]);

  const loadChart = useCallback(async (sym: string, r: string) => {
    setChartBusy(true);
    try {
      const c = await getInstrumentChart(sym, r);
      setChart(c?.error ? null : c);
    } catch { setChart(null); } finally { setChartBusy(false); }
  }, []);

  useEffect(() => {
    if (!symbol) return;
    setData(null); setChart(null); setLoading(true); setErr("");
    setRange("1y"); setMode("value"); setOpen(null); setFullscreen(false);
    setReset((k) => k + 1);
    (async () => {
      try {
        const [c] = await Promise.all([getCompany(symbol), loadChart(symbol, "1y")]);
        if (c?.error) setErr(c.error);
        setData(c);
      } catch (e: any) {
        setErr(e?.message || "Nie udało się pobrać danych");
      } finally { setLoading(false); }
    })();
    // historia operacji — zapas na wypadek panelu bez pola `trades`
    getOperations(1000).then(setOps).catch(() => setOps([]));
    // insiderzy: osobno i bez czekania — karta spółki nie może stać na nich
    setIns(null); setProfil(null); setGrupa(null);
    let aktualne = true;
    getInsiderzySpolki(symbol)
      .then((r) => { if (aktualne) setIns(r); })
      .catch(() => { if (aktualne) setIns(null); });
    return () => { aktualne = false; };
  }, [symbol]);

  /** Twarze na wykres: klasy wybrane w panelu insiderów, sprzedaże tylko na życzenie.
   *  Bez premium każda transakcja to zamazane kółko z podpisem „Insajder". */
  const faces = useMemo<FaceMark[]>(() => {
    if (!ins?.trades?.length || !insPrefs.chart) return [];
    const out: FaceMark[] = [];
    for (const t of ins.trades) {
      if (t.side === "sell" && !insPrefs.sells) continue;
      if ("locked" in t || insLocked) {
        out.push({ key: t.uid, date: t.date, price: t.price ?? null, side: t.side,
                   blur: (t as any).blur || "", label: "Insajder", locked: true, weight: 0,
                   who: (t as any).who || (t as any).person });
        continue;
      }
      const tr = t as TransakcjaInsidera;
      const p = ins.persons[tr.person];
      if (!p || !insPrefs.cats.includes(p.cat)) continue;
      const kw = tr.hi ?? tr.lo ?? 0;
      out.push({
        key: tr.uid, date: tr.date, price: tr.source === "sec" ? tr.price : null,
        side: tr.side, photo: p.photo, blur: p.blur, label: p.short || p.name, who: tr.person,
        // katalog ważności wygrywa z kwotą: Pelosi za 100 tys. przed prezesem za milion
        weight: (p.rank ? 1e12 - p.rank * 1e9 : 0) + Math.min(kw, 9e8),
        ref: tr,
      });
    }
    return out;
  }, [ins, insPrefs.chart, insPrefs.sells, insPrefs.cats, insLocked]);

  /* Notowania benchmarków — dociągamy dopiero, gdy ktoś włączy porównanie, i tylko
     te, których jeszcze nie mamy dla tego zakresu. Benchmark, którego nie da się
     pobrać, zapisujemy jako `null`, żeby nie próbować w kółko. */
  const cmpRef = useRef(cmpData);
  cmpRef.current = cmpData;
  useEffect(() => {
    if (mode !== "compare" || !cmpOn.length) return;
    let alive = true;
    (async () => {
      for (const id of cmpOn) {
        const key = `${id}|${range}`;
        if (key in cmpRef.current) continue;
        let got: InstrumentChart | null = null;
        try {
          const c = await getInstrumentChart(CMP[id].symbol, range);
          got = c?.error ? null : c;
        } catch { got = null; }
        if (!alive) return;
        setCmpData((p) => ({ ...p, [key]: got }));
      }
    })();
    return () => { alive = false; };
  }, [mode, cmpOn, range]);

  /** Benchmarki przełożone na siatkę czasu spółki.
   *
   *  Indeksy notują się w innych godzinach i innych dniach niż spółka (a złoto
   *  i bitcoin prawie non stop), więc dla każdego punktu spółki bierzemy OSTATNI
   *  wcześniejszy kurs benchmarku. Zanim benchmark w ogóle wystartuje, zostaje
   *  dziura — wykres po prostu jej nie rysuje.
   */
  const benchSeries = useMemo(() => {
    if (mode !== "compare" || !chart?.ts?.length) return undefined;
    const out: Record<string, (number | null)[]> = {};
    for (const id of cmpOn) {
      const b = cmpData[`${id}|${range}`];
      if (!b?.ts?.length) continue;
      const arr: (number | null)[] = new Array(chart.ts.length).fill(null);
      let j = 0;
      for (let i = 0; i < chart.ts.length; i++) {
        while (j + 1 < b.ts.length && b.ts[j + 1] <= chart.ts[i]) j++;
        // kurs sprzed więcej niż tygodnia to już nie jest ten sam moment rynku
        arr[i] = b.ts[j] <= chart.ts[i] && chart.ts[i] - b.ts[j] < 7 * 86400
          ? b.values[j] : null;
      }
      out[id] = arr;
    }
    return out;
  }, [mode, chart, cmpOn, cmpData, range]);

  function toggleCmp(id: string) {
    setCmpOn((prev) => prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]);
  }

  function pickMode(x: ChartMode) {
    setMode(x);
    // pierwsze wejście w porównanie bez wybranego benchmarku — podpowiedz S&P 500
    if (x === "compare" && !cmpOn.length) setCmpOn(["sp500"]);
  }

  /** Znaczniki transakcji: z panelu, jeśli je podaje, inaczej policzone na miejscu. */
  const trades = useMemo<Trade[]>(() => {
    if (data?.trades?.length) return data.trades;
    if (!ops.length) return [];
    return tradesFromOps(ops, [data?.position?.ticker || "", data?.symbol || "", symbol || ""]);
  }, [data, ops, symbol]);

  /* Automatyczne dodanie do obserwowanych po wejściu z podstrony SEO.
     `useRef` pilnuje, żeby stało się to raz na spółkę: efekt zależy od `data`,
     które zmienia się przy każdym przełączeniu serduszka — bez tego strażnika
     ręczne usunięcie z listy natychmiast dodawałoby ją z powrotem. */
  const dodane = useRef<string | null>(null);
  useEffect(() => {
    if (!obserwujOdRazu || !data || data.watched) return;
    if (dodane.current === data.symbol) return;
    dodane.current = data.symbol;
    toggleWatch();
  }, [obserwujOdRazu, data]);

  async function toggleWatch() {
    if (!data) return;
    const next = !data.watched;
    setData({ ...data, watched: next });
    try {
      if (next) await watchAdd({ symbol: data.symbol, name: data.name, type: data.type,
                                 exchange: data.exchange, currency: data.currency });
      else await watchRemove(data.symbol);
      onWatchChange?.();
    } catch { setData({ ...data, watched: !next }); }
  }

  const cur = data?.currency || chart?.currency || "USD";
  const money = (v: number) => fmtCur(v, cur, Math.abs(v) < 10 ? 4 : 2);
  // okno spółki zakrywa cały ekran, więc na komputerze samo pilnuje swojej kolumny
  const chartW = modalColumn - 36 - 28;
  const up = (chart && chart.values.length
    ? chart.values[chart.values.length - 1] >= chart.prev_close
    : (data?.change_pct ?? 0) >= 0);

  /** Dotknięcie twarzy. Bez premium — do narzędzia (okno karty najpierw się
   *  zamyka: drugie pełnoekranowe okno obok tego nie pokazałoby się na iPhonie). */
  const naTwarz = useCallback((marks: FaceMark[]) => {
    const dalej = () => {
      if (insLocked || marks.some((m) => m.locked)) {
        onClose();
        setTimeout(() => openInsiders(), 380);
        return;
      }
      if (marks.length === 1 && marks[0].ref) setProfil(marks[0].ref.person);
      else setGrupa(marks);
    };
    if (fullscreen) { setFullscreen(false); setTimeout(dalej, 380); } else dalej();
  }, [insLocked, onClose, fullscreen]);

  /** Wykres poprosił o dane, których w obecnym zakresie nie ma.
   *
   *  „older" — palec dojechał do początku notowań i ciągnie dalej w przeszłość:
   *  bierzemy najbliższy zakres sięgający wyraźnie głębiej.
   *  „finer" — przybliżenie zeszło do garstki punktów: bierzemy zakres o krótszym
   *  kroku (dzień → kwadrans → 5 minut), ale tylko taki, który wciąż OBEJMUJE
   *  oglądane okno; zakresy Yahoo liczą się od dziś wstecz, więc gęstych słupków
   *  sprzed pół roku po prostu nie ma.
   *
   *  Zakres w pasku zmienia się razem z danymi — użytkownik ma widzieć, co ogląda.
   *  `reset` zostaje bez zmian, więc wykres wraca dokładnie w to samo miejsce w czasie.
   */
  const needData = useCallback((need: { side: "older" | "finer"; from: number; to: number }) => {
    const sym = data?.symbol || symbol;
    const cur = DEPTH[range];
    if (!sym || !cur) return;
    const ids = RANGES.map((r) => r.id);
    const now = Date.now() / 1000;
    const pick = need.side === "older"
      ? ids.find((id) => (DEPTH[id]?.back ?? 0) > cur.back * 1.4)
      : ids.filter((id) => DEPTH[id] && DEPTH[id].step < cur.step
                           && now - DEPTH[id].back <= need.from)
           // spośród gęstszych bierzemy najgrubszy — najmniejszy skok naraz
           .sort((a, b) => DEPTH[b].step - DEPTH[a].step)[0];
    if (!pick || pick === range) return;
    setRange(pick);
    loadChart(sym, pick);
  }, [data, symbol, range, loadChart]);

  /** Wykres spółki — ten sam kod w karcie i na pełnym ekranie. */
  const renderChart = (w: number, h: number, zoomable = false) => {
    if (chartBusy && !chart) {
      return (
        <View style={{ height: h + 26, alignItems: "center", justifyContent: "center" }}>
          <ActivityIndicator color={C.green} />
        </View>
      );
    }
    if (!chart) {
      return (
        <View style={{ height: h + 26, alignItems: "center", justifyContent: "center" }}>
          <Text style={s.dim}>Brak notowań w tym zakresie</Text>
        </View>
      );
    }
    return (
      <PortfolioChart
        ts={chart.ts} values={chart.values} baseline={chart.prev_close}
        tzOffset={0} mode={mode} height={h} width={w} positive={up}
        fmtValue={money} trades={trades} zoomable={zoomable}
        twr={mode === "compare" ? chart.values : undefined}
        bench={benchSeries} benchMeta={CMP}
        baselineLabel={chart.intraday ? "wczorajsze zamknięcie" : "początek zakresu"}
        resetKey={reset}
        faces={faces} onFacePress={naTwarz}
        // dosypywanie danych ma sens tam, gdzie da się przesuwać i przybliżać;
        // w trybie porównania siatka musi zostać wspólna z benchmarkami
        onNeedData={zoomable && mode !== "compare" ? needData : undefined}
      />
    );
  };

  const modeBar = (
    <Segmented options={MODES} value={mode} liquid tone="green"
               onChange={(x) => pickMode(x as ChartMode)} />
  );
  const cmpBar = (
    <View style={s.benchRow}>
      {Object.entries(CMP).map(([id, b]) => (
        <MetalButton key={id} label={b.label} size="sm" round accent={b.color}
                     active={cmpOn.includes(id)} onPress={() => toggleCmp(id)} />
      ))}
    </View>
  );
  const rangeBar = (
    <ScrollView horizontal showsHorizontalScrollIndicator={false}
                contentContainerStyle={s.ranges}>
      {RANGES.map((r) => (
        <MetalButton key={r.id} label={r.label} size="sm" tone="green" liquid
                     active={range === r.id}
                     onPress={() => {
                       const sym = data?.symbol || symbol;
                       if (!sym || r.id === range) return;
                       setRange(r.id); setReset((k) => k + 1); loadChart(sym, r.id);
                     }} />
      ))}
    </ScrollView>
  );

  return (
    <Modal visible={!!symbol} animationType="slide" onRequestClose={onClose} transparent={false}>
      {/* okno pełnoekranowe rysuje się POD wcięciem ekranu i paskiem stanu — bez tego
          „Wróć" ląduje pod notchem telefonu i nie da się w niego trafić palcem */}
      <SafeAreaView style={s.root}>
        <View style={s.bar}>
          <MetalButton onPress={onClose} label="‹  Wróć" />
          {!!data && !data.error && (
            <MetalButton tone="red" round active={data.watched} onPress={toggleWatch}>
              <Icon name={data.watched ? "serceOn" : "serce"} size={18}
                    color={data.watched ? C.red : C.muted} />
            </MetalButton>
          )}
        </View>

        {loading ? (
          <View style={s.center}>
            <ActivityIndicator color={C.green} size="large" />
            <Text style={s.dim}>Wczytuję {symbol}…</Text>
          </View>
        ) : err && !data?.price ? (
          <View style={s.center}>
            <Text style={s.errTitle}>{err}</Text>
            <Text style={s.dim}>Symbol: {symbol}</Text>
          </View>
        ) : (
          <ScrollView contentContainerStyle={[s.wrap, wide && s.column]}
                      showsVerticalScrollIndicator={false}>
            <FadeIn>
              <View style={s.head}>
                <Logo ticker={data!.symbol} size={44} />
                <View style={{ flex: 1, marginLeft: 12 }}>
                  <Text style={s.sym}>{data!.symbol}</Text>
                  <Text style={s.name} numberOfLines={2}>{data!.name}</Text>
                </View>
              </View>

              <Text style={s.price}>{data!.price != null ? money(data!.price) : "—"}</Text>
              <View style={s.chipRow}>
                {data!.change_pct != null && (
                  <View style={[s.chip, { backgroundColor: data!.change_pct >= 0 ? C.greenDim : C.redDim }]}>
                    <Text style={[s.chipTxt, { color: plColor(data!.change_pct) }]}>
                      {fmtPct(data!.change_pct)}   dzisiaj
                    </Text>
                  </View>
                )}
                <Text style={s.meta} numberOfLines={1}>
                  {[TYP[data!.type] || data!.type, data!.exchange, data!.sector]
                    .filter(Boolean).join(" · ")}
                </Text>
              </View>
            </FadeIn>

            <FadeIn delay={80}>
              <Card style={{ marginTop: 16 }} padded={false}>
                <View style={{ padding: 14, paddingBottom: 4 }}>
                  {/* wykres spółki jest półtora raza wyższy od portfelowego — to on jest
                      tu treścią główną, a nie dodatkiem do liczb */}
                  {renderChart(chartW, chartHeight(CHART_H, wide, chartW))}

                  <View style={{ marginTop: 10 }}>{modeBar}</View>
                </View>
                {mode === "compare" && cmpBar}
                {/* zakresy, a przy nich lupa na pełny ekran */}
                <View style={s.rangeRow}>
                  <View style={{ flex: 1 }}>{rangeBar}</View>
                  <MetalButton label="⤢" size="sm" tone="green" round
                               onPress={() => setFullscreen(true)}
                               textStyle={{ fontSize: 15, lineHeight: 19 }}
                               style={{ marginRight: 10, marginBottom: 10 }} />
                </View>
              </Card>
            </FadeIn>

            <CompanyInsiders data={ins} locked={insLocked}
                             onPerson={(id) => setProfil(id)}
                             onLocked={() => { onClose(); setTimeout(() => openInsiders(), 380); }} />

            {!!data!.position && <PositionCard p={data!.position!} money={money} />}

            <RangeBar low={data!.week52_low} high={data!.week52_high} price={data!.price}
                      money={money} />

            {(data!.target_price != null || !!data!.recommendation) && (
              <FadeIn delay={130}>
                <SectionTitle hint={data!.analysts ? `${data!.analysts} analityków` : undefined}>
                  Opinia analityków
                </SectionTitle>
                <Card style={s.posCard}>
                  {!!data!.recommendation && (
                    <Line k="Rekomendacja"
                          v={REKOMENDACJE[data!.recommendation]?.label || data!.recommendation}
                          color={REKOMENDACJE[data!.recommendation]?.color} />
                  )}
                  {data!.target_price != null && (
                    <Line k="Średnia cena docelowa" v={money(data!.target_price)}
                          sub={data!.price ? `${fmtPct((data!.target_price / data!.price - 1) * 100)} od dzisiejszej ceny` : undefined}
                          color={data!.price && data!.target_price >= data!.price ? C.green : C.red}
                          last />
                  )}
                </Card>
              </FadeIn>
            )}

            <Metrics metrics={data!.metrics} currency={cur} peers={data!.peers}
                     open={open} setOpen={setOpen} />

            {!!data!.summary && (
              <FadeIn delay={160}>
                <SectionTitle hint="Opis z profilu spółki">Czym się zajmuje</SectionTitle>
                <Card>
                  <Text style={s.summary}>{data!.summary}</Text>
                  <Text style={s.summaryMeta}>
                    {[data!.industry, data!.country,
                      data!.employees ? `${data!.employees.toLocaleString("pl-PL")} pracowników` : ""]
                      .filter(Boolean).join(" · ")}
                  </Text>
                </Card>
              </FadeIn>
            )}

            {/* Fundusz? To pod wykresem jest najciekawsza część — co siedzi w środku. */}
            <EtfXrayCard symbol={data!.symbol} name={data!.name} type={data!.type} />

            <Text style={s.foot}>
              Dane: Yahoo Finance · notowania i rekomendacje mają charakter wyłącznie informacyjny i nie stanowią doradztwa inwestycyjnego.
            </Text>
          </ScrollView>
        )}

        <ChartFullscreen
          visible={fullscreen}
          onClose={() => setFullscreen(false)}
          title={data?.symbol || symbol || ""}
          subtitle={[data?.name, data?.price != null ? money(data.price) : null]
            .filter(Boolean).join(" · ")}
          hint="Przeciągnij, aby przesuwać · szczypnij albo kółko myszy, aby przybliżyć · dwa stuknięcia wracają do całości · przytrzymaj, aby odczytać wartość"
          controls={
            <>
              {modeBar}
              {mode === "compare" && cmpBar}
              {rangeBar}
            </>
          }
        >
          {({ width: w, height: h }) => renderChart(w, h, true)}
        </ChartFullscreen>

        {!!grupa && (
          <WyborInsidera marks={grupa} persons={ins?.persons || {}}
                         onPick={(pid) => { setGrupa(null); setProfil(pid); }}
                         onClose={() => setGrupa(null)} />
        )}
        <Profile personId={profil} onClose={() => setProfil(null)}
                 onOpenCompany={(t) => {
                   setProfil(null);
                   if (t && t !== (data?.symbol || symbol)) setSymbol(t);
                 }} />
      </SafeAreaView>
    </Modal>
  );
}

/** Kilka twarzy w jednym miejscu wykresu — lista do wyboru.
 *
 *  Zwykły widok nad kartą, nie okno: kolejne okno otwarte nad oknem karty
 *  bywa na iPhonie kłopotliwe, a to jest chwilowa ściągawka na trzy wiersze. */
function WyborInsidera({ marks, persons, onPick, onClose }: {
  marks: FaceMark[];
  persons: Record<string, any>;
  onPick: (personId: string) => void;
  onClose: () => void;
}) {
  const lista = marks.map((m) => m.ref as TransakcjaInsidera).filter(Boolean);
  return (
    <Pressable style={s.pickBackdrop} onPress={onClose}>
      <Pressable style={s.pickCard} onPress={() => {}}>
        <Text style={s.pickTitle}>W tym miejscu wykresu</Text>
        {lista.map((t) => {
          const p = persons[t.person];
          const kupno = t.side === "buy";
          return (
            <Press key={t.uid} scaleTo={0.985} onPress={() => onPick(t.person)} style={s.pickRow}>
              <Avatar person={p} size={38} ring={kupno ? "buy" : "sell"} />
              <View style={{ flex: 1, marginLeft: 10 }}>
                <Text style={s.pickName} numberOfLines={1}>{p?.name || "Insider"}</Text>
                <Text style={s.pickSub} numberOfLines={1}>
                  <Text style={{ color: kupno ? C.green : C.red, fontWeight: "800" }}>
                    {kupno ? "kupno" : "sprzedaż"}
                  </Text>
                  {" · "}{kwota(t)} · {dzien(t.date, true)}
                </Text>
              </View>
              <Text style={s.pickGo}>›</Text>
            </Press>
          );
        })}
        <MetalButton label="Zamknij" full onPress={onClose} style={{ marginTop: 10 }} />
      </Pressable>
    </Pressable>
  );
}

/** Twoja pozycja w tej spółce.
 *
 *  Na wierzchu procent, nie kwota. Kwota mówi, ile zarobiłeś; procent mówi, czy
 *  było warto — i to jego szuka się wzrokiem, wchodząc na ekran spółki. Kwota
 *  i wydany kapitał lecą obok, drobnym drukiem, żeby liczba miała skalę.
 */
function PositionCard({
  p, money,
}: { p: Position; money: (v: number) => string }) {
  return (
    <FadeIn delay={110}>
      <SectionTitle hint="Ta spółka jest w Twoim portfelu">Twoja pozycja</SectionTitle>
      <Card style={s.posCard}>
        <View style={s.plHead}>
          <View style={{ flex: 1 }}>
            <Text style={s.plHeadK}>Zysk na tej pozycji</Text>
            <Text style={s.plHeadSub} numberOfLines={1}>
              {sgnPLN(p.pl_pln)} z {fmtPLN(p.cost_pln)} wydanych
            </Text>
          </View>
          <View style={[s.plPill, { backgroundColor: p.pl_pct >= 0 ? C.greenDim : C.redDim }]}>
            <Text style={[s.plPillTxt, { color: plColor(p.pl_pct) }]}>{fmtPct(p.pl_pct)}</Text>
          </View>
        </View>

        <Line k="Liczba akcji"
              v={p.shares.toLocaleString("pl-PL", { maximumFractionDigits: 4 })} />
        <Line k="Średnia cena zakupu" v={fmtCur(p.avg_open, p.currency)}
              sub={`teraz ${money(p.price)}`} />
        <Line k="Wartość" v={fmtPLN(p.value_pln)} />
        <Line k="Wynik" v={sgnPLN(p.pl_pln)} sub={fmtPct(p.pl_pct)}
              color={plColor(p.pl_pln)} subColor={plColor(p.pl_pct)} />
        <Line k="Wynik po kosztach" v={sgnPLN(p.pl_net_pln)} sub={fmtPct(p.pl_net_pct)}
              color={plColor(p.pl_net_pln)} subColor={plColor(p.pl_net_pct)} last />
      </Card>
    </FadeIn>
  );
}

/** Pasek 52 tygodni — gdzie dziś jest cena na tle rocznego zakresu. */
function RangeBar({
  low, high, price, money,
}: { low: number | null; high: number | null; price: number | null; money: (v: number) => string }) {
  if (low == null || high == null || price == null || high <= low) return null;
  const pos = Math.max(0, Math.min(1, (price - low) / (high - low)));
  return (
    <FadeIn delay={120}>
      <SectionTitle hint="Gdzie jest dzisiejsza cena na tle ostatniego roku">
        Zakres 52 tygodni
      </SectionTitle>
      <Card>
        <View style={s.rangeTrack}>
          <View style={[s.rangeDot, { left: `${pos * 100}%` }]} />
        </View>
        <View style={s.rangeLabels}>
          <Text style={s.rangeLow}>{money(low)}</Text>
          <Text style={s.rangeHigh}>{money(high)}</Text>
        </View>
      </Card>
    </FadeIn>
  );
}

/** Wskaźniki pogrupowane tematycznie; dotknięcie wiersza pokazuje wyjaśnienie. */
function Metrics({
  metrics, currency, peers, open, setOpen,
}: {
  metrics: Metric[]; currency: string; peers?: { symbol: string; name: string }[];
  open: string | null; setOpen: (k: string | null) => void;
}) {
  const groups: string[] = [];
  for (const m of metrics) if (m.value != null && !groups.includes(m.group)) groups.push(m.group);
  if (!groups.length) return null;

  const fmt = (m: Metric, v: number) =>
    m.fmt === "money" ? fmtBig(v, currency)
      : m.fmt === "pct" ? (m.signed ? fmtPct(v * 100)
          : `${(v * 100).toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`)
      : m.fmt === "ratio" ? `${v.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}×`
      : v.toLocaleString("pl-PL", { maximumFractionDigits: 2 });

  return (
    <>
      <SectionTitle hint="Dotknij wiersza, aby zobaczyć, co dana liczba oznacza">
        Kluczowe dane
      </SectionTitle>

      {groups.map((g) => (
        <View key={g} style={{ marginBottom: 12 }}>
          <Text style={s.groupTitle}>{g}</Text>
          <Card padded={false} style={{ paddingHorizontal: 14, paddingVertical: 2 }}>
            {metrics.filter((m) => m.group === g && m.value != null).map((m, i, arr) => {
              const v = m.value as number;
              // porównanie liczymy tylko dla krotności i marż — kwot nie da się
              // uczciwie zestawić między firmami różnej wielkości
              const rel = m.peer != null && m.peer !== 0 ? v / m.peer - 1 : null;
              const better = rel == null || m.better === "none" ? null
                : m.better === "low" ? rel < 0 : rel > 0;
              return (
                <Press key={m.key} scaleTo={0.995}
                       onPress={() => setOpen(open === m.key ? null : m.key)}
                       style={[s.metric, i === arr.length - 1 && { borderBottomWidth: 0 }]}>
                  <View style={s.metricTop}>
                    <Text style={s.metricLabel}>{m.label}</Text>
                    <Text style={s.metricValue}>{fmt(m, v)}</Text>
                  </View>
                  {m.peer != null && (
                    <View style={s.metricPeer}>
                      <Text style={s.metricPeerTxt}>
                        podobne spółki: {fmt(m, m.peer)}
                      </Text>
                      {rel != null && Math.abs(rel) > 0.01 && (
                        <Text style={[s.metricRel,
                                      { color: better == null ? C.muted : better ? C.green : C.red }]}>
                          {rel > 0 ? "+" : ""}{(rel * 100).toFixed(0)}%
                          {better == null ? "" : better ? "  lepiej" : "  gorzej"}
                        </Text>
                      )}
                    </View>
                  )}
                  {open === m.key && <Text style={s.metricDesc}>{m.desc}</Text>}
                </Press>
              );
            })}
          </Card>
        </View>
      ))}

      {!!peers?.length && (
        <Text style={s.peersNote}>
          „Podobne spółki" to mediana z: {peers.map((p) => p.symbol).join(", ")}.
          To punkt odniesienia, a nie cała branża — spółki różnią się modelem biznesu.
        </Text>
      )}
    </>
  );
}

function Line({
  k, v, sub, color, subColor, last,
}: {
  k: string; v: string; sub?: string; color?: string; subColor?: string; last?: boolean;
}) {
  return (
    <View style={[s.line, last && { borderBottomWidth: 0 }]}>
      <Text style={s.lineK}>{k}</Text>
      <View style={{ alignItems: "flex-end", flexShrink: 1 }}>
        <Text style={[s.lineV, color ? { color } : null]}>{v}</Text>
        {!!sub && (
          <Text style={[s.lineSub, subColor ? { color: subColor, fontWeight: "700" } : null]}>
            {sub}
          </Text>
        )}
      </View>
    </View>
  );
}

