/** Tła ASCII — zdjęcie przemielone na siatkę znaków albo bloków, rysowane shaderem.
 *
 *  Odtworzenie efektów z 21st.dev/community/ascii (tryby `characters` i `dither`).
 *  Oryginał liczy to na Canvas2D: dzieli obraz na komórki, uśrednia jasność każdej
 *  i wstawia znak. W React Native Canvas2D nie ma, a liczenie komórek po pikselu
 *  w JS dałoby kilka klatek na sekundę — więc cały przepis siedzi w shaderze
 *  fragmentów i liczy go GPU:
 *
 *    1. `photo()`  — zdjęcie wpasowane w ekran (poza jego prostokątem jest czerń)
 *    2. komórka    — jasność w środku komórki + różnica z sąsiadami (`edgeEmphasis`)
 *    3. kształt    — bitmapa 3×5 znaku „0"/„1" albo próg Bayera (tryb `dither`)
 *    4. barwa      — nasycenie, odbarwienie, nakładka `tint` w trybie overlay
 *    5. post       — poświata, aberracja, linie obrazu, winieta, ziarno, glitch
 *    6. animacja   — `flicker`: losowe migotanie komórek w rytmie `speed`
 *
 *  Gdy GL nie wystartuje albo zdjęcie się nie wczyta, zostaje samo ciemne tło —
 *  apka nigdy nie kończy z czarnym ekranem.
 */
import { Asset } from "expo-asset";
import React, { useEffect, useRef, useState } from "react";
import { Platform } from "react-native";
import ShaderCanvas, { f, rgb } from "./ShaderCanvas";

export type AsciiPreset = {
  /** `require("...")` zdjęcia — motyw powinien odcinać się od tła */
  source: number;
  /** znaki 0/1 czy bloki dithera */
  mode: "characters" | "dither";
  /** bok komórki w pikselach rysowanego obrazu (mniej = drobniejsza kaszka) */
  cellPx: number;
  /** `true` = zdjęcie wypełnia ekran, `false` = pas o szerokości `fit` */
  cover: boolean;
  fit: number;
  /** środek zdjęcia w pionie (0 = góra, 1 = dół) */
  offsetY: number;
  /** korekty obrazu w skali z przepisu (100 = bez zmian) */
  contrast: number;
  brightness: number;
  saturation: number;
  grayscale: number;
  edge: number;
  coverage: number;
  invert: boolean;
  /** rzadkie znaki poza zdjęciem — dla teł, które nie wypełniają ekranu */
  ambient: number;
  /** ile widać samego zdjęcia pod siatką znaków (0–100) — odpowiednik `bgOpacity`
   *  z przepisu. Bez tego zostaje sama kaszka i motyw znika */
  photo: number;
  /** ile własnej barwy dokłada `ink` (0 = tylko kolory ze zdjęcia) */
  ink: string;
  inkMix: number;
  /** nakładka barwiąca: kolor + siła (0–100) */
  tint: string;
  tintOpacity: number;
  /** efekty końcowe, każdy 0–100 */
  bloom: number;
  chromatic: number;
  scanLines: number;
  vignette: number;
  filmGrain: number;
  glitch: number;
  /** animacja: siła migotania i tempo przeskoków na sekundę */
  flicker: number;
  speed: number;
  fps: number;
};

function frag(p: AsciiPreset, hasPhoto: boolean, bg: [number, number, number]) {
  const ink = rgb(p.ink);
  const tint = rgb(p.tint);
  return `
precision highp float;

uniform vec2  u_res;
uniform float u_time;
uniform sampler2D u_tex;
uniform vec4  u_rect;          // x, y, w, h — miejsce zdjęcia w układzie ekranu

const float CELL      = ${f(p.cellPx)};
const float CONTRAST  = ${f(p.contrast / 100)};
const float BRIGHT    = ${f(p.brightness / 100)};
const float SATUR     = ${f(p.saturation / 100)};
const float GRAY      = ${f(p.grayscale / 100)};
const float EDGE      = ${f(p.edge / 100)};
const float COVERAGE  = ${f(p.coverage / 100)};
const float INVERT    = ${p.invert ? "1.0" : "0.0"};
const float AMBIENT   = ${f(p.ambient / 100)};
const float PHOTO     = ${f(p.photo / 100)};
const float INK_MIX   = ${f(p.inkMix / 100)};
const float TINT_OP   = ${f(p.tintOpacity / 100)};
const float BLOOM     = ${f(p.bloom / 100)};
const float CHROM     = ${f(p.chromatic / 100)};
const float SCAN      = ${f(p.scanLines / 100)};
const float VIGNETTE  = ${f(p.vignette / 100)};
const float GRAIN     = ${f(p.filmGrain / 100)};
const float GLITCH    = ${f(p.glitch / 100)};
const float FLICKER   = ${f(p.flicker / 100)};
const float SPEED     = ${f(p.speed)};
const float DITHER    = ${p.mode === "dither" ? "1.0" : "0.0"};

const vec3 INK  = vec3(${f(ink[0])}, ${f(ink[1])}, ${f(ink[2])});
const vec3 TINT = vec3(${f(tint[0])}, ${f(tint[1])}, ${f(tint[2])});
const vec3 BG   = vec3(${f(bg[0])}, ${f(bg[1])}, ${f(bg[2])});

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

/** Zdjęcie wpasowane w ekran; poza jego prostokątem — czerń, czyli brak znaków. */
vec3 photo(vec2 uv) {
${hasPhoto ? `
  vec2 t = (uv - u_rect.xy) / u_rect.zw;
  if (t.x < 0.0 || t.x > 1.0 || t.y < 0.0 || t.y > 1.0) return vec3(0.0);
  vec4 c = texture2D(u_tex, t);
  return c.rgb * c.a;                     // przezroczyste tło = pustka
` : `
  // zapas bez tekstury: miękka plama światła, żeby efekt miał co rysować
  vec2 d = (uv - vec2(u_rect.x + u_rect.z * 0.5, u_rect.y + u_rect.w * 0.5)) / u_rect.zw;
  return vec3(smoothstep(0.75, 0.0, length(d)));
`}
}

float lum(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

/** Bitmapa znaku 3×5 — wiersz zapisany liczbą, bo GLSL ES 1.0 nie ma operacji
 *  bitowych ani tablic indeksowanych zmienną. */
float rowBits(float which, float r) {
  if (which < 0.5) {
    if (r < 0.5) return 7.0;              // ███   znak „0"
    if (r < 1.5) return 5.0;              // █ █
    if (r < 2.5) return 5.0;              // █ █
    if (r < 3.5) return 5.0;              // █ █
    return 7.0;                           // ███
  }
  if (r < 0.5) return 2.0;                //  █    znak „1"
  if (r < 1.5) return 6.0;                // ██
  if (r < 2.5) return 2.0;                //  █
  if (r < 3.5) return 2.0;                //  █
  return 7.0;                             // ███
}

float glyph(float which, vec2 p) {
  p = (p - 0.5) / 0.78 + 0.5;             // margines, żeby znaki się nie zlewały
  if (p.x < 0.0 || p.x > 1.0 || p.y < 0.0 || p.y > 1.0) return 0.0;
  vec2 g = clamp(floor(vec2(p.x * 3.0, p.y * 5.0)), vec2(0.0), vec2(2.0, 4.0));
  return floor(mod(rowBits(which, g.y) / pow(2.0, 2.0 - g.x), 2.0));
}

/** Uporządkowany próg Bayera 4×4 — klasyczny dithering, komórka zapala się cała. */
float bayer2(vec2 a) { a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }
float bayer4(vec2 a) { return bayer2(0.5 * a) * 0.25 + bayer2(a); }

void main() {
  vec2 uv = vec2(gl_FragCoord.x, u_res.y - gl_FragCoord.y) / u_res;
  vec2 cell = vec2(CELL) / u_res;

  // glitch: pojedyncze poziome pasy przeskakują w bok
  if (GLITCH > 0.0) {
    float band = floor(uv.y * 26.0);
    float gt = floor(u_time * 5.0);
    float hit = step(0.88, hash(vec2(band, gt)));
    uv.x = fract(uv.x + hit * (hash(vec2(band, gt + 1.0)) - 0.5) * GLITCH * 0.3);
  }

  vec2 id = floor(uv / cell);
  vec2 inCell = fract(uv / cell);
  vec2 center = (id + 0.5) * cell;

  vec3 src = photo(center);
  float l = lum(src);
  l = clamp((l - 0.5) * CONTRAST + 0.5 + BRIGHT, 0.0, 1.0);

  // kontury: różnica z sąsiednimi komórkami
  float lx = lum(photo(center + vec2(cell.x, 0.0)));
  float ly = lum(photo(center + vec2(0.0, cell.y)));
  l = clamp(l + (abs(l - lx) + abs(l - ly)) * EDGE, 0.0, 1.0);
  if (INVERT > 0.5) l = 1.0 - l;

  // pole tła: powolna fala przetykana losem — rzadkie znaki poza motywem
  if (AMBIENT > 0.0) {
    float wave = 0.5 + 0.5 * sin((uv.x * 3.0 + uv.y * 5.0) * 2.0 + u_time * 0.35);
    l = max(l, AMBIENT * (0.25 + 0.75 * wave) * hash(id + 11.0));
  }

  // migotanie — każda komórka gaśnie własnym rytmem
  float step_t = floor(u_time * SPEED);
  float v = l * (1.0 - FLICKER * hash(id + step_t));

  float lit = step(1.0 - COVERAGE, hash(id + 3.3)) * step(0.05, v);
  float which = step(0.5, hash(id * 1.7 + floor(step_t * 0.5)));

  // kanały R i B rysują kształt minimalnie inaczej — to daje aberrację
  vec3 mask;
  if (DITHER > 0.5) {
    float th = bayer4(id);
    mask = vec3(step(th + CHROM * 0.12, v), step(th, v), step(th - CHROM * 0.12, v)) * lit;
  } else {
    mask = vec3(
      glyph(which, inCell - vec2(CHROM * 0.22, 0.0)),
      glyph(which, inCell),
      glyph(which, inCell + vec2(CHROM * 0.22, 0.0))) * lit;
  }

  // barwa komórki bez jasności — dzięki temu ciemne partie też mają kolor
  float peak = max(src.r, max(src.g, src.b));
  vec3 chroma = peak > 0.02 ? src / peak : vec3(1.0);
  chroma = mix(vec3(1.0), chroma, SATUR);
  chroma = mix(chroma, vec3(1.0), GRAY);
  vec3 tone = mix(chroma, INK, INK_MIX);

  // Warstwa samego zdjęcia pod siatką — to ona niesie motyw, znaki są fakturą na nim.
  // Przy odwróceniu (jasne zdjęcie na ciemnej apce) pokazujemy tylko ciemne partie
  // oryginału, inaczej biała kartka rozświetliłaby cały ekran.
  vec3 shot = photo(uv);
  if (INVERT > 0.5) shot *= clamp((1.0 - lum(shot)) * 1.4, 0.0, 1.0);

  vec3 col = BG + shot * PHOTO + tone * mask * (0.30 + v * 0.95);
  col += tone * v * v * BLOOM * 0.16;                      // poświata jasnych partii

  // nakładka barwiąca w trybie overlay
  vec3 sel = step(vec3(0.5), col);
  vec3 over = mix(2.0 * col * TINT, vec3(1.0) - 2.0 * (vec3(1.0) - col) * (vec3(1.0) - TINT), sel);
  col = mix(col, over, TINT_OP);

  col *= 1.0 - SCAN * 0.45 * (0.5 + 0.5 * sin(gl_FragCoord.y * 3.14159));
  vec2 d = uv - 0.5;
  col *= clamp(1.0 - VIGNETTE * dot(d, d) * 2.4, 0.0, 1.0);
  col += (hash(uv * u_res + u_time) - 0.5) * GRAIN * 0.10;

  gl_FragColor = vec4(max(col, BG * 0.65), 1.0);
}
`;
}

/** Źródło tekstury: na telefonie obiekt Asset z plikiem lokalnym, w przeglądarce
 *  zwykły `<img>` — expo-gl przyjmuje co innego na każdej platformie. */
type Texture = { data: any; width: number; height: number };

async function loadTexture(mod: number): Promise<Texture | null> {
  const a = Asset.fromModule(mod);
  await a.downloadAsync();
  const width = a.width || 1, height = a.height || 1;
  if (Platform.OS !== "web") {
    // expo-gl czyta teksturę z dysku, nie z adresu http paczki aktualizacji
    return a.localUri ? { data: a, width, height } : null;
  }
  const src = a.localUri || a.uri;
  if (!src) return null;
  return new Promise((resolve) => {
    const img = new (globalThis as any).Image();
    img.crossOrigin = "anonymous";
    img.onload = () => resolve({ data: img, width: img.width || width, height: img.height || height });
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

export default function AsciiEffect({
  preset, fps, downscale = 1, bg,
}: {
  preset: AsciiPreset;
  fps?: number;
  downscale?: number;
  bg: [number, number, number];
}) {
  const [tex, setTex] = useState<Texture | null>(null);
  const [ready, setReady] = useState(false);
  const locs = useRef<any>({});

  useEffect(() => {
    let alive = true;
    // przy zmianie zdjęcia wstrzymujemy rysowanie — inaczej nowy shader dostałby
    // na moment starą teksturę
    setReady(false);
    loadTexture(preset.source)
      .catch(() => null)
      .then((t) => { if (alive) { setTex(t); setReady(true); } });
    return () => { alive = false; };
  }, [preset.source]);

  // shader powstaje dopiero, gdy wiadomo czy jest tekstura — inaczej zostałby
  // skompilowany w wersji zapasowej i tak już zostało
  const source = ready ? frag(preset, !!tex, bg) : "";

  return (
    <ShaderCanvas
      frag={source}
      ready={ready}
      fps={fps ?? preset.fps}
      downscale={downscale}
      setup={(gl, prog) => {
        locs.current = {
          res: gl.getUniformLocation(prog, "u_res"),
          time: gl.getUniformLocation(prog, "u_time"),
          rect: gl.getUniformLocation(prog, "u_rect"),
        };
        if (!tex) return;
        const handle = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, handle);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, tex.data);
        // zdjęcie nie ma wymiarów będących potęgą dwójki — bez tego byłby czarny prostokąt
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.uniform1i(gl.getUniformLocation(prog, "u_tex"), 0);
      }}
      frame={({ gl, w, h, t }) => {
        // wpasowanie zdjęcia: „cover" wypełnia ekran, inaczej pas o szerokości `fit`
        const imgA = tex ? tex.width / tex.height : 1.6;
        const scrA = w / h;
        let rw = preset.fit;
        if (preset.cover) rw = scrA >= imgA ? 1 : imgA / scrA;
        const rh = rw * scrA / imgA;
        gl.uniform2f(locs.current.res, w, h);
        gl.uniform1f(locs.current.time, t);
        gl.uniform4f(locs.current.rect, (1 - rw) / 2, preset.offsetY - rh / 2, rw, rh);
      }}
    />
  );
}
