/** Klocki UI wielokrotnego użytku — metaliczny przycisk, karta, wejście z opóźnieniem. */
import * as Haptics from "expo-haptics";
import { LinearGradient } from "expo-linear-gradient";
import React, { useEffect, useRef, useState } from "react";
import {
  Animated, Easing, Platform, Pressable, PressableProps, StyleSheet, Text, TextStyle,
  View, ViewStyle,
} from "react-native";
import { C, T } from "../theme";

/** Krótkie stuknięcie w telefon przy dotknięciu — na webie po prostu nie istnieje. */
function tap() {
  if (Platform.OS === "web") return;
  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
}

export { default as ErrorBoundary } from "./ErrorBoundary";
export { default as LiquidButton } from "./LiquidButton";
export { default as RefreshButton } from "./RefreshButton";
import LiquidPill from "./LiquidPill";
import LiquidSurface, { LiquidHandle } from "./LiquidSurface";
export { default as LiquidPill } from "./LiquidPill";
export { default as LiquidSurface } from "./LiquidSurface";

type Tone = "steel" | "green" | "red" | "amber" | "blue";

/** Paleta ramki i wypełnienia dla każdego stanu przycisku. */
const TONES: Record<Tone, { accent: string; onFace: [string, string]; onEdge: [string, string] }> = {
  steel: { accent: C.text,
           onFace: ["#252d3f", "#161b27"], onEdge: ["rgba(255,255,255,.38)", "rgba(255,255,255,.08)"] },
  green: { accent: C.green,
           onFace: ["rgba(47,212,138,.20)", "rgba(47,212,138,.05)"],
           onEdge: ["rgba(47,212,138,.85)", "rgba(47,212,138,.22)"] },
  red: { accent: C.red,
         onFace: ["rgba(255,92,108,.20)", "rgba(255,92,108,.05)"],
         onEdge: ["rgba(255,92,108,.85)", "rgba(255,92,108,.22)"] },
  amber: { accent: C.amber,
           onFace: ["rgba(255,180,84,.20)", "rgba(255,180,84,.05)"],
           onEdge: ["rgba(255,180,84,.85)", "rgba(255,180,84,.22)"] },
  blue: { accent: C.accent,
          onFace: ["rgba(91,140,255,.20)", "rgba(91,140,255,.05)"],
          onEdge: ["rgba(91,140,255,.85)", "rgba(91,140,255,.22)"] },
};

const OFF_FACE: [string, string] = ["#171d29", "#0f131c"];
const OFF_EDGE: [string, string] = ["rgba(255,255,255,.14)", "rgba(255,255,255,.02)"];

const SIZES = {
  sm: { padV: 7, padH: 12, radius: 11, font: 12.5 },
  md: { padV: 11, padH: 16, radius: 13, font: 13.5 },
  lg: { padV: 14, padH: 20, radius: 15, font: 15.5 },
};

type MetalProps = {
  label?: string;
  children?: React.ReactNode;
  onPress?: () => void;
  tone?: Tone;
  size?: keyof typeof SIZES;
  /** stan wybrany — ramka i tekst przejmują kolor tonacji */
  active?: boolean;
  /** pełne wypełnienie kolorem — do jednej głównej akcji na ekranie */
  filled?: boolean;
  /** własny kolor akcentu (np. barwa benchmarku) */
  accent?: string;
  disabled?: boolean;
  full?: boolean;
  round?: boolean;
  /** aktywny stan wypełnia płynny metal zamiast płaskiego gradientu */
  liquid?: boolean;
  style?: ViewStyle;
  textStyle?: TextStyle;
};

/** Przycisk z metaliczną ramką: wciska się, przebiega po nim błysk, a od miejsca
 *  dotknięcia rozchodzi się fala. Jeden komponent obsługuje też pigułki filtrów
 *  (`size="sm"` + `active`), żeby cała aplikacja mówiła jednym językiem. */
export function MetalButton({
  label, children, onPress, tone = "steel", size = "md", active = false, filled = false,
  accent, disabled = false, full = false, round = false, liquid = false, style, textStyle,
}: MetalProps) {
  // WSZYSTKIE hooki muszą stać przed jakimkolwiek `return` — wariant „liquid" włącza
  // się i wyłącza razem z `active`, więc pominięcie ich przy wybraniu przycisku
  // zmieniałoby liczbę hooków między renderami i wywracało cały ekran
  const boost = useRef<LiquidHandle | null>(null);
  const scale = useRef(new Animated.Value(1)).current;
  const sheen = useRef(new Animated.Value(0)).current;
  const wave = useRef(new Animated.Value(0)).current;
  const [w, setW] = useState(0);
  const [spot, setSpot] = useState({ x: 0, y: 0 });

  const dims = SIZES[size];
  const t = TONES[tone];
  const color = accent || t.accent;

  // stan wybrany w wersji „liquid" to osobny projekt: metal jest OBWÓDKĄ,
  // a wnętrze zostaje prawie czarne — dokładnie jak w pierwowzorze
  if (liquid && active && !filled) {
    return (
      <LiquidPill
        label={label} size={size} active disabled={disabled} full={full}
        tint={color} tintMix={accent ? 0.45 : 0.22}
        onPress={onPress} style={style} textStyle={textStyle}
      >
        {children}
      </LiquidPill>
    );
  }

  const spring = (to: number) =>
    Animated.spring(scale, { toValue: to, useNativeDriver: true, speed: 50, bounciness: 6 }).start();

  function press(e: any) {
    if (disabled) return;
    tap();
    boost.current?.boost();
    const { locationX = 0, locationY = 0 } = e?.nativeEvent || {};
    setSpot({ x: locationX, y: locationY });
    spring(0.96);
    // błysk przebiega raz przez całą szerokość, fala rozchodzi się z punktu dotknięcia
    sheen.setValue(0);
    wave.setValue(0);
    Animated.parallel([
      Animated.timing(sheen, { toValue: 1, duration: 520, easing: Easing.out(Easing.quad), useNativeDriver: true }),
      Animated.timing(wave, { toValue: 1, duration: 520, easing: Easing.out(Easing.cubic), useNativeDriver: true }),
    ]).start();
  }

  const face = filled ? ([color, color] as [string, string])
    : active ? t.onFace : OFF_FACE;
  const edge = filled ? ([color, color] as [string, string])
    : active ? (accent ? [accent, accent + "44"] as [string, string] : t.onEdge)
    : OFF_EDGE;
  const txtColor = filled ? "#04140c" : active ? color : C.muted;

  return (
    <Pressable
      onPressIn={press}
      onPressOut={() => spring(1)}
      onPress={disabled ? undefined : onPress}
      disabled={disabled}
      style={full ? { alignSelf: "stretch" } : undefined}
    >
      <Animated.View
        onLayout={(e) => setW(e.nativeEvent.layout.width)}
        style={[{ transform: [{ scale }] }, disabled && { opacity: 0.45 }, style]}
      >
        <LinearGradient
          colors={edge} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={{ borderRadius: round ? 999 : dims.radius, padding: 1 }}
        >
          <LinearGradient
            colors={face} start={{ x: 0, y: 0 }} end={{ x: 0, y: 1 }}
            style={[
              s.mFace,
              {
                borderRadius: round ? 999 : dims.radius - 1,
                paddingVertical: dims.padV,
                paddingHorizontal: dims.padH,
              },
            ]}
          >
            <Animated.View
              pointerEvents="none"
              style={[
                s.sheen,
                {
                  opacity: sheen.interpolate({ inputRange: [0, 0.15, 1], outputRange: [0, 0.5, 0] }),
                  transform: [
                    { translateX: sheen.interpolate({ inputRange: [0, 1], outputRange: [-60, w + 60] }) },
                    { rotate: "18deg" },
                  ],
                },
              ]}
            />
            <Animated.View
              pointerEvents="none"
              style={[
                s.wave,
                {
                  left: spot.x, top: spot.y, backgroundColor: filled ? "#04140c" : color,
                  opacity: wave.interpolate({ inputRange: [0, 1], outputRange: [0.28, 0] }),
                  transform: [
                    { translateX: -70 }, { translateY: -70 },
                    { scale: wave.interpolate({ inputRange: [0, 1], outputRange: [0.1, 1.6] }) },
                  ],
                },
              ]}
            />
            {children ?? (
              <Text style={[s.mText, { color: txtColor, fontSize: dims.font },
                            liquid && active && s.onMetal, textStyle]}
                    numberOfLines={1}>
                {label}
              </Text>
            )}
          </LinearGradient>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

/** Przycisk, który reaguje na dotyk skalą — daje wrażenie fizyczności. */
export function Press({
  children, style, onPress, scaleTo = 0.96, disabled, ...rest
}: PressableProps & { style?: ViewStyle | ViewStyle[]; scaleTo?: number }) {
  const scale = useRef(new Animated.Value(1)).current;
  const to = (v: number) =>
    Animated.spring(scale, { toValue: v, useNativeDriver: true, speed: 45, bounciness: 4 }).start();

  return (
    <Pressable
      onPressIn={() => !disabled && to(scaleTo)}
      onPressOut={() => to(1)}
      onPress={onPress}
      disabled={disabled}
      {...rest}
    >
      <Animated.View style={[style, { transform: [{ scale }] }, disabled && { opacity: 0.5 }]}>
        {children as React.ReactNode}
      </Animated.View>
    </Pressable>
  );
}

/** Wjazd elementu przy montowaniu — z opóźnieniem buduje kaskadę na ekranie. */
export function FadeIn({
  children, delay = 0, offset = 14, style,
}: {
  children: React.ReactNode; delay?: number; offset?: number; style?: ViewStyle | ViewStyle[];
}) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.timing(a, {
      toValue: 1, duration: 420, delay,
      easing: Easing.bezier(0.22, 1, 0.36, 1), useNativeDriver: true,
    }).start();
  }, []);
  return (
    <Animated.View
      style={[
        style,
        {
          opacity: a,
          transform: [{ translateY: a.interpolate({ inputRange: [0, 1], outputRange: [offset, 0] }) }],
        },
      ]}
    >
      {children}
    </Animated.View>
  );
}

export function Card({
  children, style, padded = true,
}: { children: React.ReactNode; style?: ViewStyle | (ViewStyle | false | undefined)[]; padded?: boolean }) {
  return <View style={[s.card, padded && { padding: 15 }, style]}>{children}</View>;
}

export function SectionTitle({ children, hint }: { children: string; hint?: string }) {
  return (
    <View style={s.sectionWrap}>
      <Text style={s.sectionTitle}>{children}</Text>
      {!!hint && <Text style={s.sectionHint}>{hint}</Text>}
    </View>
  );
}

/** Przełącznik z metaliczną pigułką, która przesuwa się pod aktywną opcją. */
export function Segmented({
  options, value, onChange, tone = "steel", liquid = false,
}: {
  options: { id: string; label: string }[];
  value: string;
  onChange: (id: string) => void;
  tone?: Tone;
  /** pigułka wypełniona płynnym metalem — do przełączników na widoku */
  liquid?: boolean;
}) {
  const idx = Math.max(0, options.findIndex((o) => o.id === value));
  const pos = useRef(new Animated.Value(idx)).current;
  const [w, setW] = React.useState(0);
  const t = TONES[tone];
  const boost = useRef<LiquidHandle | null>(null);

  useEffect(() => {
    Animated.spring(pos, { toValue: idx, useNativeDriver: true, speed: 20, bounciness: 7 }).start();
  }, [idx]);

  const seg = w / Math.max(1, options.length);

  return (
    <View style={s.segWrap} onLayout={(e) => setW(e.nativeEvent.layout.width - 6)}>
      {w > 0 && (
        <Animated.View
          style={[
            s.segPillWrap,
            {
              width: seg,
              transform: [{
                translateX: pos.interpolate({
                  inputRange: options.map((_, i) => i),
                  outputRange: options.map((_, i) => i * seg),
                }),
              }],
            },
          ]}
        >
          {liquid ? (
            // metal po obwodzie, wnętrze prawie czarne — jak w oryginalnym przycisku
            <View style={s.segRim}>
              <LiquidSurface tint={t.accent} tintMix={0.22} fps={30} boostRef={boost}
                             style={{ borderRadius: 10 }} />
              <View style={s.segInner}>
                <LinearGradient colors={["#202020", "#000000"]}
                                start={{ x: 0, y: 0 }} end={{ x: 0, y: 1 }}
                                style={StyleSheet.absoluteFill as any} />
              </View>
            </View>
          ) : (
            <LinearGradient colors={t.onEdge} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
                            style={s.segEdge}>
              <LinearGradient colors={t.onFace} start={{ x: 0, y: 0 }} end={{ x: 0, y: 1 }}
                              style={s.segFace} />
            </LinearGradient>
          )}
        </Animated.View>
      )}
      {options.map((o) => (
        <Pressable key={o.id} style={s.segBtn}
                   onPress={() => { tap(); boost.current?.boost(); onChange(o.id); }}>
          <Text style={[s.segTxt, value === o.id && { color: t.accent },
                        liquid && value === o.id && s.onMetal]} numberOfLines={1}>
            {o.label}
          </Text>
        </Pressable>
      ))}
    </View>
  );
}

/** Poziomy pasek postępu — używany w listach alokacji. */
export function Bar({ pct, color, delay = 0 }: { pct: number; color: string; delay?: number }) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.timing(a, {
      toValue: 1, duration: 700, delay, easing: Easing.out(Easing.cubic), useNativeDriver: false,
    }).start();
  }, [pct]);
  return (
    <View style={s.barTrack}>
      <Animated.View
        style={[
          s.barFill,
          {
            backgroundColor: color,
            width: a.interpolate({
              inputRange: [0, 1],
              outputRange: ["0%", `${Math.max(1, Math.min(100, pct))}%`],
            }),
          },
        ]}
      />
    </View>
  );
}

/** Wiersz „etykieta → wartość" w kartach statystyk. */
export function Row({
  k, v, color, last,
}: { k: string; v: string; color?: string; last?: boolean }) {
  return (
    <View style={[s.row, last && { borderBottomWidth: 0 }]}>
      <Text style={s.rowK}>{k}</Text>
      <Text style={[s.rowV, color ? { color } : null]}>{v}</Text>
    </View>
  );
}

/** Wielki przycisk zakupu z przebiegającym błyskiem.
 *
 *  Mieszka tutaj, a nie na stronie sprzedażowej, bo używają go dwie drogi
 *  płatności: Stripe (web, Android) i StoreKit (iPhone). Ta sama akcja ma
 *  wyglądać identycznie niezależnie od tego, kto akurat pobiera pieniądze.
 */
export function CheckoutButton({
  label, busy, onPress, style,
}: { label: string; busy: boolean; onPress: () => void; style?: ViewStyle }) {
  const scale = useRef(new Animated.Value(1)).current;
  const shimmer = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(shimmer, { toValue: 1, duration: 1800, easing: Easing.inOut(Easing.quad), useNativeDriver: true }),
        Animated.delay(1200),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, []);
  return (
    <Pressable
      onPress={busy ? undefined : onPress}
      onPressIn={() => Animated.spring(scale, { toValue: 0.97, useNativeDriver: true, speed: 50, bounciness: 6 }).start()}
      onPressOut={() => Animated.spring(scale, { toValue: 1, useNativeDriver: true, speed: 50, bounciness: 6 }).start()}
      style={[{ marginTop: 20 }, style]}
    >
      <Animated.View style={{ transform: [{ scale }], opacity: busy ? 0.7 : 1 }}>
        <LinearGradient
          colors={[C.amber, C.brandOrange]}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={cta.face}
        >
          <Animated.View
            pointerEvents="none"
            style={[
              cta.shine,
              {
                opacity: shimmer.interpolate({ inputRange: [0, 0.15, 1], outputRange: [0, 0.55, 0] }),
                transform: [
                  { translateX: shimmer.interpolate({ inputRange: [0, 1], outputRange: [-220, 420] }) },
                  { rotate: "18deg" },
                ],
              },
            ]}
          />
          <Text style={cta.txt} numberOfLines={1}>{busy ? "Łączę…" : label}</Text>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

