/** Źródła nasłuchu — co bot obserwuje i kiedy sprawdzi to ponownie.
 *
 *  Sedno tego ekranu to LICZNIKI. Wcześniej nie było widać, czy źródło żyje,
 *  czy zawiesiło się w połowie — a to najczęstsza awaria bota. Tutaj każde
 *  źródło ma odliczanie do następnego sprawdzenia i moment ostatniego kontaktu,
 *  więc martwe źródło rzuca się w oczy bez zaglądania w logi.
 *
 *  Zegar telefonu bywa przesunięty względem serwera, dlatego liczymy różnicę
 *  (`server_time` z API) i wszystkie odliczania robimy w czasie serwera.
 */
import React, { useEffect, useState } from "react";
import { StyleSheet, Switch, Text, View } from "react-native";
import { BotState, setParams } from "../../api";
import { C, T } from "../../theme";
import { Card, FadeIn, SectionTitle } from "../../ui";
import { ago, every, SOURCES } from "./sources";

export default function SourcesTab({
  st, reload,
}: { st: BotState; reload: () => Promise<void> }) {
  // własny zegar 1 Hz — odliczanie ma płynąć niezależnie od odświeżania danych
  const [now, setNow] = useState(Date.now() / 1000);
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now() / 1000), 1000);
    return () => clearInterval(t);
  }, []);

  const running = st.bot_alive;
  const polls: Record<string, any> = st.bot_status?.polls || {};
  /** Zdrowie źródeł — odróżnia „działa, ale cisza" od „nie odpowiada". */
  const health = st.sources_health || {};
  const p = st.params || {};
  // różnica zegarów telefon–serwer, wyznaczona przy ostatnim pobraniu stanu
  const offset = st.server_time ? Date.now() / 1000 - st.server_time : 0;
  const serverNow = now - offset;

  const patch = async (updates: Record<string, any>) => {
    await setParams(updates);
    await reload();
  };

  const active = SOURCES.filter((x) => p[x.param]).length;

  return (
    <View style={{ marginTop: 14 }}>
      <FadeIn>
        <Card style={s.head}>
          <View style={s.headRow}>
            <View style={[s.dot, { backgroundColor: running ? C.green : C.dim }]} />
            <Text style={s.headTxt}>
              {running ? "Nasłuch trwa" : "Nasłuch zatrzymany"}
            </Text>
            <Text style={s.headCount}>{active}/{SOURCES.length} włączonych</Text>
          </View>
          <Text style={s.headDesc}>
            {running
              ? "Każde źródło ma własny rytm. Nowy materiał trafia do analizy od razu, w osobnym wątku."
              : "Włącz bota w zakładce Sterowanie, żeby liczniki ruszyły."}
          </Text>
        </Card>
      </FadeIn>

      <SectionTitle hint="Przełącznik działa od razu — bot nie wymaga restartu">
        Obserwowane źródła
      </SectionTitle>

      {SOURCES.map((src, i) => {
        const on = Boolean(p[src.param]);
        const poll = polls[src.poll];
        const interval = Number(poll?.interval || 0);
        const last = Number(poll?.ts || 0);
        const since = last ? serverNow - last : null;
        const left = interval && since != null ? Math.max(0, interval - since) : null;
        // pasek pokazuje, ile czasu upłynęło od ostatniego sprawdzenia
        const pct = interval && since != null
          ? Math.max(2, Math.min(100, (since / interval) * 100)) : 0;

        let statusTxt = "wyłączone";
        let statusColor = C.dim;
        if (on && !running) { statusTxt = "czeka na start"; statusColor = C.muted; }
        else if (on && running && !last) { statusTxt = "pierwsze sprawdzenie…"; statusColor = C.amber; }
        else if (on && running && left != null) {
          statusTxt = left < 1 ? "sprawdzam…" : `za ${Math.ceil(left)} s`;
          statusColor = left < 1 ? C.amber : C.green;
        }

        return (
          <FadeIn key={src.poll} delay={Math.min(i * 24, 220)} offset={8}>
            <Card style={s.card}>
              <View style={s.row}>
                <View style={[s.badge, { backgroundColor: src.color + "22", borderColor: src.color + "55" }]}>
                  <Text style={[s.badgeTxt, { color: src.color }]}>{src.badge}</Text>
                </View>
                <View style={{ flex: 1, marginLeft: 10 }}>
                  <Text style={s.name}>{src.name}</Text>
                  <Text style={s.desc}>{src.desc}</Text>
                </View>
                <Switch
                  value={on}
                  onValueChange={(v) => patch({ [src.param]: v })}
                  trackColor={{ false: "#2a3247", true: "rgba(47,212,138,.5)" }}
                  thumbColor={on ? C.green : "#fff"}
                />
              </View>

              {on && (
                <>
                  <View style={s.track}>
                    <View style={[s.fill, {
                      width: `${pct}%`,
                      backgroundColor: running ? src.color : C.dim,
                    }]} />
                  </View>
                  <View style={s.metaRow}>
                    <Text style={[s.status, { color: statusColor }]}>{statusTxt}</Text>
                    <Text style={s.meta}>
                      {interval ? every(interval) : "—"}
                      {since != null ? `  ·  ostatnio ${ago(since)}` : ""}
                    </Text>
                  </View>

                  {/* Odliczanie mówi tylko, że bot PYTA. Ta linijka mówi, co
                      dostaje w odpowiedzi — bez niej „cisza w Truth Social"
                      i „Truth Social nie odpowiada od tygodnia" wyglądały
                      w aplikacji dokładnie tak samo. */}
                  {running && <Zdrowie stan={health[src.poll]} serverNow={serverNow} />}
                </>
              )}
            </Card>
          </FadeIn>
        );
      })}

      {!!st.bot_status?.last_error && (
        <Card style={s.errCard}>
          <Text style={s.errTxt} numberOfLines={3}>
            Ostatni błąd pętli: {st.bot_status.last_error}
          </Text>
        </Card>
      )}
    </View>
  );
}

/** Jedna linijka o tym, co źródło realnie przyniosło. */
function Zdrowie({ stan, serverNow }: { stan?: any; serverNow: number }) {
  if (!stan) return null;

  // Wpis powstaje w chwili ROZPOCZĘCIA pobierania, więc zerowy `ok_ts` znaczy
  // „pierwsze sprawdzenie jeszcze trwa" — nie „nic nie przyniosło". Przy wolnych
  // źródłach (SEC potrafi zbierać pół minuty) trafia się to po każdym starcie.
  if (!stan.ok_ts && !stan.err) {
    return <Text style={s.zdrowie}>Pierwsze sprawdzenie w toku…</Text>;
  }

  if (stan.err) {
    return (
      <Text style={s.zdrowieBlad} numberOfLines={2}>
        Nie odpowiada{stan.err_ts ? ` (od ${ago(serverNow - stan.err_ts)})` : ""}: {stan.err}
      </Text>
    );
  }
  if (!stan.items) {
    return (
      <Text style={s.zdrowie}>
        Odpowiada poprawnie, ale nic nowego od startu nasłuchu — to normalne przy
        źródłach, które publikują rzadko.
      </Text>
    );
  }
  return (
    <Text style={s.zdrowie}>
      {stan.items} {stan.items === 1 ? "materiał" : "materiałów"} od startu
      {stan.last_item_ts ? `  ·  ostatni ${ago(serverNow - stan.last_item_ts)}` : ""}
    </Text>
  );
}

const s = StyleSheet.create({
  zdrowie: { color: C.dim, fontSize: 11, lineHeight: 16, marginTop: 7 },
  zdrowieBlad: { color: C.red, fontSize: 11, lineHeight: 16, marginTop: 7 },
  head: { padding: 14, marginBottom: 4 },
  headRow: { flexDirection: "row", alignItems: "center" },
  dot: { width: 9, height: 9, borderRadius: 5, marginRight: 8 },
  headTxt: { color: C.text, ...T.h2 },
  headCount: { marginLeft: "auto", color: C.muted, fontSize: 11.5 },
  headDesc: { color: C.muted, fontSize: 12, lineHeight: 17, marginTop: 8 },

  card: { padding: 13, marginBottom: 9 },
  row: { flexDirection: "row", alignItems: "center" },
  badge: { borderRadius: 6, borderWidth: 1, paddingHorizontal: 7, paddingVertical: 3 },
  badgeTxt: { fontSize: 9.5, fontWeight: "800", letterSpacing: 0.5 },
  name: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  desc: { color: C.muted, fontSize: 11, marginTop: 2, lineHeight: 15 },

  track: { height: 3, borderRadius: 2, backgroundColor: "#1c2333", marginTop: 12, overflow: "hidden" },
  fill: { height: 3, borderRadius: 2 },
  metaRow: { flexDirection: "row", alignItems: "center", marginTop: 7 },
  status: { fontSize: 11, fontWeight: "700" },
  meta: { marginLeft: "auto", color: C.dim, fontSize: 10.5 },

  errCard: { padding: 12, marginTop: 6, borderColor: "rgba(255,92,108,.35)", borderWidth: 1 },
  errTxt: { color: C.red, fontSize: 11.5, lineHeight: 16 },
});
