/** Kafelek wydarzenia ekonomicznego — pasek nad spółkami danego dnia.
 *
 *  Wydarzenia banków centralnych dostają osobny, mocniejszy wygląd (czerwona płytka
 *  z napisem FED / NBP / ECB), bo to one przestawiają cały rynek naraz. Reszta to
 *  spokojne pigułki, których intensywność rośnie z wagą odczytu.
 */
import React from "react";
import { StyleSheet, Text, View } from "react-native";
import { EconEvent } from "../../api";
import { C } from "../../theme";
import { Press } from "../../ui";

/** Skrót banku centralnego z nazwy wydarzenia — do napisu na czerwonej płytce. */
export function bankTag(e: EconEvent): string {
  const n = e.name.toUpperCase();
  if (/FOMC|FED|POWELL|FEDERAL RESERVE|BEIGE/.test(n)) return "FED";
  if (/\bECB\b|LAGARDE/.test(n)) return "EBC";
  if (/\bBOE\b/.test(n)) return "BOE";
  if (/\bBOJ\b/.test(n)) return "BOJ";
  if (/\bSNB\b/.test(n)) return "SNB";
  if (/\bPBOC\b/.test(n)) return "PBOC";
  if (/\bBOC\b/.test(n)) return "BOC";
  if (e.country === "PL") return "NBP";
  return e.country;
}

/** Kolor wagi: wysoka = czerwień, średnia = bursztyn, niska = stal. */
export function toneOf(e: EconEvent): string {
  if (e.kind === "fed" || e.kind === "cb") return C.red;
  if (e.kind === "holiday") return C.dim;
  return e.importance >= 3 ? C.amber : e.importance === 2 ? C.accent : C.dim;
}

export function hhmm(e: EconEvent): string {
  if (e.all_day || !e.ts) return "cały dzień";
  const d = new Date(e.ts * 1000);
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

export default function EventChip({
  event, onPress,
}: { event: EconEvent; onPress: () => void }) {
  const bank = event.kind === "fed" || event.kind === "cb";
  const tone = toneOf(event);

  if (bank) {
    return (
      <Press onPress={onPress}>
        <View style={[s.bank, { borderColor: tone }]}>
          <View style={[s.bankBadge, { backgroundColor: tone }]}>
            <Text style={s.bankTxt}>{bankTag(event)}</Text>
          </View>
          <Text style={[s.bankTime, { color: tone }]}>{hhmm(event)}</Text>
          <Text style={s.bankName} numberOfLines={2}>{event.name_pl}</Text>
        </View>
      </Press>
    );
  }

  return (
    <Press onPress={onPress}>
      <View style={[s.chip, { borderColor: tone + "66" }]}>
        <View style={s.chipHead}>
          <Text style={s.flag}>{event.flag}</Text>
          <Text style={[s.time, { color: tone }]}>{hhmm(event)}</Text>
          {event.importance >= 2 && (
            <View style={s.dots}>
              {[1, 2, 3].map((i) => (
                <View key={i} style={[s.dot, {
                  backgroundColor: i <= event.importance ? tone : "rgba(255,255,255,.12)",
                }]} />
              ))}
            </View>
          )}
        </View>
        <Text style={s.name} numberOfLines={2}>{event.name_pl}</Text>
        {(!!event.actual_fmt || !!event.consensus_fmt) && (
          <Text style={s.vals} numberOfLines={1}>
            {event.actual_fmt
              ? <Text style={{ color: event.better === false ? C.red : event.better ? C.green : C.text }}>
                  {event.actual_fmt}
                </Text>
              : <Text style={{ color: C.muted }}>{event.consensus_fmt}</Text>}
            {!!event.previous_fmt && <Text style={{ color: C.dim }}>  ← {event.previous_fmt}</Text>}
          </Text>
        )}
      </View>
    </Press>
  );
}

const s = StyleSheet.create({
  bank: {
    width: 108, borderRadius: 13, borderWidth: 1.5, padding: 8,
    backgroundColor: "rgba(255,92,108,.07)", gap: 3,
  },
  bankBadge: { alignSelf: "flex-start", borderRadius: 6, paddingHorizontal: 6, paddingVertical: 2 },
  bankTxt: { color: "#150406", fontSize: 10, fontWeight: "900", letterSpacing: 0.8 },
  bankTime: { fontSize: 13, fontWeight: "900", letterSpacing: -0.3 },
  bankName: { color: C.muted, fontSize: 9.5, fontWeight: "600", lineHeight: 12 },

  chip: {
    width: 132, borderRadius: 13, borderWidth: 1, padding: 8, gap: 3,
    backgroundColor: "rgba(255,255,255,.02)",
  },
  chipHead: { flexDirection: "row", alignItems: "center", gap: 5 },
  flag: { fontSize: 12 },
  time: { fontSize: 11, fontWeight: "800" },
  dots: { flexDirection: "row", gap: 2, marginLeft: "auto" },
  dot: { width: 4, height: 4, borderRadius: 2 },
  name: { color: C.text, fontSize: 10.5, fontWeight: "700", lineHeight: 13 },
  vals: { fontSize: 10, fontWeight: "700" },
});
