/** Przełączanie zakładek z dowolnego miejsca aplikacji.
 *
 *  Ten sam wzorzec, co `companyRouter`: powłoka (App.tsx) rejestruje tu jedną
 *  funkcję, a ekrany proszą o przejście, nie importując powłoki. Bez tego
 *  „Bot newsów" w Narzędziach musiałby albo dostać własną kopię ekranu bota,
 *  albo zaciągnąć App.tsx — czyli import w kółko.
 */

export type TabId = "overview" | "allocation" | "history" | "bot" | "tools"
                  | "pages" | "more" | "promo";
export type HubId = "bot" | "earnings";

type Opener = (tab: TabId, hub?: HubId) => void;

let opener: Opener | null = null;

export function setTabOpener(fn: Opener | null) {
  opener = fn;
}

/** Zwraca false, gdy nie ma kto obsłużyć — wołający może wtedy nic nie robić. */
export function openTab(tab: TabId, hub?: HubId): boolean {
  if (!opener) return false;
  opener(tab, hub);
  return true;
}
