/** Ekran łączenia z panelem na komputerze — adres serwera + token. */
import React, { useState } from "react";
import {
  ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, ScrollView,
  StyleSheet, Text, TextInput, View,
} from "react-native";
import { ping, saveConfig } from "../api";
import { BrandLogo } from "../components/Brand";
import { C } from "../theme";
import { LiquidButton } from "../ui";

export default function ConnectScreen({
  initialUrl, initialToken, onConnected,
}: {
  initialUrl: string;
  initialToken: string;
  onConnected: () => void;
}) {
  const [url, setUrl] = useState(initialUrl || "http://192.168.1.89:8500");
  const [token, setToken] = useState(initialToken);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  async function connect() {
    setBusy(true);
    setErr("");
    try {
      await ping(url, token);
      await saveConfig(url, token);
      onConnected();
    } catch (e: any) {
      setErr(e?.message || "Nie udało się połączyć");
    } finally {
      setBusy(false);
    }
  }

  return (
    <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined}>
      <ScrollView contentContainerStyle={s.wrap} keyboardShouldPersistTaps="handled">
        <BrandLogo width={200} style={{ marginBottom: 6, marginLeft: -6 }} />
        <Text style={s.sub}>Połącz się z panelem na komputerze</Text>

        <View style={s.card}>
          <Text style={s.label}>Adres serwera</Text>
          <TextInput
            style={s.input} value={url} onChangeText={setUrl}
            autoCapitalize="none" autoCorrect={false} keyboardType="url"
            placeholder="http://192.168.1.89:8500" placeholderTextColor={C.dim}
          />

          <Text style={[s.label, { marginTop: 16 }]}>Token dostępu</Text>
          <TextInput
            style={s.input} value={token} onChangeText={setToken}
            autoCapitalize="none" autoCorrect={false}
            placeholder="wklej token z panelu" placeholderTextColor={C.dim}
          />

          {!!err && <Text style={s.err}>{err}</Text>}

          <LiquidButton label={busy ? "Łączę…" : "Połącz"} disabled={busy}
                        onPress={connect} style={{ marginTop: 20 }} />
        </View>

        <View style={s.help}>
          <Text style={s.helpTitle}>Skąd wziąć te dane?</Text>
          <Text style={s.helpText}>
            Na komputerze otwórz w przeglądarce <Text style={s.b}>http://localhost:8500</Text> —
            adres i token są na tej stronie, w sekcji <Text style={s.b}>Podłącz telefon</Text>.
          </Text>
          <Text style={[s.helpText, { marginTop: 10 }]}>
            Serwer musi działać w trybie sieciowym (skrót <Text style={s.b}>Portevo (telefon)</Text>
            {" "}na pulpicie; startuje też sam przy włączeniu komputera). W tej samej sieci Wi-Fi
            użyj adresu <Text style={s.b}>192.168.…</Text>, spoza domu — adresu Tailscale.
          </Text>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const s = StyleSheet.create({
  wrap: { padding: 22, paddingTop: 70, gap: 6 },
  logo: { color: C.text, fontSize: 30, fontWeight: "800", letterSpacing: -0.4 },
  sub: { color: C.muted, fontSize: 14.5, marginBottom: 22 },
  card: {
    backgroundColor: C.card, borderColor: C.border, borderWidth: 1,
    borderRadius: 18, padding: 18,
  },
  label: {
    color: C.muted, fontSize: 11, fontWeight: "700",
    letterSpacing: 0.8, textTransform: "uppercase", marginBottom: 7,
  },
  input: {
    backgroundColor: C.bg, borderColor: C.border2, borderWidth: 1, borderRadius: 11,
    paddingHorizontal: 13, paddingVertical: 12, color: C.text, fontSize: 15,
  },
  err: { color: C.red, fontSize: 13, marginTop: 14 },
  btn: {
    backgroundColor: C.green, borderRadius: 13, paddingVertical: 15,
    alignItems: "center", marginTop: 20,
  },
  btnText: { color: "#04140c", fontWeight: "800", fontSize: 16 },
  help: {
    marginTop: 22, backgroundColor: C.elev, borderColor: C.border,
    borderWidth: 1, borderRadius: 14, padding: 16,
  },
  helpTitle: { color: C.text, fontWeight: "700", fontSize: 14, marginBottom: 8 },
  helpText: { color: C.muted, fontSize: 13, lineHeight: 19 },
  b: { color: C.text, fontWeight: "700" },
});
