// ------------------------------------------------------------ formatowanie

const ZNAK: Record<string, string> = { USD: "$", PLN: "zł", EUR: "€" };

/** Kwota w walucie transakcji: „1,2 mln $" albo „350 tys. zł" (GPW). */
export function kasa(v: number | null | undefined, cur = "USD", zeZnakiem = true): string {
  const s = usd(v, false);
  return zeZnakiem && s !== "—" ? `${s} ${ZNAK[cur] || cur}` : s;
}

/** „12,5 tys. $", „1,2 mln $", „3,4 mld $" — skala ważniejsza niż grosze. */
export function usd(v: number | null | undefined, zDolarem = true): string {
  if (v == null || !Number.isFinite(v)) return "—";
  const a = Math.abs(v);
  const [dz, sl] = a >= 1e9 ? [1e9, "mld"] : a >= 1e6 ? [1e6, "mln"] : a >= 1e3 ? [1e3, "tys."] : [1, ""];
  const x = (v / (dz as number)).toLocaleString("pl-PL", {
    maximumFractionDigits: dz === 1 ? 0 : a / (dz as number) >= 100 ? 0 : 1,
  });
  return `${x}${sl ? " " + sl : ""}${zDolarem ? " $" : ""}`;
}

/** Kwota transakcji: dokładna z SEC albo przedział z formularza Kongresu. */
export function kwota(t: Pick<TransakcjaInsidera, "lo" | "hi"> & { cur?: string }): string {
  const { lo, hi } = t;
  const cur = t.cur || "USD";
  if (lo == null && hi == null) return "kwota nieznana";
  if (hi == null) return `powyżej ${kasa(lo, cur)}`;
  if (lo == null || Math.abs(hi - lo) < 2) return kasa(hi, cur);
  return `${usd(lo, false)} – ${kasa(hi, cur)}`;
}

const MIES = ["sty", "lut", "mar", "kwi", "maj", "cze", "lip", "sie", "wrz", "paź", "lis", "gru"];

export function dzien(iso: string | null | undefined, zRokiem = false): string {
  if (!iso) return "—";
  const [r, m, d] = iso.slice(0, 10).split("-").map(Number);
  if (!r || !m || !d) return iso;
  return `${d} ${MIES[m - 1]}${zRokiem ? ` ${r}` : ""}`;
}

export function ileTemu(iso: string | null | undefined): string {
  if (!iso) return "";
  const t = Date.parse(`${iso.slice(0, 10)}T12:00:00Z`);
  if (!Number.isFinite(t)) return "";
  const dni = Math.round((Date.now() - t) / 86400000);
  if (dni <= 0) return "dziś";
  if (dni === 1) return "wczoraj";
  if (dni < 7) return `${dni} dni temu`;
  if (dni < 60) return `${Math.round(dni / 7)} tyg. temu`;
  return dzien(iso, true);
}

export function procent(v: number | null | undefined): string {
  if (v == null || !Number.isFinite(v)) return "—";
  return `${v > 0 ? "+" : ""}${v.toLocaleString("pl-PL", { maximumFractionDigits: 1, minimumFractionDigits: 1 })}%`;
}

export const PARTIE: Record<string, { label: string; color: string }> = {
  D: { label: "Demokraci", color: "#5b8cff" },
  R: { label: "Republikanie", color: "#ff5c6c" },
  I: { label: "Niezależni", color: "#8b93a7" },
};

/** Opis persony w jednej linii: „Izba Reprezentantów · CA-11 · Demokraci".
 *  `krotko` — do list na wąskim ekranie, gdzie pełna nazwa izby się ucina. */
export function opis(p: PersonaInsidera, krotko = false): string {
  const rola = krotko ? p.role.replace("Izba Reprezentantów", "Kongres") : p.role;
  const czesci = [rola, p.org && p.org !== "Kongres USA" ? p.org : ""];
  if (p.party && PARTIE[p.party]) czesci.push(PARTIE[p.party].label);
  return czesci.filter(Boolean).join(" · ");
}

// --------------------------------------------------------------- ustawienia

type Prefs = { cats: string[]; sells: boolean; chart: boolean };

let prefs: Prefs = { cats: WSZYSTKIE_KLASY, sells: false, chart: true };
let wczytane = false;
const sluchacze = new Set<(p: Prefs) => void>();

async function wczytaj() {
  if (wczytane) return;
  wczytane = true;
  const [c, s, ch] = await Promise.all([
    getPref("insiders.cats", ""), getPref("insiders.sells", "0"), getPref("insiders.chart", "1"),
  ]);
  let cats = WSZYSTKIE_KLASY;
  try {
    const x = c ? JSON.parse(c) : null;
    if (Array.isArray(x)) cats = x.filter((k) => typeof k === "string");
  } catch { /* zły zapis = domyślne wszystkie */ }
  ustaw({ cats, sells: s === "1", chart: ch !== "0" }, false);
}

function ustaw(p: Prefs, zapisz = true) {
  prefs = p;
  if (zapisz) {
    setPref("insiders.cats", JSON.stringify(p.cats));
    setPref("insiders.sells", p.sells ? "1" : "0");
    setPref("insiders.chart", p.chart ? "1" : "0");
  }
  for (const f of [...sluchacze]) f(p);
}

/** Ustawienia insiderów z automatycznym odświeżaniem we wszystkich ekranach. */
export function useInsiderPrefs() {
  const [p, setP] = useState<Prefs>(prefs);
  useEffect(() => {
    sluchacze.add(setP);
    setP(prefs);
    wczytaj();
    return () => { sluchacze.delete(setP); };
  }, []);
  return {
    ...p,
    toggleCat(id: string) {
      const on = p.cats.includes(id);
      ustaw({ ...prefs, cats: on ? prefs.cats.filter((c) => c !== id) : [...prefs.cats, id] });
    },
    setAll(on: boolean) { ustaw({ ...prefs, cats: on ? WSZYSTKIE_KLASY : [] }); },
    setSells(on: boolean) { ustaw({ ...prefs, sells: on }); },
    setChart(on: boolean) { ustaw({ ...prefs, chart: on }); },
  };
}

// -------------------------------------------------------------------- awatar

export type Ramka = "gold" | "silver" | "bronze" | "buy" | "sell" | "plain" | "follow";

const RAMKI: Record<Ramka, [string, string]> = {
  gold: [C.gold, C.goldDeep],
  silver: ["#eef1f7", "#7d8699"],
  bronze: ["#f0b27a", "#8f5424"],
  buy: [C.green, "#1b8f5c"],
  sell: [C.red, "#b83a47"],
  follow: [C.accent, "#3358b8"],
  plain: ["#3a4660", "#232b3d"],
};

/** Twarz persony: zdjęcie w obwódce, a bez zdjęcia — kółko ze znakiem zapytania.
 *
 *  `locked` pokazuje rozmytą kopię zdjęcia (albo pusty znak zapytania) — to jest
 *  widok bez premium. Rozmycie robi serwer, nie aplikacja: plik ostry nigdy nie
 *  trafia do kogoś, kto nie powinien go zobaczyć.
 *
 *  Obwódka to gradient po skosie — ten sam metaliczny język, co przyciski
 *  aplikacji (`MetalButton`), więc medal wygląda jak medal, a nie jak kółko.
 */
export function Avatar({
  person, size = 44, ring = "plain", locked = false, blur, style, pop = false, delay = 0,
}: {
  person?: Pick<PersonaInsidera, "photo" | "blur" | "name"> | null;
  size?: number;
  ring?: Ramka;
  locked?: boolean;
  /** rozmyta kopia podana wprost (transakcja zamazana nie niesie persony) */
  blur?: string;
  style?: ViewStyle;
  /** wejście sprężyną — przy pojawieniu się na wykresie */
  pop?: boolean;
  delay?: number;
}) {
  const [blad, setBlad] = useState(false);
  const skala = useRef(new Animated.Value(pop ? 0 : 1)).current;
  useEffect(() => {
    if (!pop) return;
    Animated.spring(skala, { toValue: 1, delay, speed: 14, bounciness: 11, useNativeDriver: true }).start();
  }, []);

  const zrodlo = locked ? (blur || person?.blur || "") : (person?.photo || "");
  const uri = !blad && zrodlo ? adresZdjecia(zrodlo) : "";
  const [gora, dol] = RAMKI[ring];
  const obw = Math.max(1.5, Math.round(size * 0.06 * 2) / 2);
  const wew = size - obw * 2;

  return (
    <Animated.View style={[{ width: size, height: size, transform: [{ scale: skala }] }, style]}>
      <LinearGradient colors={[gora, dol]} start={{ x: 0.15, y: 0 }} end={{ x: 0.85, y: 1 }}
                      style={{ width: size, height: size, borderRadius: size / 2 }}>
        <View style={[st.wnetrze, { width: wew, height: wew, borderRadius: wew / 2, top: obw, left: obw }]}>
          {uri ? (
            <Image source={{ uri }} onError={() => setBlad(true)}
                   style={{ width: wew, height: wew, borderRadius: wew / 2 }}
                   // rozmycie dokłada też aplikacja: serwer podaje już mały,
                   // rozmyty plik, a to tylko wygładza piksele po powiększeniu
                   blurRadius={locked ? 2 : 0} />
          ) : (
            <Text style={[st.pytajnik, { fontSize: wew * 0.5, lineHeight: wew * 0.62 }]}>?</Text>
          )}
        </View>
      </LinearGradient>
    </Animated.View>
  );
}

const st = StyleSheet.create({
  wnetrze: {
    position: "absolute", backgroundColor: "#1a2030", alignItems: "center", justifyContent: "center",
    overflow: "hidden",
  },
  pytajnik: { color: "#8b93a7", fontWeight: "800", textAlign: "center" },
});

/** Pierwsze miejsca w kolejności ważności dostają medalową ramkę. */
export function ramkaMiejsca(i: number): Ramka {
  return i === 0 ? "gold" : i === 1 ? "silver" : i === 2 ? "bronze" : "plain";
}

/** Easing wspólny dla wejść na tym ekranie. */
export const WEJSCIE = Easing.bezier(0.22, 1, 0.36, 1);

// ------------------------------------------------------------- przełącznik

/** Przełącznik rysowany sam — systemowy `Switch` wygląda inaczej na każdej platformie. */
export function Przelacznik({ on, label, sub, onPress }: {
  on: boolean; label: string; sub?: string; onPress: () => void;
}) {
  const a = useRef(new Animated.Value(on ? 1 : 0)).current;
  useEffect(() => {
    Animated.spring(a, { toValue: on ? 1 : 0, speed: 22, bounciness: 8, useNativeDriver: false }).start();
  }, [on]);
  return (
    <Pressable onPress={onPress} style={pz.toggle} accessibilityRole="switch"
               accessibilityState={{ checked: on }}>
      <View style={{ flex: 1 }}>
        <Text style={pz.toggleLabel}>{label}</Text>
        {!!sub && <Text style={pz.toggleSub}>{sub}</Text>}
      </View>
      <Animated.View style={[pz.track, {
        backgroundColor: a.interpolate({ inputRange: [0, 1], outputRange: [C.cardHi, "rgba(47,212,138,.35)"] }),
        borderColor: a.interpolate({ inputRange: [0, 1], outputRange: [C.border2, "rgba(47,212,138,.8)"] }),
      }]}>
        <Animated.View style={[pz.knob, {
          backgroundColor: a.interpolate({ inputRange: [0, 1], outputRange: [C.muted, C.green] }),
          transform: [{ translateX: a.interpolate({ inputRange: [0, 1], outputRange: [0, 18] }) }],
        }]} />
      </Animated.View>
    </Pressable>
  );
}

const pz = StyleSheet.create({
  toggle: { flexDirection: "row", alignItems: "center", gap: 12, paddingVertical: 11 },
  toggleLabel: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  toggleSub: { color: C.dim, fontSize: 11, marginTop: 2 },
  track: {
    width: 44, height: 26, borderRadius: 13, borderWidth: 1, padding: 3, justifyContent: "center",
  },
  knob: { width: 18, height: 18, borderRadius: 9 },
});
