/** Chmurka „kod przypisany" — dla kodu wpisanego PRZED zalogowaniem.
 *
 *  Taki kod trafia do konta w tle, zaraz po zalogowaniu (`referral.ts`), a okno
 *  logowania jest już wtedy zamknięte — na webie strona wręcz przeładowała się
 *  po powrocie z Google. Bez tej chmurki nikt by się nie dowiedział, czy kod
 *  zadziałał, a to dokładnie to pytanie, z którym widz przychodzi z filmu.
 */
import React, { useEffect, useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import { dismissReferralNotice, referralNotice, subscribeReferral } from "../referral";
import { C } from "../theme";
import Icon from "../ui/Icon";

export default function ReferralNotice() {
  const [n, setN] = useState(referralNotice());

  useEffect(() => subscribeReferral(() => setN(referralNotice())), []);

  useEffect(() => {
    if (!n) return;
    const t = setTimeout(dismissReferralNotice, 8000);
    return () => clearTimeout(t);
  }, [n]);

  if (!n) return null;

  const tekst = n.ok
    ? n.reward_days
      ? `Kod ${n.code} przypisany — masz ${n.reward_days} dni premium od twórcy ${n.creator}!`
      : `Kod ${n.code} przypisany. Dzięki — wspierasz twórcę ${n.creator}.`
    : n.message || "Nie udało się przypisać kodu polecającego.";

  return (
    <View style={s.wrap} pointerEvents="box-none">
      <Pressable onPress={dismissReferralNotice} style={[s.card, n.ok ? s.ok : s.err]}>
        <Icon name={n.ok ? "ptaszek" : "zamknij"} size={14} color={n.ok ? C.green : C.red} />
        <Text style={s.txt}>{tekst}</Text>
      </Pressable>
    </View>
  );
}

const s = StyleSheet.create({
  wrap: { position: "absolute", top: 12, left: 12, right: 12, alignItems: "center" },
  card: {
    flexDirection: "row", alignItems: "center", gap: 10, maxWidth: 520,
    borderRadius: 14, borderWidth: 1, paddingHorizontal: 15, paddingVertical: 12,
    backgroundColor: C.elev,
    shadowColor: "#000", shadowOpacity: 0.45, shadowRadius: 18, shadowOffset: { width: 0, height: 8 },
  },
  ok: { borderColor: "rgba(47,212,138,.45)" },
  err: { borderColor: "rgba(255,92,108,.45)" },
  txt: { color: C.text, fontSize: 13, fontWeight: "600", lineHeight: 18, flexShrink: 1 },
});
