/** Kafel spółki w kalendarzu wyników.
 *
 *  Dwa wyróżnienia, celowo różne w charakterze:
 *   • **posiadana** — zielona ramka, która pulsuje razem z poświatą. Ruch przyciąga
 *     wzrok mocniej niż kolor, a to jest informacja typu „uwaga, to dotyczy Twoich
 *     pieniędzy", więc ma się rzucać w oczy nawet przy przewijaniu.
 *   • **obserwowana** — czerwona ramka, statyczna. Ma być widoczna, ale nie ma
 *     konkurować z pozycjami.
 *
 *  Pulsowanie robimy na `useNativeDriver`, więc animacja nie przechodzi przez most
 *  JS — przy 40 kaflach na ekranie to jedyna wersja, która nie gubi klatek.
 */
import React, { useEffect, useRef } from "react";
import { Animated, Easing, Platform, StyleSheet, Text, View } from "react-native";
import { EarningsCompany } from "../../api";
import Logo from "../../components/Logo";
import { C } from "../../theme";
import { Press } from "../../ui";

export const TILE_RADIUS = 15;

/** Pętla animacji „oddechu" — wspólny rytm dla kafla i dla legendy, żeby ruch na
 *  ekranie był jeden, a nie kilka rozjeżdżających się.
 *
 *  Na telefonie jedzie sterownikiem natywnym: przy kilkudziesięciu kaflach naraz
 *  animacja nie może przechodzić przez most JS. Na webie (podgląd `expo start --web`)
 *  natywnej warstwy nie ma, więc jawnie prosimy o sterownik JS.
 */
export function usePulse(active: boolean) {
  const value = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (!active) return;
    const step = (toValue: number, easing: (v: number) => number) =>
      Animated.timing(value, {
        toValue, duration: 1100, easing,
        useNativeDriver: Platform.OS !== "web",
      });
    const loop = Animated.loop(Animated.sequence([
      step(1, Easing.out(Easing.quad)),
      step(0, Easing.in(Easing.quad)),
    ]));
    loop.start();
    return () => loop.stop();
  }, [active]);
  return value;
}

export default function CompanyTile({
  item, size, onPress,
}: { item: EarningsCompany; size: number; onPress: () => void }) {
  const pulse = usePulse(item.owned);

  const frame = item.owned ? C.green : item.watched ? C.red : "transparent";
  const box = { width: size, height: size, borderRadius: TILE_RADIUS };

  return (
    <Press style={{ width: size }} onPress={onPress}>
      <View>
        {/* poświata pod kaflem — tylko dla pozycji; „oddycha" w tym samym rytmie
            co ramka, przez co pulsowanie czyta się jako jeden ruch, nie dwa */}
        {item.owned && (
          <Animated.View
            pointerEvents="none"
            style={[
              s.glow,
              {
                borderRadius: TILE_RADIUS + 6,
                opacity: pulse.interpolate({ inputRange: [0, 1], outputRange: [0.12, 0.5] }),
                transform: [{ scale: pulse.interpolate({ inputRange: [0, 1], outputRange: [1, 1.08] }) }],
              },
            ]}
          />
        )}
        <Animated.View
          style={[
            s.frame,
            box,
            frame !== "transparent" && { borderColor: frame, borderWidth: 2 },
            item.owned && {
              opacity: pulse.interpolate({ inputRange: [0, 1], outputRange: [0.72, 1] }),
            },
          ]}
        >
          <Logo ticker={item.symbol} size={size - 8} radius={TILE_RADIUS - 4} />
        </Animated.View>
      </View>

      <Text style={[s.ticker, item.owned && { color: C.green }, item.watched && { color: C.red }]}
            numberOfLines={1}>
        {item.symbol.replace(".WA", "")}
      </Text>
      {item.market === "PL" && <Text style={s.market}>GPW</Text>}
    </Press>
  );
}

const s = StyleSheet.create({
  glow: {
    ...StyleSheet.absoluteFillObject,
    margin: -6, backgroundColor: C.green,
  },
  frame: {
    backgroundColor: "#fff", alignItems: "center", justifyContent: "center",
    overflow: "hidden", borderWidth: 0,
  },
  ticker: {
    color: C.muted, fontSize: 10.5, fontWeight: "800", textAlign: "center",
    marginTop: 5, letterSpacing: 0.2,
  },
  market: { color: C.dim, fontSize: 8, fontWeight: "800", textAlign: "center", letterSpacing: 0.6 },
});
