/** Mały przycisk „?" do postawienia obok nagłówka wgrywania. */
export function ReportHelpButton({ onPress }: { onPress: () => void }) {
  return (
    <Pressable onPress={onPress} hitSlop={10} style={s.qBtn}>
      <Text style={s.qTxt}>?</Text>
    </Pressable>
  );
}

export default function ReportHelp({ onClose }: { onClose: () => void }) {
  return (
    <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}>
      <View style={s.root}>
        <View style={s.bar}>
          <Text style={s.barTitle}>JAK POBRAĆ RAPORT</Text>
          <Pressable onPress={onClose} hitSlop={12} style={s.close}>
            <Icon name="zamknij" size={15} color={C.muted} />
          </Pressable>
        </View>

        <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
          <FadeIn>
            <Text style={s.h1}>Raport z XTB w cztery kroki</Text>
            <Text style={s.lead}>
              Zajmuje to niecałą minutę. Raport pobierasz w przeglądarce, na stronie XTB —
              nie w aplikacji na telefonie.
            </Text>
          </FadeIn>

          {KROKI.map((k, i) => (
            <FadeIn key={k.plik} delay={Math.min(i * 60, 240)} offset={10}>
              <View style={s.krok}>
                <View style={s.krokNag}>
                  <View style={s.nr}><Text style={s.nrTxt}>{i + 1}</Text></View>
                  <View style={{ flex: 1 }}>
                    <Text style={s.krokTytul}>{k.tytul}</Text>
                    <Text style={s.krokOpis}>{k.opis}</Text>
                  </View>
                </View>
                <Zrzut plik={k.plik} aspekt={k.aspekt} numer={i + 1} />
              </View>
            </FadeIn>
          ))}

          <Text style={s.sek}>Częste pytania</Text>
          <View style={{ gap: 9 }}>
            {FAQ.map((f, i) => <FaqWiersz key={f.q} q={f.q} a={f.a} delay={Math.min(i * 30, 200)} />)}
          </View>

          <MetalButton label="Rozumiem — wracam do wgrywania" tone="green" active liquid full
                       style={{ marginTop: 22 }} onPress={onClose} />
          <Text style={{ color: C.dim, fontSize: 11, textAlign: "center", marginTop: 28, lineHeight: 16 }}>
            Portevo jest niezależną aplikacją analityczną i nie jest powiązana ani sponsorowana przez XTB S.A.
          </Text>
        </ScrollView>
      </View>
    </Modal>
  );
}

/** Obrazek kroku. Sam radzi sobie z brakiem pliku i z tym, że w apce na telefonie
 *  adres `/static/...` trzeba dokleić do adresu panelu — przeglądarka weźmie go
 *  względem siebie, telefon nie ma pojęcia, gdzie to jest. */
function Zrzut({ plik, aspekt, numer }: { plik: string; aspekt: number; numer: number }) {
  const [brak, setBrak] = useState(false);
  const zrodlo = useMemo(() => {
    const base = (getConfig().baseUrl || "").replace(/\/+$/, "");
    return { uri: base ? base + plik : plik };
  }, [plik]);

  if (brak) {
    return (
      <View style={[s.ramka, s.ramkaPusta, { aspectRatio: aspekt }]}>
        <Text style={s.pustyTxt}>zrzut kroku {numer}</Text>
      </View>
    );
  }

  return (
    <View style={[s.ramka, { aspectRatio: aspekt }]}>
      <Image source={zrodlo} style={s.obraz} resizeMode="contain" onError={() => setBrak(true)} />
    </View>
  );
}

function FaqWiersz({ q, a, delay }: { q: string; a: string; delay: number }) {
  const [open, setOpen] = useState(false);
  return (
    <FadeIn delay={delay} offset={8}>
      <Pressable onPress={() => setOpen((v) => !v)}>
        <Card style={s.faq}>
          <View style={s.faqNag}>
            <Text style={s.faqQ}>{q}</Text>
            <Text style={s.faqZnak}>{open ? "−" : "+"}</Text>
          </View>
          {open && <Text style={s.faqA}>{a}</Text>}
        </Card>
      </Pressable>
    </FadeIn>
  );
}

