/** Kalendarz wyników finansowych — główny ekran sekcji Earnings.
 *
 *  Trzy rozdzielczości tego samego kalendarza:
 *    • **Dziś** — jeden dzień, spółki jako wiersze z konsensusem EPS,
 *    • **Tydzień** — dzień po dniu, spółki jako kafle z logotypami,
 *    • **Miesiąc** — siatka 7 kolumn; dotknięcie dnia przechodzi do widoku dziennego.
 *
 *  Nad spółkami każdego dnia leży pasek wydarzeń ekonomicznych — decyzje banków
 *  centralnych dostają czerwoną płytkę, bo przestawiają cały rynek naraz, a nie
 *  pojedynczą spółkę.
 *
 *  Wyróżnienia kafli (zielona pulsująca ramka = pozycja, czerwona = obserwowana)
 *  liczy serwer, bo tylko on wie, co siedzi w portfelu — patrz `_my_symbols` w panelu.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator, RefreshControl, ScrollView, StyleSheet, Text, View,
} from "react-native";
import {
  EarningsCalendar, EarningsCompany, EarningsDay, EconEvent, getEarningsCalendar,
  getPref, setPref,
} from "../../api";
import { useLayout, TAB_SPACE } from "../../layout";
import Logo from "../../components/Logo";
import { C, fmtBig, plural, T } from "../../theme";
import { Card, FadeIn, MetalButton, Press, Segmented } from "../../ui";
import Icon, { IconName } from "../../ui/Icon";
import CompanyTile from "./CompanyTile";
import EventChip from "./EventChip";
import EventModal from "./EventModal";
import ReportModal from "./ReportModal";

const RANGES = [
  { id: "day", label: "Dziś" },
  { id: "week", label: "Tydzień" },
  { id: "month", label: "Miesiąc" },
];

const FILTERS = [
  { id: "popular", label: "Popularne" },
  { id: "cap100b", label: "100 mld+" },
  { id: "cap10b", label: "10 mld+" },
  { id: "cap1b", label: "1 mld+" },
  { id: "all", label: "Wszystkie" },
];

const SORTS = [
  { id: "popular", label: "Popularność" },
  { id: "time", label: "Godzina" },
  { id: "cap", label: "Kapitalizacja" },
  { id: "estimates", label: "Liczba prognoz" },
  { id: "alpha", label: "Alfabetycznie" },
];

const IMPORTANCE = [
  { id: "3", label: "Tylko wysokie" },
  { id: "2", label: "Średnie i wyższe" },
  { id: "1", label: "Wszystkie odczyty" },
];

const SCOPES = [
  { id: "core", label: "Polska i USA" },
  { id: "all", label: "Cały świat" },
];

const SESSIONS: { id: "bmo" | "amc" | "tbd"; label: string; icon: IconName }[] = [
  { id: "bmo", label: "Przed otwarciem", icon: "slonce" },
  { id: "amc", label: "Po zamknięciu", icon: "ksiezyc" },
  { id: "tbd", label: "Godzina nieznana", icon: "zegar" },
];

const MONTHS = ["stycznia", "lutego", "marca", "kwietnia", "maja", "czerwca", "lipca",
                "sierpnia", "września", "października", "listopada", "grudnia"];
const MONTHS_NOM = ["Styczeń", "Luty", "Marzec", "Kwiecień", "Maj", "Czerwiec", "Lipiec",
                    "Sierpień", "Wrzesień", "Październik", "Listopad", "Grudzień"];
const DOW = ["Pn", "Wt", "Śr", "Cz", "Pt", "So", "Nd"];

const iso = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

const addDays = (d: Date, n: number) => {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
};

/** Poniedziałek tygodnia, w którym leży `d` (w Polsce tydzień zaczyna się w poniedziałek). */
function monday(d: Date) {
  const x = new Date(d);
  x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
  x.setHours(0, 0, 0, 0);
  return x;
}

/** Zakres dat dla trybu i przesunięcia — `offset` liczy dni/tygodnie/miesiące od dziś. */
function rangeFor(mode: string, offset: number) {
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  if (mode === "day") {
    const d = addDays(now, offset);
    return { start: iso(d), end: iso(d), anchor: d };
  }
  if (mode === "month") {
    const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
    const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
    return { start: iso(first), end: iso(last), anchor: first };
  }
  const from = addDays(monday(now), offset * 7);
  return { start: iso(from), end: iso(addDays(from, 6)), anchor: from };
}

function rangeLabel(mode: string, offset: number) {
  const { anchor, start, end } = rangeFor(mode, offset);
  if (mode === "day") {
    return `${anchor.getDate()} ${MONTHS[anchor.getMonth()]}`;
  }
  if (mode === "month") {
    return `${MONTHS_NOM[anchor.getMonth()]} ${anchor.getFullYear()}`;
  }
  const a = new Date(start + "T00:00:00");
  const b = new Date(end + "T00:00:00");
  return a.getMonth() === b.getMonth()
    ? `${a.getDate()}–${b.getDate()} ${MONTHS[a.getMonth()]}`
    : `${a.getDate()} ${MONTHS[a.getMonth()].slice(0, 3)} – ${b.getDate()} ${MONTHS[b.getMonth()].slice(0, 3)}`;
}

export default function EarningsScreen({ visible }: { visible: boolean }) {
  // szerokość KOLUMNY treści, nie całego okna — siatka miesiąca musi się w niej
  // zmieścić, a na komputerze kolumna jest węższa niż ekran
  const { column: width } = useLayout();
  const [mode, setMode] = useState("week");
  const [offset, setOffset] = useState(0);
  const [filter, setFilter] = useState("popular");
  const [sort, setSort] = useState("popular");
  const [importance, setImportance] = useState("2");
  const [scope, setScope] = useState("core");
  const [settings, setSettings] = useState(false);

  const [data, setData] = useState<EarningsCalendar | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const [openSymbol, setOpenSymbol] = useState<string | null>(null);
  const [openTime, setOpenTime] = useState<"bmo" | "amc" | "tbd">("tbd");
  const [openEvent, setOpenEvent] = useState<EconEvent | null>(null);
  const [profileSymbol, setProfileSymbol] = useState<string | null>(null);

  // ustawienia trzymamy na telefonie — wracasz do sekcji i widzisz swój filtr
  useEffect(() => {
    getPref("earn.filter", "popular").then(setFilter);
    getPref("earn.sort", "popular").then(setSort);
    getPref("earn.importance", "2").then(setImportance);
    getPref("earn.scope", "core").then(setScope);
    getPref("earn.mode", "week").then(setMode);
  }, []);

  const { start, end } = useMemo(() => rangeFor(mode, offset), [mode, offset]);

  //  Strażnik kolejności. Szybkie przeklikiwanie zakresów wypuszcza kilka żądań
  //  naraz, a odpowiedzi wracają w dowolnej kolejności — bez tego licznika starsza
  //  odpowiedź potrafiła nadpisać nowszą i ekran pokazywał inny tydzień, niż mówił
  //  nagłówek. Liczy się wyłącznie ostatnie wysłane żądanie.
  const reqId = useRef(0);
  const alive = useRef(true);
  //  Flagę trzeba PODNIEŚĆ przy każdym uruchomieniu efektu, nie tylko opuścić przy
  //  sprzątaniu. React potrafi wywołać efekt → sprzątanie → efekt ponownie (tryb
  //  ścisły, remount po bezpieczniku) — przy samym sprzątaniu flaga zostawała na
  //  `false` i każda odpowiedź była wyrzucana, a ekran wisiał na „Zbieram…".
  useEffect(() => {
    alive.current = true;
    return () => { alive.current = false; };
  }, []);

  const load = useCallback(async (quiet = false) => {
    const my = ++reqId.current;
    try {
      const d = await getEarningsCalendar({
        start, end, filter, sort,
        // w miesiącu kafle są maleńkie, więc nie ma sensu ciągnąć czterdziestu spółek na dzień
        limit: mode === "month" ? 8 : mode === "day" ? 60 : 40,
        importance: Number(importance),
        scope: scope as "core" | "all",
      });
      if (!alive.current || my !== reqId.current) return;
      setData(d);
      setErr("");
    } catch (e: any) {
      if (!alive.current || my !== reqId.current) return;
      // ciche doładowanie nie ma prawa skasować tego, co użytkownik już widzi
      if (!quiet) setErr(e?.message || "Nie udało się pobrać kalendarza");
    } finally {
      if (alive.current && my === reqId.current) {
        setLoading(false);
        setBusy(false);
      }
    }
  }, [start, end, filter, sort, importance, scope, mode]);

  useEffect(() => {
    if (!visible) return;
    setLoading(true);
    load();
  }, [load, visible]);

  //  Serwer oddaje kalendarz etapami: najpierw to, co ma w cache, resztę dociąga
  //  w tle. Póki są dni oznaczone jako `pending`, wracamy po uzupełnienie —
  //  użytkownik widzi dane od razu, a brakujące dni dosypują się same.
  const incomplete = Boolean(data && data.complete === false);
  useEffect(() => {
    if (!visible || !incomplete) return;
    const timer = setTimeout(() => load(true), 6000);
    return () => clearTimeout(timer);
  }, [visible, incomplete, data, load]);

  const pick = (key: string, value: string, set: (v: string) => void) => {
    set(value);
    setPref(key, value);
  };

  const mine = useMemo(() => {
    if (!data) return [] as { day: EarningsDay; company: EarningsCompany }[];
    const out: { day: EarningsDay; company: EarningsCompany }[] = [];
    for (const day of data.days) {
      for (const c of day.companies) if (c.owned || c.watched) out.push({ day, company: c });
    }
    return out;
  }, [data]);

  const openCompany = (c: EarningsCompany) => {
    setOpenTime(c.time);
    setOpenSymbol(c.symbol);
  };

  return (
    <>
      <ScrollView
        contentContainerStyle={s.wrap}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={busy} tintColor={C.green}
                          onRefresh={() => { setBusy(true); load(); }} />
        }
      >
        <FadeIn>
          <View style={s.head}>
            <View style={{ flex: 1 }}>
              <Text style={s.h1}>Kalendarz wyników</Text>
              <Text style={s.sub}>Publikacje spółek i wydarzenia makro</Text>
            </View>
            <Press onPress={() => setSettings((v) => !v)} style={[s.gear, settings && s.gearOn]}>
              <Icon name="dev" size={15} color={settings ? C.green : C.muted} />
            </Press>
          </View>
        </FadeIn>

        <View style={{ marginTop: 15 }}>
          <Segmented options={RANGES} value={mode}
                     onChange={(v) => { pick("earn.mode", v, setMode); setOffset(0); }}
                     tone="green" liquid />
        </View>

        {/* nawigacja po zakresie */}
        <View style={s.nav}>
          <Press onPress={() => setOffset((o) => o - 1)} style={s.navBtn}>
            <Text style={s.navTxt}>‹</Text>
          </Press>
          <Press onPress={() => setOffset(0)} style={{ flex: 1 }}>
            <Text style={s.navLabel} numberOfLines={1}>{rangeLabel(mode, offset)}</Text>
            {offset !== 0 && <Text style={s.navBack}>dotknij, żeby wrócić do dziś</Text>}
          </Press>
          <Press onPress={() => setOffset((o) => o + 1)} style={s.navBtn}>
            <Text style={s.navTxt}>›</Text>
          </Press>
        </View>

        {settings && (
          <FadeIn offset={-8}>
            <Card style={s.settings}>
              <Group title="Które spółki" options={FILTERS} value={filter}
                     onChange={(v) => pick("earn.filter", v, setFilter)} />
              <Group title="Kolejność" options={SORTS} value={sort}
                     onChange={(v) => pick("earn.sort", v, setSort)} />
              <Group title="Wydarzenia ekonomiczne" options={IMPORTANCE} value={importance}
                     onChange={(v) => pick("earn.importance", v, setImportance)} />
              <Group title="Zasięg geograficzny" options={SCOPES} value={scope}
                     onChange={(v) => pick("earn.scope", v, setScope)} last />
              <Text style={s.settingsFoot}>
                „Popularne" stawia najpierw Twoje pozycje i obserwowane, dalej sortuje po
                kapitalizacji i liczbie prognoz analityków. Polskie odczyty makro pokazujemy
                zawsze, niezależnie od progu wagi. Przy zasięgu „Polska i USA" z pozostałych
                krajów przechodzą tylko odczyty najwyższej wagi i decyzje o stopach — bez tego
                jeden czwartek potrafi mieć kilkadziesiąt pozycji z pół świata.
              </Text>
            </Card>
          </FadeIn>
        )}

        {loading ? (
          <View style={s.center}>
            <ActivityIndicator color={C.green} size="large" />
            <Text style={s.loadingTxt}>Zbieram kalendarz z giełd i kalendarza makro…</Text>
          </View>
        ) : err ? (
          <View style={s.center}>
            <Text style={s.errTxt}>{err}</Text>
            <MetalButton label="Spróbuj ponownie" tone="green"
                         onPress={() => { setLoading(true); load(); }} />
          </View>
        ) : !data ? null : (
          <>
            {incomplete && (
              <View style={s.filling}>
                <ActivityIndicator color={C.green} size="small" />
                <Text style={s.fillingTxt}>
                  Uzupełniam {data.pending_days?.length || 0}{" "}
                  {plural(data.pending_days?.length || 0, "dzień", "dni", "dni")} —
                  reszta jest już widoczna
                </Text>
              </View>
            )}

            {mine.length > 0 && mode !== "month" && (
              <MineStrip rows={mine} onPress={openCompany} />
            )}

            {mode === "month" ? (
              <MonthGrid data={data} width={width - 36}
                         onPickDay={(date) => {
                           const target = new Date(date + "T00:00:00");
                           const today = new Date();
                           today.setHours(0, 0, 0, 0);
                           setMode("day");
                           setOffset(Math.round((target.getTime() - today.getTime()) / 86400000));
                         }} />
            ) : (
              data.days.map((day, i) => (
                <DaySection
                  key={day.date} day={day} index={i} width={width - 36}
                  detailed={mode === "day"}
                  onCompany={openCompany} onEvent={setOpenEvent}
                />
              ))
            )}

            <Text style={s.sourceFoot}>
              Źródła: Nasdaq (kalendarz wyników), Yahoo Finance (GPW i konsensus),
              FXStreet (kalendarz makro). Terminy publikacji bywają przesuwane przez spółki.
            </Text>
          </>
        )}
      </ScrollView>

      <ReportModal
        symbol={openSymbol} time={openTime}
        onClose={() => setOpenSymbol(null)}
        onOpenProfile={(sym) => { setOpenSymbol(null); setProfileSymbol(sym); }}
      />
      <EventModal event={openEvent} onClose={() => setOpenEvent(null)} />
      <LazyCompany symbol={profileSymbol} onClose={() => setProfileSymbol(null)} />
    </>
  );
}

/** Profil spółki ładujemy dopiero przy pierwszym wejściu — to ciężki ekran z wykresem. */
function LazyCompany({ symbol, onClose }: { symbol: string | null; onClose: () => void }) {
  const [Comp, setComp] = useState<React.ComponentType<any> | null>(null);
  useEffect(() => {
    if (symbol && !Comp) {
      import("../CompanyScreen").then((m) => setComp(() => m.default)).catch(() => {});
    }
  }, [symbol]);
  if (!Comp) return null;
  return <Comp symbol={symbol} onClose={onClose} />;
}

/* --------------------------------------------------------------- dzień */

/** Dni z odczytami z pół świata potrafią mieć 45 pozycji makro — resztę rozwijamy na żądanie. */
const EVENT_CAP = 6;

/** Podpis pod dniem. Rozróżnia trzy różne „zera", bo znaczą co innego:
 *  dane jeszcze lecą, spółki nie ogłosiły terminów, albo naprawdę nikt nie raportuje. */
function dayCountLabel(day: EarningsDay): string {
  if (day.pending) return "wczytuję…";
  if (day.matched > 0) {
    return `${day.matched} ${plural(day.matched, "spółka", "spółki", "spółek")}`;
  }
  if (day.total > 0) return "nic nie przeszło filtra";
  // Nasdaq publikuje terminy z około sześciotygodniowym wyprzedzeniem — dalej
  // pusty dzień nie znaczy „nikt nie raportuje", tylko „jeszcze nie wiadomo"
  return day.is_past ? "brak publikacji" : "terminy jeszcze nieogłoszone";
}

function DaySection({
  day, index, width, detailed, onCompany, onEvent,
}: {
  day: EarningsDay; index: number; width: number; detailed: boolean;
  onCompany: (c: EarningsCompany) => void;
  onEvent: (e: EconEvent) => void;
}) {
  const [allEvents, setAllEvents] = useState(false);
  const perRow = detailed ? 5 : 4;
  const gap = 10;
  const tile = Math.floor((width - gap * (perRow - 1)) / perRow);

  const groups = SESSIONS
    .map((sess) => ({ ...sess, items: day.companies.filter((c) => c.time === sess.id) }))
    .filter((g) => g.items.length > 0);

  if (day.weekend && !day.events.length && !day.companies.length && !day.pending) return null;

  return (
    <FadeIn delay={Math.min(index * 45, 220)}>
      <View style={s.day}>
        <View style={s.dayHead}>
          <View style={[s.dayMark, day.is_today && s.dayMarkNow]}>
            <Text style={[s.dayNum, day.is_today && { color: C.green }]}>
              {day.date.slice(8, 10)}
            </Text>
          </View>
          <View style={{ flex: 1 }}>
            <Text style={[s.dayName, day.is_today && { color: C.green }]}>
              {day.weekday}{day.is_today ? " · dziś" : ""}
            </Text>
            <Text style={[s.dayCount, day.pending && s.pendingDay]}>
              {dayCountLabel(day)}
              {day.total > day.matched ? ` z ${day.total}` : ""}
              {day.mine_count > 0 ? ` · ${day.mine_count} Twoich` : ""}
            </Text>
          </View>
          {day.pending && <ActivityIndicator color={C.green} size="small" />}
          {day.events.length > 0 && (
            <View style={s.evCount}>
              <Text style={s.evCountTxt}>{day.events.length} makro</Text>
            </View>
          )}
        </View>

        {day.events.length > 0 && (
          <ScrollView horizontal showsHorizontalScrollIndicator={false}
                      contentContainerStyle={s.events}>
            {(allEvents ? day.events : day.events.slice(0, EVENT_CAP)).map((e) => (
              <EventChip key={e.id} event={e} onPress={() => onEvent(e)} />
            ))}
            {!allEvents && day.events.length > EVENT_CAP && (
              <Press onPress={() => setAllEvents(true)}>
                <View style={s.moreEv}>
                  <Text style={s.moreEvTxt}>+{day.events.length - EVENT_CAP}</Text>
                  <Text style={s.moreEvSub}>więcej</Text>
                </View>
              </Press>
            )}
          </ScrollView>
        )}

        {groups.map((g) => (
          <View key={g.id} style={{ marginTop: 14 }}>
            <View style={s.sessHead}>
              <Icon name={g.icon} size={13} color={C.muted} />
              <Text style={s.sessLabel}>{g.label}</Text>
              <Text style={s.sessCount}>{g.items.length}</Text>
            </View>
            {detailed ? (
              <View style={{ gap: 8 }}>
                {g.items.map((c) => (
                  <CompanyRow key={c.symbol} item={c} onPress={() => onCompany(c)} />
                ))}
              </View>
            ) : (
              <View style={[s.grid, { gap }]}>
                {g.items.map((c) => (
                  <CompanyTile key={c.symbol} item={c} size={tile}
                               onPress={() => onCompany(c)} />
                ))}
              </View>
            )}
          </View>
        ))}

        {day.hidden > 0 && (
          <Text style={s.hidden}>
            + {day.hidden} {plural(day.hidden, "spółka", "spółki", "spółek")} poza limitem widoku
          </Text>
        )}
      </View>
    </FadeIn>
  );
}

/** Wiersz spółki w widoku dziennym — jest miejsce na konsensus, więc go pokazujemy. */
function CompanyRow({ item, onPress }: { item: EarningsCompany; onPress: () => void }) {
  const frame = item.owned ? C.green : item.watched ? C.red : C.border;
  return (
    <Press onPress={onPress}>
      <View style={[s.row, { borderColor: item.owned || item.watched ? frame : C.border }]}>
        <Logo ticker={item.symbol} size={38} radius={11} />
        <View style={{ flex: 1 }}>
          <Text style={[s.rowSym, item.owned && { color: C.green }, item.watched && { color: C.red }]}>
            {item.symbol.replace(".WA", "")}
            {item.market === "PL" ? "  ·  GPW" : ""}
          </Text>
          <Text style={s.rowName} numberOfLines={1}>{item.name}</Text>
        </View>
        <View style={{ alignItems: "flex-end" }}>
          <Text style={s.rowEps}>
            {item.eps_forecast != null
              ? `${item.eps_forecast.toFixed(2).replace(".", ",")} ${item.currency}`
              : "—"}
          </Text>
          <Text style={s.rowSub}>
            {item.estimates ? `${item.estimates} prognoz` : "prognoza EPS"}
          </Text>
          {item.market_cap != null && (
            <Text style={s.rowCap}>{fmtBig(item.market_cap, item.currency)}</Text>
          )}
        </View>
      </View>
    </Press>
  );
}

/* --------------------------------------------------------------- miesiąc */

function MonthGrid({
  data, width, onPickDay,
}: { data: EarningsCalendar; width: number; onPickDay: (date: string) => void }) {
  const gap = 5;
  const cell = Math.floor((width - gap * 6) / 7);

  // pierwszy dzień miesiąca rzadko wypada w poniedziałek — dopełniamy pustymi polami
  const first = new Date(data.days[0]?.date + "T00:00:00");
  const blanks = Number.isNaN(first.getTime()) ? 0 : (first.getDay() + 6) % 7;

  return (
    <View style={{ marginTop: 18 }}>
      <View style={[s.monthRow, { gap }]}>
        {DOW.map((d) => (
          <Text key={d} style={[s.dow, { width: cell }]}>{d}</Text>
        ))}
      </View>
      <View style={[s.monthRow, { gap, flexWrap: "wrap" }]}>
        {Array.from({ length: blanks }).map((_, i) => (
          <View key={`b${i}`} style={{ width: cell, height: cell * 1.28 }} />
        ))}
        {data.days.map((day) => (
          <Press key={day.date} onPress={() => onPickDay(day.date)}>
            <View style={[
              s.cell,
              { width: cell, height: cell * 1.28 },
              day.is_today && s.cellNow,
              day.weekend && s.cellWeekend,
            ]}>
              <View style={s.cellHead}>
                <Text style={[s.cellNum, day.is_today && { color: C.green }]}>
                  {day.date.slice(8, 10)}
                </Text>
                {day.events.some((e) => e.kind === "fed" || e.kind === "cb") && (
                  <View style={s.cellFed} />
                )}
              </View>
              <View style={s.cellLogos}>
                {day.companies.slice(0, 4).map((c) => (
                  <View key={c.symbol}
                        style={[
                          s.cellLogo,
                          c.owned && { borderColor: C.green, borderWidth: 1.5 },
                          c.watched && { borderColor: C.red, borderWidth: 1.5 },
                        ]}>
                    <Logo ticker={c.symbol} size={cell * 0.32} radius={4} />
                  </View>
                ))}
              </View>
              {day.matched > 0 && (
                <Text style={s.cellCount}>{day.matched}</Text>
              )}
            </View>
          </Press>
        ))}
      </View>
      <Text style={s.monthHint}>Dotknij dnia, żeby zobaczyć pełną listę publikacji.</Text>
    </View>
  );
}

/* --------------------------------------------------------------- drobiazgi */

/** Pasek „Twoje w tym okresie" — pozycje i obserwowane wyciągnięte na wierzch. */
function MineStrip({
  rows, onPress,
}: {
  rows: { day: EarningsDay; company: EarningsCompany }[];
  onPress: (c: EarningsCompany) => void;
}) {
  return (
    <FadeIn>
      <View style={s.mineWrap}>
        <Text style={s.mineTitle}>
          Twoje w tym okresie · {rows.length}
        </Text>
        <ScrollView horizontal showsHorizontalScrollIndicator={false}
                    contentContainerStyle={{ gap: 9, paddingRight: 4 }}>
          {rows.map(({ day, company }) => (
            <Press key={day.date + company.symbol} onPress={() => onPress(company)}>
              <View style={[
                s.mineCard,
                { borderColor: company.owned ? "rgba(47,212,138,.45)" : "rgba(255,92,108,.45)" },
              ]}>
                <Logo ticker={company.symbol} size={30} radius={9} />
                <View>
                  <Text style={[s.mineSym, { color: company.owned ? C.green : C.red }]}>
                    {company.symbol.replace(".WA", "")}
                  </Text>
                  <Text style={s.mineDay}>
                    {day.weekday.slice(0, 3)} {day.date.slice(8, 10)}.{day.date.slice(5, 7)}
                  </Text>
                </View>
              </View>
            </Press>
          ))}
        </ScrollView>
      </View>
    </FadeIn>
  );
}

function Group({
  title, options, value, onChange, last,
}: {
  title: string; options: { id: string; label: string }[]; value: string;
  onChange: (v: string) => void; last?: boolean;
}) {
  return (
    <View style={[s.group, last && { borderBottomWidth: 0, paddingBottom: 0 }]}>
      <Text style={s.groupTitle}>{title}</Text>
      <View style={s.pills}>
        {options.map((o) => (
          <MetalButton key={o.id} label={o.label} size="sm" tone="green"
                       active={value === o.id} liquid
                       onPress={() => onChange(o.id)} />
        ))}
      </View>
    </View>
  );
}

