/** Widoczny przycisk „odśwież" — bo w przeglądarce nie ma czego pociągnąć.
 *
 *  Wszystkie ekrany portfela odświeżały się wyłącznie gestem `RefreshControl`:
 *  chwytasz zawartość i ciągniesz w dół. Na telefonie to naturalne, myszą nie da
 *  się tego zrobić w ogóle — a to jedyny sposób na wymuszenie odczytu na stronie.
 *  Ekran, który raz pobrał stare dane, zostawał z nimi na zawsze.
 *
 *  Przycisk zostaje też na telefonie: gest dalej działa, a jawny przycisk nikomu
 *  nie przeszkadza i widać po nim, że dane da się odświeżyć.
 */
import React, { useEffect, useRef } from "react";
import { Animated, Easing, Pressable, StyleSheet, Text } from "react-native";
import { C } from "../theme";
import Icon from "./Icon";

export default function RefreshButton({
  busy = false, onPress, style,
}: {
  busy?: boolean;
  onPress: () => void;
  style?: any;
}) {
  const obrot = useRef(new Animated.Value(0)).current;
  const petla = useRef<Animated.CompositeAnimation | null>(null);

  useEffect(() => {
    if (busy) {
      obrot.setValue(0);
      petla.current = Animated.loop(Animated.timing(obrot, {
        toValue: 1, duration: 900, easing: Easing.linear, useNativeDriver: true,
      }));
      petla.current.start();
    } else {
      petla.current?.stop();
      petla.current = null;
      obrot.setValue(0);
    }
    return () => { petla.current?.stop(); };
  }, [busy, obrot]);

  const spin = obrot.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "360deg"] });

  return (
    <Pressable onPress={busy ? undefined : onPress} disabled={busy}
               accessibilityRole="button" accessibilityLabel="Odśwież dane"
               style={({ pressed }) => [s.btn, pressed && s.pressed, style]}>
      <Animated.View style={{ transform: [{ rotate: spin }] }}>
        <Icon name="odswiez" size={16} color={C.muted} />
      </Animated.View>
    </Pressable>
  );
}

const s = StyleSheet.create({
  btn: {
    width: 34, height: 34, borderRadius: 17,
    alignItems: "center", justifyContent: "center",
    borderWidth: 1, borderColor: C.border2,
    backgroundColor: "rgba(255,255,255,.05)",
  },
  pressed: { opacity: 0.55 },
});
