/** Wspólne klocki narzędzia dywidendowego — używane przez wszystkie cztery zakładki.
 *
 *  Trzymamy je osobno, bo inaczej ocena bezpieczeństwa wyglądałaby inaczej
 *  w skanerze, inaczej w porównywarce i inaczej w portfelu, a to jest ta sama
 *  liczba i musi znaczyć to samo za każdym razem. Jedno miejsce = jeden wygląd.
 */
import React, { useState } from "react";
import {
  LayoutAnimation, Platform, Pressable, StyleSheet, Text, useWindowDimensions, View,
} from "react-native";
import Logo from "../../../components/Logo";
import { C, T } from "../../../theme";

/** Od tylu pikseli układamy karty w dwie kolumny.
 *
 *  Narzędzie otwiera się na cały ekran, więc na monitorze wiersz spółki
 *  rozciągałby się na 1400 px: nazwa przy lewej krawędzi, stopa przy prawej,
 *  a pomiędzy nimi pół metra pustki, po której oko musi wędrować. Dwie kolumny
 *  robią z tego czytelne kafle i mieszczą dwa razy więcej treści bez przewijania.
 */
export const PROG_DWIE_KOLUMNY = 900;

export function useSzerokoscUkladu() {
  const { width } = useWindowDimensions();
  return { szeroko: width >= PROG_DWIE_KOLUMNY, width };
}

/** Znak firmowy spółki. Logotypy mamy u siebie (`/static/seo/logos/SYMBOL.png`),
 *  ale komponent `Logo` z aplikacji zna już dwa zewnętrzne źródła i monogram
 *  jako ostatnią deskę ratunku — nie ma sensu robić trzeciej ścieżki obok. */
export function Znak({ symbol, nazwa, rozmiar = 34 }:
  { symbol: string; nazwa?: string; rozmiar?: number }) {
  return <Logo ticker={symbol} name={nazwa} size={rozmiar} radius={9} />;
}

/** Kolor oceny bezpieczeństwa. Skala jest celowo krótka i zawsze ta sama. */
export function kolorOceny(poziom?: string): string {
  switch (poziom) {
    case "wysokie": return C.green;
    case "srednie": return "#7dd3fc";
    case "niskie": return C.amber;
    case "ryzykowne": return C.red;
    default: return C.dim;
  }
}

export function etykietaOceny(poziom?: string): string {
  switch (poziom) {
    case "wysokie": return "Ugruntowana";
    case "srednie": return "Solidna";
    case "niskie": return "Wątpliwa";
    case "ryzykowne": return "Ryzykowna";
    default: return "Brak danych";
  }
}

/** Odznaka z oceną — tarcza 0–100 plus słowo, bo sama liczba nic nie mówi. */
export function OdznakaOceny({ ocena, poziom, male = false }:
  { ocena: number | null; poziom?: string; male?: boolean }) {
  const kolor = kolorOceny(poziom);
  if (ocena === null || ocena === undefined) {
    return (
      <View style={[s.badge, { borderColor: C.border2 }, male && s.badgeSm]}>
        <Text style={[s.badgeTxt, { color: C.dim }, male && s.badgeTxtSm]}>—</Text>
      </View>
    );
  }
  return (
    <View style={[s.badge, { borderColor: kolor, backgroundColor: kolor + "1a" },
                  male && s.badgeSm]}>
      <Text style={[s.badgeTxt, { color: kolor }, male && s.badgeTxtSm]}>{ocena}</Text>
      {!male && <Text style={s.badgeSub}>{etykietaOceny(poziom)}</Text>}
    </View>
  );
}

/** Znacznik rynku — jedna litera koloru, żeby wzrok od razu dzielił listę. */
export function ZnacznikRynku({ rynek }: { rynek: string }) {
  const gpw = rynek === "GPW";
  return (
    <View style={[s.rynek, { backgroundColor: gpw ? "rgba(91,140,255,.16)" : "rgba(167,139,250,.16)" }]}>
      <Text style={[s.rynekTxt, { color: gpw ? C.accent : C.violet }]}>{rynek}</Text>
    </View>
  );
}

/** Rozwijane wyjaśnienie. Treść siedzi w drzewie od razu, tylko jest schowana —
 *  dzięki temu czytnik ekranu i wyszukiwanie w przeglądarce ją widzą. */
export function Wyjasnienie({ tytul, children }:
  { tytul: string; children: React.ReactNode }) {
  const [otwarte, setOtwarte] = useState(false);
  return (
    <View style={s.wyjWrap}>
      <Pressable
        onPress={() => {
          if (Platform.OS !== "web") {
            LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
          }
          setOtwarte((v) => !v);
        }}
        style={s.wyjBtn}
        accessibilityRole="button"
        accessibilityState={{ expanded: otwarte }}
      >
        <Text style={s.wyjIkona}>{otwarte ? "▾" : "▸"}</Text>
        <Text style={s.wyjTytul}>{tytul}</Text>
      </Pressable>
      {otwarte && <View style={s.wyjTresc}>{children}</View>}
    </View>
  );
}

export function Akapit({ children }: { children: React.ReactNode }) {
  return <Text style={s.akapit}>{children}</Text>;
}

/** Kafel z jedną liczbą — używany w podsumowaniach wszystkich zakładek. */
export function Kafel({ etykieta, wartosc, nota, kolor }:
  { etykieta: string; wartosc: string; nota?: string; kolor?: string }) {
  return (
    <View style={s.kafel}>
      <Text style={s.kafelEt}>{etykieta}</Text>
      <Text style={[s.kafelW, kolor ? { color: kolor } : null]} numberOfLines={1}>{wartosc}</Text>
      {!!nota && <Text style={s.kafelN}>{nota}</Text>}
    </View>
  );
}

/** Pigułka filtru — włączona/wyłączona. */
export function Pigulka({ tekst, aktywna, onPress }:
  { tekst: string; aktywna: boolean; onPress: () => void }) {
  return (
    <Pressable onPress={onPress}
               style={[s.pill, aktywna && { borderColor: C.green, backgroundColor: C.greenDim }]}>
      <Text style={[s.pillTxt, aktywna && { color: C.green }]}>{tekst}</Text>
    </Pressable>
  );
}

/* ---------- formatowanie ---------- */

export const proc = (v: number | null | undefined, znak = false): string =>
  v === null || v === undefined || Number.isNaN(v)
    ? "—"
    : `${znak && v > 0 ? "+" : ""}${v.toFixed(2).replace(".", ",")}%`;

export const pln = (v: number | null | undefined, waluta = "zł"): string =>
  v === null || v === undefined || Number.isNaN(v)
    ? "—"
    : `${Math.round(v).toLocaleString("pl-PL")} ${waluta}`;

export const kwota2 = (v: number | null | undefined, waluta = ""): string =>
  v === null || v === undefined || Number.isNaN(v)
    ? "—"
    : `${v.toFixed(2).replace(".", ",")}${waluta ? ` ${waluta}` : ""}`;

const MIESIACE = ["stycznia", "lutego", "marca", "kwietnia", "maja", "czerwca",
                  "lipca", "sierpnia", "września", "października", "listopada", "grudnia"];
const MIESIACE_M = ["styczeń", "luty", "marzec", "kwiecień", "maj", "czerwiec",
                    "lipiec", "sierpień", "wrzesień", "październik", "listopad", "grudzień"];

export function dataPl(iso?: string): string {
  if (!iso || iso.length < 10) return "—";
  const [r, m, d] = iso.slice(0, 10).split("-");
  const mi = Number(m) - 1;
  if (mi < 0 || mi > 11) return iso;
  return `${Number(d)} ${MIESIACE[mi]} ${r}`;
}

export function miesiacPl(ym: string): string {
  const [r, m] = ym.split("-");
  const mi = Number(m) - 1;
  if (mi < 0 || mi > 11) return ym;
  return `${MIESIACE_M[mi]} ${r}`;
}

export function miesiacKrotki(nr: number): string {
  return ["sty", "lut", "mar", "kwi", "maj", "cze",
          "lip", "sie", "wrz", "paź", "lis", "gru"][nr - 1] || "";
}

export function zaIleDni(dni: number | null | undefined): string {
  if (dni === null || dni === undefined) return "";
  if (dni === 0) return "dziś";
  if (dni === 1) return "jutro";
  if (dni < 0) return "minęło";
  return `za ${dni} dni`;
}

const s = StyleSheet.create({
  badge: {
    minWidth: 46, paddingHorizontal: 7, paddingVertical: 4, borderRadius: 9,
    borderWidth: 1, alignItems: "center", justifyContent: "center",
  },
  badgeSm: { minWidth: 32, paddingVertical: 2, paddingHorizontal: 5, borderRadius: 7 },
  badgeTxt: { ...T.body, fontSize: 16, fontWeight: "800" },
  badgeTxtSm: { fontSize: 12 },
  badgeSub: { ...T.micro, color: C.dim, fontSize: 9, marginTop: 1 },
  rynek: { paddingHorizontal: 6, paddingVertical: 2, borderRadius: 6 },
  rynekTxt: { ...T.micro, fontSize: 10, fontWeight: "800", letterSpacing: 0.4 },

  wyjWrap: { marginTop: 10, borderTopWidth: 1, borderTopColor: C.border, paddingTop: 9 },
  wyjBtn: { flexDirection: "row", alignItems: "center", gap: 7 },
  wyjIkona: { color: C.green, fontSize: 12, width: 12 },
  wyjTytul: { ...T.small, color: C.green, fontWeight: "700", flex: 1 },
  wyjTresc: { marginTop: 8, gap: 8, paddingLeft: 19 },
  akapit: { ...T.small, color: C.muted, lineHeight: 19 },

  kafel: {
    // `maxWidth` jest tu istotne, nie kosmetyczne: bez niego cztery kafle
    // w oknie o szerokości 2000 px rozciągały się po 480 px każdy i etykieta
    // z liczbą pływały samotnie w pustym prostokącie.
    flexGrow: 1, flexBasis: 150, maxWidth: 280,
    backgroundColor: C.card, borderRadius: 12,
    borderWidth: 1, borderColor: C.border, padding: 11,
  },
  kafelEt: { ...T.micro, color: C.dim, textTransform: "uppercase", letterSpacing: 0.5 },
  kafelW: { ...T.body, color: C.text, fontSize: 19, fontWeight: "800", marginTop: 3 },
  kafelN: { ...T.micro, color: C.muted, marginTop: 2 },

  pill: {
    paddingHorizontal: 11, paddingVertical: 7, borderRadius: 999,
    borderWidth: 1, borderColor: C.border2, backgroundColor: C.card,
  },
  pillTxt: { ...T.small, color: C.muted, fontWeight: "600" },
});
