/** Enkoder kodów QR — czysta arytmetyka, bez Reacta i bez zależności.
 *
 *  Zakres CELOWO ograniczony: tryb bajtowy, poziom korekcji M, wersje 1–6.
 *  Wersja 6 mieści 108 bajtów danych, czyli adres wielokrotnie dłuższy niż
 *  „https://www.portevo.pl". Od wersji 7 doszedłby jeszcze blok informacji
 *  o wersji, którego przy tej długości nie ma po co pisać.
 *
 *  Dlaczego własna implementacja zamiast paczki z npm: kod QR jest potrzebny
 *  w jednym miejscu (sekcja „Aplikacja"), zawsze dla krótkiego adresu własnego
 *  serwisu. Najpopularniejsze paczki ciągną za sobą zależności natywne albo
 *  `canvas`, którego wersja webowa i telefonowa zachowują się inaczej — a ten
 *  sam kod ma śmigać w obu.
 *
 *  Plik jest osobno od komponentu WYŁĄCZNIE po to, żeby dało się go sprawdzić:
 *  bez importów Reacta wynik `macierzQr` porównuje się wprost z macierzą
 *  z niezależnej implementacji. Błędny kod QR wygląda jak poprawny, więc jedyną
 *  metodą na zaufanie mu jest przepuszczenie go przez prawdziwy czytnik.
 *  Sprawdzone tak: 313 losowych napisów ASCII we wszystkich wersjach 1–6,
 *  wszystkie odczytane bajt w bajt (zbar). Kolejność wypełniania i mapa modułów
 *  funkcyjnych zgadzają się z `segno`, a punktacja masek — z regułami normy.
 *
 *  ZNANE OGRANICZENIE: nie wstawiamy nagłówka ECI, więc treść spoza ASCII
 *  czytnik interpretuje po swojemu i polskie znaki potrafią wrócić przekręcone.
 *  Dla adresów URL, czyli jedynego zastosowania w tej aplikacji, nie ma to
 *  znaczenia — ale nie koduj tu zdań po polsku licząc, że wrócą w całości.
 */

/* ---------------------------------------------------------------- GF(256) */

// Ciało skończone o 256 elementach z wielomianem 0x11D — tak zdefiniowany jest
// arytmetyczny grunt pod kody Reeda–Solomona w normie QR.
const EXP = new Uint8Array(512);
const LOG = new Uint8Array(256);
{
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
}

const mul = (a: number, b: number) => (a === 0 || b === 0 ? 0 : EXP[LOG[a] + LOG[b]]);

/** Wielomian generujący stopnia `n`, współczynniki od najwyższej potęgi. */
function generator(n: number): number[] {
  let g = [1];
  for (let i = 0; i < n; i++) {
    const next = new Array(g.length + 1).fill(0);
    for (let j = 0; j < g.length; j++) {
      next[j] ^= g[j];                       // składnik po przemnożeniu przez x
      next[j + 1] ^= mul(g[j], EXP[i]);      // składnik po przemnożeniu przez α^i
    }
    g = next;
  }
  return g;
}

/** Bajty korekcji błędów dla jednego bloku danych. */
function korekcja(dane: number[], ile: number): number[] {
  const g = generator(ile);
  const reszta = new Array(ile).fill(0);
  for (const bajt of dane) {
    const czynnik = bajt ^ reszta[0];
    reszta.shift();
    reszta.push(0);
    if (czynnik !== 0) {
      for (let i = 0; i < ile; i++) reszta[i] ^= mul(g[i + 1], czynnik);
    }
  }
  return reszta;
}

/* ------------------------------------------------------- tablice z normy */

/** Wszystkie bajty (dane + korekcja) w wersjach 1–6. */
const RAZEM = [26, 44, 70, 100, 134, 172];
/** Bajty korekcji na blok, poziom M. */
const EC_NA_BLOK = [10, 16, 26, 18, 24, 16];
/** Liczba bloków, poziom M. */
const BLOKI = [1, 1, 1, 2, 2, 4];
/** Środki wzorów wyrównujących. Wersja 1 ich nie ma. */
const WYROWNANIE: number[][] = [[], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34]];

/* ------------------------------------------------------------ kodowanie */

/** Strumień bitów zapisywany bit po bicie. */
class Bity {
  bits: number[] = [];
  dopisz(wartosc: number, dlugosc: number) {
    for (let i = dlugosc - 1; i >= 0; i--) this.bits.push((wartosc >> i) & 1);
  }
}

/** Bajty danych gotowe do podziału na bloki, albo `null` gdy tekst za długi. */
function zakoduj(tekst: string, wersja: number): number[] | null {
  const bajty = Array.from(new TextEncoder().encode(tekst));
  const pojemnosc = RAZEM[wersja - 1] - EC_NA_BLOK[wersja - 1] * BLOKI[wersja - 1];
  // 4 bity trybu + 8 bitów długości = 1,5 bajta narzutu (wersje 1–9)
  if (bajty.length + 2 > pojemnosc) return null;

  const b = new Bity();
  b.dopisz(0b0100, 4);            // tryb bajtowy
  b.dopisz(bajty.length, 8);      // licznik znaków
  for (const bajt of bajty) b.dopisz(bajt, 8);

  const maks = pojemnosc * 8;
  b.dopisz(0, Math.min(4, maks - b.bits.length));       // terminator
  while (b.bits.length % 8 !== 0) b.bits.push(0);       // wyrównanie do bajtu

  const out: number[] = [];
  for (let i = 0; i < b.bits.length; i += 8) {
    let v = 0;
    for (let j = 0; j < 8; j++) v = (v << 1) | b.bits[i + j];
    out.push(v);
  }
  // Wypełniacze z normy, na przemian, aż do pełnej pojemności.
  for (let i = 0; out.length < pojemnosc; i++) out.push(i % 2 === 0 ? 0xec : 0x11);
  return out;
}

/** Dane i korekcja poprzeplatane blokami — tak wymaga norma. */
function przeplec(dane: number[], wersja: number): number[] {
  const bloki = BLOKI[wersja - 1];
  const ec = EC_NA_BLOK[wersja - 1];
  const krotki = Math.floor(dane.length / bloki);
  const dlugich = dane.length % bloki;

  const czesciD: number[][] = [];
  const czesciE: number[][] = [];
  let poz = 0;
  for (let i = 0; i < bloki; i++) {
    const len = krotki + (i >= bloki - dlugich ? 1 : 0);
    const kawalek = dane.slice(poz, poz + len);
    poz += len;
    czesciD.push(kawalek);
    czesciE.push(korekcja(kawalek, ec));
  }

  const out: number[] = [];
  for (let i = 0; i < krotki + 1; i++) {
    for (const c of czesciD) if (i < c.length) out.push(c[i]);
  }
  for (let i = 0; i < ec; i++) {
    for (const c of czesciE) out.push(c[i]);
  }
  return out;
}

/* -------------------------------------------------------------- macierz */

type Siatka = { rozmiar: number; ciemne: Uint8Array; stale: Uint8Array };

const idx = (g: Siatka, x: number, y: number) => y * g.rozmiar + x;

function ustaw(g: Siatka, x: number, y: number, ciemny: boolean, stale = true) {
  if (x < 0 || y < 0 || x >= g.rozmiar || y >= g.rozmiar) return;
  g.ciemne[idx(g, x, y)] = ciemny ? 1 : 0;
  if (stale) g.stale[idx(g, x, y)] = 1;
}

/** Wzory rozpoznawcze, wyrównujące, taktujące i pola zarezerwowane. */
function szkielet(wersja: number): Siatka {
  const rozmiar = 17 + 4 * wersja;
  const g: Siatka = {
    rozmiar,
    ciemne: new Uint8Array(rozmiar * rozmiar),
    stale: new Uint8Array(rozmiar * rozmiar),
  };

  const oko = (ox: number, oy: number) => {
    for (let dy = -1; dy <= 7; dy++) {
      for (let dx = -1; dx <= 7; dx++) {
        const x = ox + dx;
        const y = oy + dy;
        if (x < 0 || y < 0 || x >= rozmiar || y >= rozmiar) continue;
        const brzeg = Math.max(Math.abs(dx - 3), Math.abs(dy - 3));
        ustaw(g, x, y, brzeg !== 2 && brzeg <= 3);
      }
    }
  };
  oko(0, 0);
  oko(rozmiar - 7, 0);
  oko(0, rozmiar - 7);

  for (let i = 8; i < rozmiar - 8; i++) {
    ustaw(g, i, 6, i % 2 === 0);
    ustaw(g, 6, i, i % 2 === 0);
  }

  const srodki = WYROWNANIE[wersja - 1];
  for (const cy of srodki) {
    for (const cx of srodki) {
      // Rogi zajmują wzory rozpoznawcze — tam wyrównania nie ma.
      const rog = (cx === 6 && cy === 6)
        || (cx === 6 && cy === rozmiar - 7) || (cx === rozmiar - 7 && cy === 6);
      if (rog) continue;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          ustaw(g, cx + dx, cy + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
        }
      }
    }
  }

  // Moduł zawsze ciemny — wymóg normy.
  ustaw(g, 8, rozmiar - 8, true);

  // Rezerwacja miejsca na informację o formacie (wypełnimy ją na końcu).
  // Ósmy wiersz i ósma kolumna przecinają wzory taktujące w (8,6) i (6,8) —
  // te dwa moduły NIE należą do pola formatu i muszą zachować swój kolor.
  // Zamazane sprawiają, że czytnik gubi siatkę: kod nadal wygląda poprawnie,
  // a w wersji 1, gdzie nie ma wzorów wyrównujących, przestaje się skanować.
  for (let i = 0; i < 9; i++) {
    if (i === 6) continue;
    ustaw(g, i, 8, false);
    ustaw(g, 8, i, false);
  }
  for (let i = 0; i < 8; i++) {
    ustaw(g, rozmiar - 1 - i, 8, false);
    ustaw(g, 8, rozmiar - 1 - i, false);
  }
  ustaw(g, 8, rozmiar - 8, true);
  return g;
}

/** Wąż danych: dwie kolumny naraz, od prawego dolnego rogu w górę i w dół. */
function wypelnij(g: Siatka, bajty: number[]) {
  let bit = 0;
  const czytaj = () => {
    const b = bit < bajty.length * 8
      ? (bajty[bit >> 3] >> (7 - (bit & 7))) & 1
      : 0;
    bit++;
    return b === 1;
  };

  let wGore = true;
  for (let prawa = g.rozmiar - 1; prawa >= 1; prawa -= 2) {
    if (prawa === 6) prawa = 5;   // kolumna taktująca nie liczy się do węża
    for (let i = 0; i < g.rozmiar; i++) {
      const y = wGore ? g.rozmiar - 1 - i : i;
      for (let d = 0; d < 2; d++) {
        const x = prawa - d;
        if (g.stale[idx(g, x, y)]) continue;
        g.ciemne[idx(g, x, y)] = czytaj() ? 1 : 0;
      }
    }
    wGore = !wGore;
  }
}

const MASKI: ((x: number, y: number) => boolean)[] = [
  (x, y) => (x + y) % 2 === 0,
  (_x, y) => y % 2 === 0,
  (x) => x % 3 === 0,
  (x, y) => (x + y) % 3 === 0,
  (x, y) => (Math.floor(y / 2) + Math.floor(x / 3)) % 2 === 0,
  (x, y) => ((x * y) % 2) + ((x * y) % 3) === 0,
  (x, y) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0,
  (x, y) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0,
];

function nalozMaske(g: Siatka, maska: number) {
  const f = MASKI[maska];
  for (let y = 0; y < g.rozmiar; y++) {
    for (let x = 0; x < g.rozmiar; x++) {
      if (g.stale[idx(g, x, y)]) continue;
      if (f(x, y)) g.ciemne[idx(g, x, y)] ^= 1;
    }
  }
}

/** Kara za czytelność — norma każe wybrać maskę o najniższym wyniku. */
function kara(g: Siatka): number {
  const n = g.rozmiar;
  const ciemny = (x: number, y: number) => g.ciemne[idx(g, x, y)] === 1;
  let suma = 0;

  // Reguła 1: serie pięciu i więcej modułów tego samego koloru.
  for (let i = 0; i < n; i++) {
    for (const wiersz of [true, false]) {
      let dlugosc = 1;
      let poprzedni = wiersz ? ciemny(0, i) : ciemny(i, 0);
      for (let j = 1; j < n; j++) {
        const teraz = wiersz ? ciemny(j, i) : ciemny(i, j);
        if (teraz === poprzedni) {
          dlugosc++;
        } else {
          if (dlugosc >= 5) suma += 3 + (dlugosc - 5);
          dlugosc = 1;
          poprzedni = teraz;
        }
      }
      if (dlugosc >= 5) suma += 3 + (dlugosc - 5);
    }
  }

  // Reguła 2: jednolite kwadraty 2×2.
  for (let y = 0; y < n - 1; y++) {
    for (let x = 0; x < n - 1; x++) {
      const a = ciemny(x, y);
      if (a === ciemny(x + 1, y) && a === ciemny(x, y + 1) && a === ciemny(x + 1, y + 1)) {
        suma += 3;
      }
    }
  }

  // Reguła 3: układ przypominający wzór rozpoznawczy (1:1:3:1:1 z jasnym marginesem).
  const WZOR = [true, false, true, true, true, false, true, false, false, false, false];
  const ODWROTNY = [...WZOR].reverse();
  const pasuje = (pobierz: (k: number) => boolean, start: number, wzor: boolean[]) => {
    for (let k = 0; k < wzor.length; k++) if (pobierz(start + k) !== wzor[k]) return false;
    return true;
  };
  for (let i = 0; i < n; i++) {
    for (let j = 0; j + 11 <= n; j++) {
      const wiersz = (k: number) => ciemny(k, i);
      const kolumna = (k: number) => ciemny(i, k);
      if (pasuje(wiersz, j, WZOR) || pasuje(wiersz, j, ODWROTNY)) suma += 40;
      if (pasuje(kolumna, j, WZOR) || pasuje(kolumna, j, ODWROTNY)) suma += 40;
    }
  }

  // Reguła 4: odchylenie udziału modułów ciemnych od połowy.
  let ciemnych = 0;
  for (let i = 0; i < g.ciemne.length; i++) ciemnych += g.ciemne[i];
  const procent = (ciemnych * 100) / (n * n);
  suma += Math.floor(Math.abs(procent - 50) / 5) * 10;
  return suma;
}

/** 15 bitów informacji o formacie: poziom korekcji M i numer maski. */
function informacjaOFormacie(g: Siatka, maska: number) {
  const dane = (0b00 << 3) | maska;          // 00 = poziom M
  let reszta = dane;
  for (let i = 0; i < 10; i++) {
    reszta = (reszta << 1) ^ ((reszta >> 9) * 0x537);
  }
  const bity = ((dane << 10) | reszta) ^ 0x5412;
  const n = g.rozmiar;

  const bit = (i: number) => ((bity >> i) & 1) === 1;
  // Kopia pierwsza — wokół lewego górnego wzoru rozpoznawczego.
  for (let i = 0; i <= 5; i++) ustaw(g, 8, i, bit(i));
  ustaw(g, 8, 7, bit(6));
  ustaw(g, 8, 8, bit(7));
  ustaw(g, 7, 8, bit(8));
  for (let i = 9; i < 15; i++) ustaw(g, 14 - i, 8, bit(i));

  // Kopia druga — rozdzielona między dwa pozostałe rogi.
  for (let i = 0; i < 8; i++) ustaw(g, n - 1 - i, 8, bit(i));
  for (let i = 8; i < 15; i++) ustaw(g, 8, n - 15 + i, bit(i));
  ustaw(g, 8, n - 8, true);
}

/** Macierz modułów dla tekstu, albo `null` gdy się nie mieści w wersji 6. */
export function macierzQr(tekst: string): boolean[][] | null {
  for (let wersja = 1; wersja <= 6; wersja++) {
    const dane = zakoduj(tekst, wersja);
    if (!dane) continue;

    const bajty = przeplec(dane, wersja);
    let najlepsza: Siatka | null = null;
    let najlepszyWynik = Infinity;

    for (let maska = 0; maska < 8; maska++) {
      const g = szkielet(wersja);
      wypelnij(g, bajty);
      nalozMaske(g, maska);
      informacjaOFormacie(g, maska);
      const wynik = kara(g);
      if (wynik < najlepszyWynik) {
        najlepszyWynik = wynik;
        najlepsza = g;
      }
    }
    if (!najlepsza) return null;

    const out: boolean[][] = [];
    for (let y = 0; y < najlepsza.rozmiar; y++) {
      const wiersz: boolean[] = [];
      for (let x = 0; x < najlepsza.rozmiar; x++) {
        wiersz.push(najlepsza.ciemne[idx(najlepsza, x, y)] === 1);
      }
      out.push(wiersz);
    }
    return out;
  }
  return null;
}
