/** Twarze insiderów nałożone na wykres — warstwa nad SVG, liczona przez `PortfolioChart`.
 *
 *  Dlaczego zwykłe widoki, a nie `<Image>` wewnątrz SVG: zdjęcie w SVG trzeba
 *  przyciąć ścieżką (`clipPath`), a stałe identyfikatory ścieżek w przeglądarce
 *  kradną sobie wykresy nawzajem (patrz `svgIds.ts`). Widok z `borderRadius`
 *  przycina się sam, obsługuje dotyk przez `Pressable` i wygląda tak samo na
 *  telefonie i w przeglądarce. W SVG zostaje tylko to, co należy do wykresu:
 *  kropka w miejscu ceny i trzonek do twarzy — przycięte do pola wykresu razem
 *  z linią notowań.
 *
 *  Kilka transakcji w jednym miejscu to jedna twarz z plakietką „+2". Twarz
 *  grupy to najważniejsza osoba w niej (katalog ważności, potem kwota), bo
 *  z trzech nakładających się zdjęć i tak widać by było tylko jedno.
 */
import React from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import { Avatar } from "../screens/tools/insiders/shared";
import { C } from "../theme";

export type FaceMark = {
  key: string;
  /** dzień transakcji RRRR-MM-DD */
  date: string;
  /** cena transakcji; brak = kurs z wykresu tego dnia */
  price: number | null;
  side: "buy" | "sell";
  photo?: string;
  blur?: string;
  /** jedno słowo pod twarzą: nazwisko albo funkcja */
  label: string;
  /** zamazana — widok bez premium */
  locked?: boolean;
  /** kto wygrywa miejsce w grupie: im więcej, tym ważniejszy */
  weight?: number;
  /** czyja to transakcja — do limitu twarzy jednej osoby na wykresie */
  who?: string;
  /** cokolwiek, co ekran nadrzędny chce dostać z powrotem po dotknięciu */
  ref?: any;
};

/** Grupa twarzy już ustawiona na ekranie. */
export type FaceGroup = {
  key: string;
  x: number;
  /** punkt ceny, do którego prowadzi trzonek */
  py: number;
  /** środek twarzy */
  cy: number;
  side: "buy" | "sell";
  marks: FaceMark[];
  lead: FaceMark;
  showLabel: boolean;
};

export const FACE = 28;

export default function ChartFaces({
  groups, dim, onPress, delayBase = 0,
}: {
  groups: FaceGroup[];
  /** trwa odczyt kursorem — twarze przygasają, żeby nie zasłaniały dymka */
  dim?: boolean;
  onPress?: (marks: FaceMark[]) => void;
  delayBase?: number;
}) {
  return (
    <>
      {groups.map((g, i) => {
        const lead = g.lead;
        return (
          <View key={g.key} pointerEvents="box-none"
                style={[s.slot, { left: g.x - 34, top: g.cy - FACE / 2, opacity: dim ? 0.35 : 1 }]}>
            <Pressable onPress={() => onPress?.(g.marks)} hitSlop={8}
                       accessibilityRole="button"
                       accessibilityLabel={lead.locked ? "Transakcja insidera — szczegóły w premium"
                         : `${lead.label}: ${g.side === "buy" ? "kupno" : "sprzedaż"}`}
                       style={({ pressed }) => [s.hit, pressed && { transform: [{ scale: 0.92 }] }]}>
              <Avatar person={{ photo: lead.photo || "", blur: lead.blur || "", name: lead.label }}
                      size={FACE} ring={g.side === "buy" ? "buy" : "sell"} locked={lead.locked}
                      pop delay={delayBase + Math.min(i, 12) * 45} />
              {g.marks.length > 1 && (
                <View style={[s.badge, g.side === "buy" ? s.badgeBuy : s.badgeSell]}>
                  <Text style={s.badgeTxt}>+{g.marks.length - 1}</Text>
                </View>
              )}
            </Pressable>
            {g.showLabel && (
              <Text numberOfLines={1}
                    style={[s.label, { color: g.side === "buy" ? "#bff3dc" : "#ffc9cf" }]}>
                {lead.locked ? "Insajder" : lead.label}
              </Text>
            )}
          </View>
        );
      })}
    </>
  );
}

const s = StyleSheet.create({
  slot: { position: "absolute", width: 68, alignItems: "center" },
  hit: { width: FACE, height: FACE },
  badge: {
    position: "absolute", right: -7, top: -5, minWidth: 17, height: 15, borderRadius: 8,
    paddingHorizontal: 3, alignItems: "center", justifyContent: "center",
    borderWidth: 1.5, borderColor: C.bg,
  },
  badgeBuy: { backgroundColor: C.green },
  badgeSell: { backgroundColor: C.red },
  badgeTxt: { color: "#07120c", fontSize: 8.5, fontWeight: "800" },
  // podpis zawsze POD twarzą — twarz stoi na tyle wysoko nad ceną, że napis
  // mieści się między nią a kropką i działa jak etykieta szpilki
  label: {
    position: "absolute", top: FACE + 1, left: 0, right: 0, fontSize: 9, fontWeight: "800", letterSpacing: 0.1,
    textAlign: "center", textShadowColor: "rgba(0,0,0,.85)", textShadowRadius: 3,
    textShadowOffset: { width: 0, height: 1 },
  },
});
