/** Pole kodu polecającego — jedno na trzy miejsca: logowanie, „Więcej" i zakup premium.
 *
 *  Trzy miejsca, bo każde łapie inną osobę:
 *  * `signup` — ktoś przyszedł z filmu i zakłada konto. Pole stoi NAD przyciskiem
 *    Google, bo tam formularza nie ma: kod zapisuje się na urządzeniu od razu przy
 *    wpisywaniu, a konto dostaje go po powrocie z Google (`referral.ts`);
 *  * `more` — konto już jest, a o kodzie przypomniał sobie później;
 *  * `paywall` — ostatnia chwila: po zakupie serwer kodu już nie przyjmie
 *    (inaczej twórcy zbieraliby prowizję od klientów, których nie przyprowadzili).
 *
 *  O darmowym premium od twórcy mówimy WYŁĄCZNIE w przeglądarce (`REWARD_HERE`).
 *  W aplikacji ze sklepu kod tylko przypisuje konto — odblokowanie premium kodem
 *  wpisanym w aplikacji to wprost wytyczna Apple 3.1.1 i odrzucenie wydania.
 *
 *  Wygląd: „bilet" z obwódką, po której krąży światło. Stan widać po kolorze
 *  obwódki (bursztyn = czeka na kod, zielony = kod rozpoznany/przypisany,
 *  czerwony = błąd), a każda zmiana stanu ma własny, krótki ruch: puls ikony,
 *  wyskok ptaszka, iskry po przypisaniu, potrząśnięcie przy błędzie. Wszystko na
 *  `Animated` z transformacjami — działa tak samo na telefonie i w przeglądarce.
 */
import { LinearGradient } from "expo-linear-gradient";
import React, { useEffect, useRef, useState } from "react";
import {
  ActivityIndicator, Animated, Easing, Platform, Pressable, StyleSheet, Text, TextInput, View,
} from "react-native";
import {
  applyReferral, checkReferral, getMyReferral, LoginRequired, ReferralCheck, ReferralMine,
} from "../api";
import { useAuth } from "../auth/AuthContext";
import {
  cleanCode, getPendingReferral, REWARD_HERE, referralPlatform, setPendingReferral,
  subscribeReferral,
} from "../referral";
import { C } from "../theme";
import { MetalButton, SectionTitle } from "../ui";
import Icon from "../ui/Icon";

type Msg = { tone: "ok" | "err" | "info"; text: string } | null;
type Ton = "idle" | "ok" | "err";

const ND = Platform.OS !== "web";         // natywny sterownik animacji tylko tam, gdzie istnieje

/** Zdanie o puli darmowego premium — tylko tam, gdzie wolno je wypowiedzieć. */
function rewardInfo(c: { free_days?: number; slots_left?: number }) {
  if (!REWARD_HERE || !c.free_days || !c.slots_left) return null;
  return { days: c.free_days, left: c.slots_left };
}

/* ======================================================================= efekty */

/** Obwódka z krążącym światłem. Blask to szeroki, pochylony pas przesuwany pod
 *  kartą — widać go tylko na półtorapikselowym brzegu, więc wygląda jak światło
 *  biegnące po krawędzi. */
function GlowBorder({ ton, children, style }: { ton: Ton; children: React.ReactNode; style?: any }) {
  const bieg = useRef(new Animated.Value(0)).current;
  const [w, setW] = useState(0);
  useEffect(() => {
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(bieg, { toValue: 1, duration: 2600, easing: Easing.inOut(Easing.quad), useNativeDriver: ND }),
      Animated.delay(900),
      Animated.timing(bieg, { toValue: 0, duration: 0, useNativeDriver: ND }),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);
  const kolory: Record<Ton, [string, string, string]> = {
    idle: ["rgba(255,180,84,.75)", "rgba(91,140,255,.35)", "rgba(255,180,84,.45)"],
    ok: ["rgba(47,212,138,.9)", "rgba(47,212,138,.3)", "rgba(47,212,138,.7)"],
    err: ["rgba(255,92,108,.85)", "rgba(255,92,108,.25)", "rgba(255,92,108,.6)"],
  };
  return (
    <View style={[s.edge, style]} onLayout={(e) => setW(e.nativeEvent.layout.width)}>
      <LinearGradient colors={kolory[ton]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
                      style={StyleSheet.absoluteFill} />
      <Animated.View pointerEvents="none" style={[s.sheen, {
        transform: [
          { translateX: bieg.interpolate({ inputRange: [0, 1], outputRange: [-160, Math.max(w, 300) + 160] }) },
          { rotate: "20deg" },
        ],
      }]} />
      <View style={s.face}>{children}</View>
    </View>
  );
}

/** Ikona w złotej plakietce, która delikatnie oddycha, dopóki czeka na kod. */
function Badge({ ton }: { ton: Ton }) {
  const oddech = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (ton !== "idle") { oddech.setValue(0); return; }
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(oddech, { toValue: 1, duration: 1100, easing: Easing.inOut(Easing.sin), useNativeDriver: ND }),
      Animated.timing(oddech, { toValue: 0, duration: 1100, easing: Easing.inOut(Easing.sin), useNativeDriver: ND }),
    ]));
    loop.start();
    return () => loop.stop();
  }, [ton]);
  const zielony = ton === "ok";
  return (
    <Animated.View style={{ transform: [{ scale: oddech.interpolate({ inputRange: [0, 1], outputRange: [1, 1.08] }) }] }}>
      <LinearGradient colors={zielony ? ["#4be3a0", "#1c9e63"] : [C.gold, C.goldDeep]}
                      start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={s.badge}>
        <Icon name={zielony ? "ptaszek" : "serce"} size={17} color={zielony ? "#03170d" : "#2a1e05"} />
      </LinearGradient>
    </Animated.View>
  );
}

/** Ptaszek, który wyskakuje sprężyście, gdy kod okaże się prawdziwy. */
function PopCheck({ ok }: { ok: boolean }) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (ok) {
      a.setValue(0);
      Animated.spring(a, { toValue: 1, speed: 14, bounciness: 14, useNativeDriver: ND }).start();
    } else a.setValue(0);
  }, [ok]);
  if (!ok) return null;
  return (
    <Animated.View style={[s.popCheck, { opacity: a, transform: [{ scale: a }, {
      rotate: a.interpolate({ inputRange: [0, 1], outputRange: ["-40deg", "0deg"] }) }] }]}>
      <Icon name="ptaszek" size={13} color="#03170d" />
    </Animated.View>
  );
}

const ISKRY = [C.green, C.gold, C.accent, C.amber, "#ffffff", C.green, C.violet, C.gold,
               C.green, C.accent, C.amber, "#ffffff", C.gold, C.green];

/** Iskry rozbiegające się z plakietki po udanym przypisaniu — raz, na każdą zmianę `klucz`. */
function Burst({ klucz }: { klucz: number }) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (!klucz) return;
    a.setValue(0);
    Animated.timing(a, { toValue: 1, duration: 900, easing: Easing.out(Easing.cubic), useNativeDriver: ND }).start();
  }, [klucz]);
  if (!klucz) return null;
  return (
    <View pointerEvents="none" style={s.burst}>
      {ISKRY.map((kolor, i) => {
        const kat = (i / ISKRY.length) * Math.PI * 2;
        const dal = 34 + (i % 3) * 16;
        return (
          <Animated.View key={i} style={[s.iskra, {
            backgroundColor: kolor,
            opacity: a.interpolate({ inputRange: [0, 0.15, 1], outputRange: [0, 1, 0] }),
            transform: [
              { translateX: a.interpolate({ inputRange: [0, 1], outputRange: [0, Math.cos(kat) * dal] }) },
              { translateY: a.interpolate({ inputRange: [0, 1], outputRange: [0, Math.sin(kat) * dal] }) },
              { scale: a.interpolate({ inputRange: [0, 1], outputRange: [1.2, 0.3] }) },
            ],
          }]} />
        );
      })}
    </View>
  );
}

/** Rozwijana treść: wjeżdża z góry z przygaszenia. */
function Rozwin({ open, children }: { open: boolean; children: React.ReactNode }) {
  const a = useRef(new Animated.Value(open ? 1 : 0)).current;
  useEffect(() => {
    Animated.timing(a, { toValue: open ? 1 : 0, duration: 280, easing: Easing.out(Easing.cubic), useNativeDriver: ND }).start();
  }, [open]);
  if (!open) return null;
  return (
    <Animated.View style={{ opacity: a, transform: [{ translateY: a.interpolate({ inputRange: [0, 1], outputRange: [-8, 0] }) }] }}>
      {children}
    </Animated.View>
  );
}

/** Krótkie, gasnące potrząśnięcie — sygnał „nie ten kod". */
function useShake() {
  const x = useRef(new Animated.Value(0)).current;
  const shake = () => {
    x.setValue(0);
    Animated.sequence([10, -8, 6, -4, 0].map((v) =>
      Animated.timing(x, { toValue: v, duration: 55, useNativeDriver: ND }))).start();
  };
  return { style: { transform: [{ translateX: x }] }, shake };
}

/** Karta twórcy, która wsuwa się pod pole, gdy kod jest rozpoznany. */
function CreatorChip({ creator, handle, reward }: {
  creator: string; handle?: string; reward: { days: number; left: number } | null;
}) {
  const a = useRef(new Animated.Value(0)).current;
  const blysk = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.spring(a, { toValue: 1, speed: 16, bounciness: 8, useNativeDriver: ND }).start();
    if (!reward) return;
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(blysk, { toValue: 1, duration: 1800, easing: Easing.inOut(Easing.quad), useNativeDriver: ND }),
      Animated.delay(1400),
      Animated.timing(blysk, { toValue: 0, duration: 0, useNativeDriver: ND }),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);
  const inicjaly = (creator || "?").split(/\s+/).map((w) => w[0]).join("").slice(0, 2).toUpperCase();
  return (
    <Animated.View style={{ opacity: a, transform: [{ translateY: a.interpolate({ inputRange: [0, 1], outputRange: [10, 0] }) }] }}>
      <View style={s.chip}>
        <LinearGradient colors={[C.accent, C.violet]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={s.avatar}>
          <Text style={s.avatarTxt}>{inicjaly}</Text>
        </LinearGradient>
        <View style={{ flex: 1 }}>
          <Text style={s.chipName} numberOfLines={1}>{creator}</Text>
          <Text style={s.chipSub} numberOfLines={1}>{handle ? `${handle} · ` : ""}kod twórcy rozpoznany</Text>
        </View>
      </View>
      {reward && (
        <View style={s.reward}>
          <Animated.View pointerEvents="none" style={[s.rewardShine, { transform: [
            { translateX: blysk.interpolate({ inputRange: [0, 1], outputRange: [-120, 420] }) }, { rotate: "20deg" }] }]} />
          <Icon name="premium" size={14} color={C.gold} />
          <Text style={s.rewardTxt}>
            {reward.days} dni premium za darmo · zostało miejsc: {reward.left}
          </Text>
        </View>
      )}
    </Animated.View>
  );
}

/* =================================================================== komponent */

export default function ReferralCodeBox({
  place, onNeedLogin, startOpen,
}: {
  place: "signup" | "more" | "paywall";
  /** paywall zamyka się przed otwarciem logowania — dlatego własna droga */
  onNeedLogin?: () => void;
  /** rozwinięte od razu — w oknie logowania przy zakładaniu konta */
  startOpen?: boolean;
}) {
  const { user, me, premium, openLogin, reload } = useAuth();
  const logged = Boolean(user) && place !== "signup";

  const [open, setOpen] = useState(startOpen ?? place === "more");
  // przełączenie „Logowanie" → „Nowe konto" rozwija pole, ale go nie zwija
  useEffect(() => { if (startOpen) setOpen(true); }, [startOpen]);
  const [value, setValue] = useState("");
  const [focus, setFocus] = useState(false);
  const [busy, setBusy] = useState(false);
  const [checking, setChecking] = useState(false);
  const [msg, setMsg] = useState<Msg>(null);
  /** kod przypisany do konta; undefined = jeszcze nie wiemy */
  const [mine, setMine] = useState<ReferralMine | null | undefined>(undefined);
  /** kod zapamiętany na urządzeniu, zanim jest konto */
  const [pending, setPending] = useState<{ code: string; info?: ReferralCheck } | null>(null);
  /** serwer mówi, że kody jeszcze nie działają — całe pole znika */
  const [off, setOff] = useState(false);
  const [burst, setBurst] = useState(0);
  const zapytanie = useRef(0);
  const { style: shakeStyle, shake } = useShake();
  const strzalka = useRef(new Animated.Value(open ? 1 : 0)).current;
  useEffect(() => {
    Animated.timing(strzalka, { toValue: open ? 1 : 0, duration: 220, useNativeDriver: ND }).start();
  }, [open]);

  // Bez konta nie ma `/api/referral`, więc o gotowość bazy pytamy pustym sprawdzeniem.
  useEffect(() => {
    if (logged) return;
    let zyje = true;
    checkReferral("").then((r) => { if (zyje && r.off) setOff(true); }).catch(() => {});
    return () => { zyje = false; };
  }, [logged]);

  // ---- stan konta: czy kod już jest
  useEffect(() => {
    if (!logged) { setMine(null); return; }
    let zyje = true;
    getMyReferral()
      .then((r) => { if (zyje) setMine(r); })
      .catch(() => { if (zyje) setMine(null); });
    return () => { zyje = false; };
  }, [logged, user?.id]);

  // ---- kod czekający na urządzeniu (z linku twórcy albo wpisany wcześniej)
  useEffect(() => {
    const wczytaj = () => getPendingReferral().then((p) => {
      if (!p) { setPending(null); return; }
      setPending((stary) => (stary?.code === p.code ? stary : { code: p.code }));
      if (place === "signup") { setValue((v) => v || p.code); setOpen(true); }
    });
    wczytaj();
    return subscribeReferral(wczytaj);
  }, [place]);

  // przy logowaniu kod z linku ma od razu pokazać, czyj jest
  useEffect(() => {
    if (place === "signup" && pending?.code && !pending.info && value === pending.code) {
      sprawdzWTle(pending.code);
    }
  }, [pending?.code]);

  /** Sprawdzenie w trakcie pisania — z opóźnieniem i odrzuceniem spóźnionych odpowiedzi. */
  function sprawdzWTle(kod: string) {
    const nr = ++zapytanie.current;
    setChecking(true);
    checkReferral(kod).then((r) => {
      if (nr !== zapytanie.current) return;
      setChecking(false);
      if (r.off) { setOff(true); setPendingReferral("", "signup"); return; }
      if (r.ok) {
        setPending({ code: r.code || kod, info: r });
        setMsg(null);
      } else {
        setPending(null);
        setMsg({ tone: "err", text: r.message || "Nie znamy takiego kodu." });
        setPendingReferral("", "signup");
        shake();
      }
    }).catch(() => {
      if (nr === zapytanie.current) { setChecking(false); setMsg(null); }  // bez sieci serwer sprawdzi później
    });
  }

  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);

  function onChange(t: string) {
    const kod = cleanCode(t);
    setValue(kod);
    setMsg(null);
    if (place !== "signup") return;
    // W oknie logowania zapisujemy od razu: ktoś wpisze kod i od razu dotknie
    // „Kontynuuj z Google" — nie może to zależeć od osobnego przycisku.
    if (timer.current) clearTimeout(timer.current);
    setPending((p) => (p?.code === kod ? p : null));
    if (kod.length < 3) { setPendingReferral("", "signup"); zapytanie.current++; setChecking(false); return; }
    setPendingReferral(kod, "signup");
    timer.current = setTimeout(() => sprawdzWTle(kod), 550);
  }

  /** „Przypisz kod" w „Więcej" i na ekranie zakupu. */
  async function przypisz(kod = value) {
    kod = cleanCode(kod);
    if (kod.length < 3) { setMsg({ tone: "err", text: "Wpisz kod — co najmniej 3 znaki." }); shake(); return; }
    setBusy(true); setMsg(null);
    try {
      if (!user) {
        // Bez konta nie ma do czego przypisać — zapamiętujemy i prowadzimy do logowania.
        const r = await checkReferral(kod);
        if (!r.ok) { setMsg({ tone: "err", text: r.message || "Nie znamy takiego kodu." }); shake(); return; }
        await setPendingReferral(kod, place === "paywall" ? "paywall" : "more");
        setPending({ code: r.code || kod, info: r });
        setMsg({ tone: "ok", text: `Kod ${r.code} zapamiętany — przypiszemy go, gdy się zalogujesz.` });
        (onNeedLogin || openLogin)();
        return;
      }
      const r = await applyReferral(kod, place === "paywall" ? "paywall" : "more", referralPlatform());
      if (!r.ok) { setMsg({ tone: "err", text: r.message || "Nie udało się przypisać kodu." }); shake(); return; }
      setMine({ available: true, code: r.code || kod, creator: r.creator, handle: r.handle,
                reward_days: r.reward_days, can_claim: false });
      setValue("");
      setBurst((b) => b + 1);
      setMsg({
        tone: "ok",
        text: r.reward_days
          ? `Gotowe! Masz ${r.reward_days} dni premium od twórcy ${r.creator}.`
          : `Dzięki — od teraz wspierasz twórcę ${r.creator}.`,
      });
      if (r.reward_days) void reload();
    } catch (e) {
      if (e instanceof LoginRequired) (onNeedLogin || openLogin)();
      else setMsg({ tone: "err", text: "Nie udało się połączyć. Spróbuj za chwilę." });
    } finally {
      setBusy(false);
    }
  }

  /* ------------------------------------------------------------------ widoki */

  // baza kodów jeszcze nie działa (migracja nieuruchomiona) — nie pokazujemy martwego pola
  if (mine?.available === false || off) return null;

  // Konto, które już płaci, nie dopisze kodu (serwer i tak by odmówił) — w „Więcej"
  // pole byłoby tylko obietnicą bez pokrycia. Na ekranie zakupu z premium też zbędne.
  const placi = premium && (me?.source === "stripe" || me?.source === "apple");
  if (logged && mine && !mine.code && placi) return null;
  if (place === "paywall" && premium && !mine?.can_claim) return null;
  if (logged && mine === undefined) return null;          // chwila na odpowiedź serwera

  const komunikat = msg && (
    <Text style={[s.msg, msg.tone === "ok" ? s.msgOk : msg.tone === "err" ? s.msgErr : s.msgInfo]}>
      {msg.text}
    </Text>
  );

  const rozpoznany = pending?.info?.ok && pending.code === value ? pending.info : null;

  // ---- konto ma już kod: potwierdzenie, a w przeglądarce ewentualny odbiór nagrody
  if (logged && mine?.code) {
    const odbierz = REWARD_HERE && mine.can_claim && !premium;
    const tresc = (
      <GlowBorder ton="ok" style={place === "paywall" ? { marginTop: 16 } : undefined}>
        <View style={s.head}>
          <View>
            <Badge ton="ok" />
            <Burst klucz={burst} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={s.title}>Wspierasz twórcę {mine.creator || ""}</Text>
            <Text style={s.sub}>
              Kod <Text style={s.codeInline}>{mine.code}</Text> jest przypisany do Twojego konta
            </Text>
          </View>
        </View>
        {odbierz && (
          <>
            <Text style={[s.hint, { marginTop: 12 }]}>
              Twórca ma jeszcze darmowe premium dla widzów — {mine.free_days} dni, kto pierwszy, ten lepszy.
            </Text>
            <MetalButton label={busy ? "Chwila…" : `Odbierz ${mine.free_days} dni premium`}
                         tone="amber" active liquid full disabled={busy}
                         style={{ marginTop: 12 }} onPress={() => przypisz(mine.code || "")} />
          </>
        )}
        {komunikat}
      </GlowBorder>
    );
    return place === "more" ? <Sekcja>{tresc}</Sekcja> : tresc;
  }

  const ton: Ton = msg?.tone === "err" ? "err" : rozpoznany ? "ok" : "idle";

  const naglowek = (tytul: string, podtytul: string, zwijane: boolean) => (
    <Pressable onPress={zwijane ? () => setOpen((o) => !o) : undefined} style={s.head} hitSlop={4}>
      <Badge ton={ton} />
      <View style={{ flex: 1 }}>
        <Text style={s.title}>{tytul}</Text>
        <Text style={s.sub}>{podtytul}</Text>
      </View>
      {zwijane && (
        <Animated.View style={{ transform: [{ rotate: strzalka.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "90deg"] }) }] }}>
          <Text style={s.arrow}>›</Text>
        </Animated.View>
      )}
    </Pressable>
  );

  const pole = (zPrzyciskiem: boolean) => (
    <Animated.View style={[s.inputRow, shakeStyle]}>
      <View style={[s.inputWrap, focus && s.inputFocus, ton === "ok" && s.inputOk, ton === "err" && s.inputErr]}>
        <Text style={s.hash}>#</Text>
        <TextInput
          style={s.input} value={value} onChangeText={onChange}
          onFocus={() => setFocus(true)} onBlur={() => setFocus(false)}
          placeholder="KOD TWÓRCY" placeholderTextColor={C.dim}
          autoCapitalize="characters" autoCorrect={false} maxLength={24}
          editable={!busy} returnKeyType="done"
          onSubmitEditing={zPrzyciskiem ? () => przypisz() : undefined}
        />
        {checking && <ActivityIndicator size="small" color={C.amber} />}
        {!checking && <PopCheck ok={Boolean(rozpoznany)} />}
      </View>
      {zPrzyciskiem && (
        <MetalButton label={busy ? "…" : "Przypisz"} tone="green" active
                     disabled={busy || value.length < 3} onPress={() => przypisz()} />
      )}
    </Animated.View>
  );

  // ---- okno logowania: pole bez przycisku, zapis i sprawdzanie w trakcie pisania
  if (place === "signup") {
    return (
      <GlowBorder ton={ton} style={{ marginTop: 20 }}>
        {naglowek(
          "Masz kod od twórcy?",
          pending?.code && !open ? `Zapamiętany kod: ${pending.code}` : "Wpisz go przed zalogowaniem — działa też z Google",
          true,
        )}
        <Rozwin open={open}>
          <View style={{ marginTop: 13 }}>
            {pole(false)}
            {rozpoznany && (
              <CreatorChip creator={rozpoznany.creator || ""} handle={rozpoznany.handle}
                           reward={rewardInfo(rozpoznany)} />
            )}
            {komunikat || (!rozpoznany && (
              <Text style={s.hint}>Kod przypisze się do konta po zalogowaniu. Cena premium się nie zmienia.</Text>
            ))}
          </View>
        </Rozwin>
      </GlowBorder>
    );
  }

  const tresc = (
    <>
      {place === "paywall"
        ? naglowek("Masz kod od twórcy?", "Ostatnia chwila, żeby go dodać — po zakupie już się nie da", true)
        : naglowek("Wpisz kod twórcy", "Jedno konto wspiera jednego twórcę · cena się nie zmienia", false)}
      <Rozwin open={open}>
        <View style={{ marginTop: 13 }}>
          {!user && pending?.code && (
            <Text style={[s.hint, { marginTop: 0, marginBottom: 8 }]}>
              Zapamiętany kod: {pending.code} — przypiszemy go po zalogowaniu.
            </Text>
          )}
          {pole(true)}
          {busy && <ActivityIndicator color={C.green} style={{ marginTop: 10 }} />}
          {komunikat || (
            <Text style={s.hint}>
              {place === "paywall"
                ? "Kod przypisuje się do konta na stałe i nie zmienia ceny."
                : "Kod przypisuje się do konta na stałe."}
            </Text>
          )}
        </View>
      </Rozwin>
    </>
  );

  if (place === "paywall") return <GlowBorder ton={ton} style={{ marginTop: 16 }}>{tresc}</GlowBorder>;
  return <Sekcja><GlowBorder ton={ton}>{tresc}</GlowBorder></Sekcja>;
}

/** Nagłówek sekcji w „Więcej" siedzi TUTAJ, a nie w ekranie: gdy pole się chowa
 *  (konto już płaci, baza kodów nie działa), nie może zostać osierocony tytuł. */
function Sekcja({ children }: { children: React.ReactNode }) {
  return (
    <>
      <SectionTitle hint="Kod twórcy, który poleca Portevo — wspierasz go, a cena się nie zmienia">
        Kod polecający
      </SectionTitle>
      {children}
    </>
  );
}

