/** Pasek świeżości wyceny — pokazuje, jak aktualne są kursy pod wartością portfela. */
import React, { useEffect, useRef, useState } from "react";
import { Animated, Easing, StyleSheet, Text, View } from "react-native";
import { QuotesInfo } from "../api";
import { C } from "../theme";

const hhmm = (ts: number) =>
  new Date(ts * 1000).toLocaleTimeString("pl-PL", { hour: "2-digit", minute: "2-digit" });

const ago = (sec: number) =>
  sec < 90 ? `${Math.max(1, Math.round(sec))} s temu`
    : sec < 5400 ? `${Math.round(sec / 60)} min temu`
    : `${Math.round(sec / 3600)} h temu`;

export default function LiveBar({ q, onPress }: { q?: QuotesInfo; onPress?: () => void }) {
  // licznik „X min temu" tyka lokalnie, bez odpytywania serwera
  const [, tick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => tick((x) => x + 1), 10000);
    return () => clearInterval(id);
  }, []);

  const pulse = useRef(new Animated.Value(0)).current;
  const live = Boolean(q?.market_open && q.age_sec != null && q.age_sec < 120);

  useEffect(() => {
    if (!live) { pulse.stopAnimation(); pulse.setValue(0); return; }
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, { toValue: 1, duration: 1100, easing: Easing.out(Easing.quad), useNativeDriver: true }),
        Animated.timing(pulse, { toValue: 0, duration: 900, easing: Easing.in(Easing.quad), useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [live]);

  if (!q || !q.total) return null;

  const age = q.age_sec == null ? null : q.age_sec + secondsSince(q);
  const stale = age != null && age > 3600;
  const color = live ? C.green : stale ? C.amber : C.muted;
  const bg = live ? "rgba(47,212,138,.07)" : stale ? "rgba(255,180,84,.07)" : C.elev;
  const border = live ? "rgba(47,212,138,.35)" : stale ? "rgba(255,180,84,.35)" : C.border;

  return (
    <View style={[s.bar, { backgroundColor: bg, borderColor: border }]} onTouchEnd={onPress}>
      <View style={s.dotWrap}>
        {live && (
          <Animated.View
            style={[
              s.ring,
              {
                opacity: pulse.interpolate({ inputRange: [0, 1], outputRange: [0.55, 0] }),
                transform: [{ scale: pulse.interpolate({ inputRange: [0, 1], outputRange: [1, 2.6] }) }],
              },
            ]}
          />
        )}
        <View style={[s.dot, { backgroundColor: color }]} />
      </View>
      <Text style={[s.txt, { color }]} numberOfLines={1}>
        {live && q.newest_ts
          ? `NA ŻYWO · ${hhmm(q.newest_ts)}`
          : q.newest_ts
            ? `Kursy z ${hhmm(q.newest_ts)}${age != null ? ` (${ago(age)})` : ""}`
            : "brak notowań"}
        <Text style={s.sep}>{"   "}{q.live}/{q.total} pozycji</Text>
      </Text>
    </View>
  );
}

/** Ile czasu minęło od momentu, w którym serwer policzył wiek notowania. */
function secondsSince(q: QuotesInfo) {
  const drift = Math.round(Date.now() / 1000) - q.server_now;
  return Math.max(0, drift);
}

const s = StyleSheet.create({
  bar: {
    flexDirection: "row", alignItems: "center", gap: 9, alignSelf: "flex-start",
    borderWidth: 1, borderRadius: 999, paddingHorizontal: 12, paddingVertical: 6, marginTop: 10,
  },
  dotWrap: { width: 8, height: 8, alignItems: "center", justifyContent: "center" },
  dot: { width: 7, height: 7, borderRadius: 4 },
  ring: {
    position: "absolute", width: 7, height: 7, borderRadius: 4, backgroundColor: C.green,
  },
  txt: { fontSize: 12, fontWeight: "700" },
  sep: { color: C.dim, fontWeight: "500" },
});
