/** Aplikacja — jedyna strona w apce, która czegoś sprzedaje.
 *
 *  Powód istnienia: ktoś, kto wszedł na portevo.pl z przeglądarki, nie ma skąd
 *  wiedzieć dwóch rzeczy — że to samo działa na telefonie i że istnieje wersja
 *  płatna. Jedno i drugie było schowane: aplikacja mobilna nie była wspomniana
 *  nigdzie, a premium wyskakiwało dopiero po kliknięciu w kłódkę, czyli tylko
 *  temu, kto sam trafił na zamkniętą funkcję.
 *
 *  Kolejność sekcji jest celowa i idzie od najmniejszego zobowiązania:
 *  najpierw „weź to na telefon" (nic nie kosztuje), potem zrzuty ekranu jako
 *  dowód, że jest co brać, a dopiero na końcu premium. Odwrotna kolejność
 *  wita cennikiem kogoś, kto jeszcze nie wie, co dostaje.
 *
 *  Ekran jest WYŁĄCZNIE dla przeglądarki — patrz komentarz przy `TABS`.
 */
import React, { useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator, Image, Linking, Platform, ScrollView, StyleSheet, Text, View,
} from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { getPremiumCatalog, PremiumCatalog, PremiumFeature, trackPremium } from "../api";
import { useAuth } from "../auth/AuthContext";
import AboutStudio from "../components/AboutStudio";
import QrCode from "../components/QrCode";
import { useLayout, TAB_SPACE } from "../layout";
import { APP_STORE, INSTALACJA, SKLEPY, ZRZUTY } from "../promo";
import { C, T } from "../theme";
import Icon, { IconName, IkonaZSerwera } from "../ui/Icon";
import { Card, FadeIn, MetalButton } from "../ui";

export default function AppPromoScreen() {
  const { wide } = useLayout();
  const { premium, showPaywall } = useAuth();
  const [katalog, setKatalog] = useState<PremiumCatalog | null>(null);

  useEffect(() => {
    getPremiumCatalog().then(setKatalog).catch(() => setKatalog(null));
  }, []);

  return (
    <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
      <SekcjaTelefon wide={wide} />
      <SekcjaZrzuty wide={wide} />
      <SekcjaPremium katalog={katalog} premium={premium} wide={wide}
                     onPaywall={(id) => showPaywall(id)} />

      <Text style={s.stopka}>
        Portevo nie jest doradcą inwestycyjnym. Dane mają charakter informacyjny
        i nie stanowią rekomendacji ani oferty kupna lub sprzedaży instrumentów
        finansowych.
      </Text>
    </ScrollView>
  );
}

/* ------------------------------------------------------------- na telefon */

function SekcjaTelefon({ wide }: { wide: boolean }) {
  return (
    <FadeIn>
      <View style={s.hero}>
        {/* Złoto jest tłem, nie obwódką: ta sekcja ma wołać, a nie szeptać. */}
        <LinearGradient
          colors={["rgba(255,210,74,.16)", "rgba(200,137,32,.05)", "rgba(8,11,17,0)"]}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill as any}
        />
        <View style={[s.heroIn, wide && { flexDirection: "row", alignItems: "center", gap: 30 }]}>
          <View style={{ flex: 1 }}>
            <Text style={s.nadtytul}>PORTEVO NA TELEFONIE</Text>
            <Text style={s.heroH1}>Portevo jest w App Store</Text>
            <Text style={s.heroTxt}>
              Kalendarz wyników, portfel i karta spółki działają na telefonie tak
              samo jak tutaj — to jedna aplikacja, nie okrojona wersja strony.
              Do tego powiadomienia: telefon odezwie się, gdy pojawi się news
              o spółce z Twojego portfela.
            </Text>

            <View style={s.zaletyRzad}>
              {[
                ["dzwonek", "Powiadomienia o Twoich spółkach",
                  "News z ESPI albo SEC trafia na ekran blokady w kilka sekund"],
                ["przeglad", "Ten sam kod, co na stronie",
                  "Portfel, kalendarz wyników i karta spółki bez okrojeń"],
                ["premium", "Za darmo", "Premium tylko wtedy, gdy zechcesz więcej"],
              ].map(([ikona, tytul, opis]) => (
                <View key={tytul} style={s.zaleta}>
                  <View style={s.zaletaIkona}><Icon name={ikona as IconName} size={15} color={C.gold} /></View>
                  <View style={{ flex: 1 }}>
                    <Text style={s.zaletaTytul}>{tytul}</Text>
                    <Text style={s.zaletaOpis}>{opis}</Text>
                  </View>
                </View>
              ))}
            </View>
          </View>

          <PobierzZApple />
        </View>
      </View>

      <SzczegolyWydania wide={wide} />

      {/* Android nie ma jeszcze sklepu, więc dla niego zostaje droga przez
          przeglądarkę. Dla iPhone'a to już tylko wariant zapasowy — dlatego
          instrukcje zeszły pod sekcję App Store, a nie stoją obok niej. */}
      <Text style={s.podsekcja}>Bez App Store — prosto z przeglądarki</Text>
      <Text style={s.podsekcjaOpis}>
        Portevo działa też jako strona dodana do ekranu początkowego: ten sam kod,
        bez instalacji. Na Androidzie to dziś jedyna droga — aplikacja w Google Play
        jeszcze nie powstała.
      </Text>

      <View style={[s.instalacja, wide && { flexDirection: "row", gap: 12 }]}>
        {INSTALACJA.map((i) => (
          <Card key={i.system} style={[s.instKarta, wide ? { flex: 1 } : { marginBottom: 10 }]}>
            <Text style={s.instSystem}>{i.system}</Text>
            {i.kroki.map((k, n) => (
              <View key={k} style={s.instKrok}>
                <Text style={s.instNr}>{n + 1}</Text>
                <Text style={s.instTxt}>{k}</Text>
              </View>
            ))}
          </Card>
        ))}
      </View>
    </FadeIn>
  );
}

/* --------------------------------------------------- pobranie z App Store */

/** Kolumna pobierania: kod do zeskanowania + przycisk.
 *
 *  Kod QR ZOSTAJE, ale prowadzi teraz do App Store, a nie na stronę — i dopiero
 *  w tej wersji ma sens. Wcześniej pokazywał adres, który człowiek i tak miał
 *  otwarty w przeglądarce („zeskanuj, żeby zobaczyć to samo"), więc wyglądał
 *  dziwnie. Skan prowadzący wprost do instalacji rozwiązuje realny problem:
 *  ktoś siedzi przy komputerze, a aplikację chce mieć na telefonie.
 */
function PobierzZApple() {
  const adres = SKLEPY.ios;
  if (!adres) return null;

  return (
    <View style={s.qrBok}>
      <View style={s.qrRamka}>
        <QrCode value={adres} size={172} color="#0b0e14" background="#ffffff" />
      </View>
      <Text style={s.qrAdres}>Zeskanuj telefonem</Text>

      <MetalButton
        label="Pobierz z App Store" tone="amber" accent={C.gold} active liquid full
        style={{ marginTop: 11 }}
        onPress={() => otworzAdres(adres)}
      />
      <Text style={s.qrCena}>
        {APP_STORE.cena} · {APP_STORE.cenaDopisek}
      </Text>
    </View>
  );
}

/** Suchy metryczek wydania — to, czego szuka się przed pobraniem czegokolwiek. */
function SzczegolyWydania({ wide }: { wide: boolean }) {
  const dane: [IconName, string, string][] = [
    ["premium", "Cena", `${APP_STORE.cena} · ${APP_STORE.cenaDopisek}`],
    ["aplikacja", "Wymagania", APP_STORE.system],
    ["teczka", "Rozmiar", APP_STORE.rozmiar],
    ["dzwonek", "Powiadomienia", "O newsach i wynikach Twoich spółek"],
  ];
  return (
    <View style={[s.metryka, wide && { flexDirection: "row", gap: 10 }]}>
      {dane.map(([ikona, klucz, wartosc]) => (
        <Card key={klucz} style={[s.metrykaKarta, wide ? { flex: 1, flexBasis: 0 } : { marginBottom: 8 }]}>
          <View style={s.metrykaIkona}>
            <Icon name={ikona} size={14} color={C.gold} />
          </View>
          <Text style={s.metrykaKlucz}>{klucz}</Text>
          <Text style={s.metrykaWartosc}>{wartosc}</Text>
        </Card>
      ))}
    </View>
  );
}

/* ---------------------------------------------------------------- zrzuty */

/** Podpis sekcji mówi „materiały prezentacyjne", a nie „prawdziwe ekrany" —
 *  i to nie jest ostrożnościowa asekuracja, tylko stan faktyczny. Kadry
 *  w `bot/static/promo/` to kolaże marketingowe z `app-store/screenshots/`,
 *  w których napisy WEWNĄTRZ telefonu wygenerował model i są zmyślone
 *  (szczegóły w `app-store/screenshots/README.md`). Kiedy powstaną zrzuty
 *  z symulatora, można wrócić do mocniejszego podpisu — wcześniej nie. */
function SekcjaZrzuty({ wide }: { wide: boolean }) {
  return (
    <>
      <Text style={s.sekcja}>Jak to wygląda</Text>
      <Text style={s.sekcjaHint}>Materiały prezentacyjne — sekcje jak w aplikacji</Text>
      <View style={s.zrzutyRzad}>
        {ZRZUTY.map((z, i) => (
          <FadeIn key={z.plik} delay={Math.min(i * 70, 280)} offset={10}
                  style={[s.zrzutKom, { width: wide ? "25%" : "50%" }]}>
            <Zrzut plik={z.plik} tytul={z.tytul} opis={z.opis} />
          </FadeIn>
        ))}
      </View>
    </>
  );
}

/** Kafelek zrzutu ekranu, który sam radzi sobie z brakiem pliku.
 *
 *  Zamiast pustej ramki albo ikony zepsutego obrazka pokazuje podpis tego, co
 *  ma się tam znaleźć. Dzięki temu układ strony jest gotowy i wygląda sensownie
 *  także zanim zrzuty powstaną — a gdy plik wyląduje w `bot/static/promo/`,
 *  podmienia się sam, bez zmiany w kodzie.
 */
function Zrzut({ plik, tytul, opis }: { plik: string; tytul: string; opis: string }) {
  const [brak, setBrak] = useState(false);
  // `source` musi być TYM SAMYM obiektem między renderami. Zapisane wprost jako
  // `{{ uri: plik }}` powstaje na nowo przy każdym renderze, a `Image` widzi
  // wtedy zmianę źródła i pobiera obrazek jeszcze raz — w sieci było widać
  // trzy komplety żądań zamiast jednego.
  const zrodlo = useMemo(() => ({ uri: plik }), [plik]);

  return (
    <View>
      <View style={s.ekranRamka}>
        {brak ? (
          <View style={s.ekranPusty}>
            <Text style={s.ekranPustyIkona}>▢</Text>
            <Text style={s.ekranPustyTxt}>zrzut{"\n"}wkrótce</Text>
          </View>
        ) : (
          <Image
            source={zrodlo}
            style={s.ekranObraz}
            resizeMode="cover"
            onError={() => setBrak(true)}
          />
        )}
      </View>
      <Text style={s.zrzutTytul} numberOfLines={1}>{tytul}</Text>
      <Text style={s.zrzutOpis} numberOfLines={3}>{opis}</Text>
    </View>
  );
}

/* --------------------------------------------------------------- premium */

function SekcjaPremium({
  katalog, premium, wide, onPaywall,
}: {
  katalog: PremiumCatalog | null;
  premium: boolean;
  wide: boolean;
  onPaywall: (featureId: string) => void;
}) {
  if (!katalog) {
    return (
      <>
        <Text style={s.sekcja}>Portevo Premium</Text>
        <View style={s.center}><ActivityIndicator color={C.amber} /></View>
      </>
    );
  }

  const funkcje = katalog.features || [];
  const pierwsza = funkcje[0]?.id || "tools.etf";

  return (
    <>
      <View style={s.premHero}>
        <Text style={s.premNad}>WERSJA PŁATNA</Text>
        <Text style={s.premH1}>{katalog.headline || "Portevo Premium"}</Text>
        {!!katalog.subheadline && <Text style={s.premSub}>{katalog.subheadline}</Text>}
        {premium && (
          <View style={s.premMasz}>
            <Text style={s.premMaszTxt}>Masz premium — wszystko jest odblokowane.</Text>
          </View>
        )}
      </View>

      {/* Ta sama sekcja co na stronie sprzedażowej i w profilu: zanim padnie cena,
          niech będzie wiadomo, na co idą pieniądze. Komuś, kto już zapłacił,
          zamienia się w podziękowanie. */}
      <AboutStudio premium={premium} />

      <Text style={s.sekcja}>Co dostajesz</Text>
      <View style={s.funkcjeRzad}>
        {funkcje.map((f, i) => (
          <FadeIn key={f.id} delay={Math.min(i * 40, 300)} offset={9}
                  style={[s.funkcjaKom, { width: wide ? "50%" : "100%" }]}>
            <FunkcjaKarta f={f} onPress={() => onPaywall(f.id)} />
          </FadeIn>
        ))}
      </View>

      <Text style={s.sekcja}>Ile to kosztuje</Text>
      <Text style={s.sekcjaHint}>
        Jedno konto obsługuje przeglądarkę i telefon. Trzon aplikacji zostaje darmowy.
      </Text>
      <View style={[s.planyRzad, wide && { flexDirection: "row", gap: 11 }]}>
        {(katalog.plans || []).map((p) => (
          <Card key={p.id} style={[s.plan, wide ? { flex: 1 } : { marginBottom: 10 },
                                   p.highlight && s.planHot]}>
            {!!p.badge && (
              <View style={s.planBadge}><Text style={s.planBadgeTxt}>{p.badge}</Text></View>
            )}
            <Text style={s.planNazwa}>{p.label}</Text>
            <View style={{ flexDirection: "row", alignItems: "baseline",
                           flexWrap: "wrap", justifyContent: "center", gap: 6, marginTop: 4 }}>
              {!!p.price_original && p.price_original > p.price && (
                <Text style={s.planStara}>{kwota(p.price_original, p.currency)}</Text>
              )}
              <Text style={[s.planCena, p.highlight && { color: C.amber }]}>
                {kwota(p.price, p.currency)}
              </Text>
              <Text style={s.planZa}>/ {p.period}</Text>
            </View>
            {!!p.save_label && (
              <View style={s.planOszcz}><Text style={s.planOszczTxt}>{p.save_label}</Text></View>
            )}
            {!!p.note && <Text style={s.planNota}>{p.note}</Text>}
          </Card>
        ))}
      </View>

      {!premium && (
        <MetalButton
          label="Zobacz, co jest w premium" tone="amber" active liquid full
          style={{ marginTop: 16 }}
          onPress={() => { trackPremium("promo_cta", pierwsza); onPaywall(pierwsza); }}
        />
      )}
    </>
  );
}

function FunkcjaKarta({ f, onPress }: { f: PremiumFeature; onPress: () => void }) {
  return (
    <Card style={s.funkcja}>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
        <IkonaZSerwera name={f.icon} size={19} color={C.gold} />
        <Text style={s.funkcjaTytul} numberOfLines={1}>{f.title}</Text>
        {f.status === "soon" && <Text style={s.wkrotce}>WKRÓTCE</Text>}
      </View>
      <Text style={s.funkcjaTag}>{f.tagline}</Text>
      {!!f.bullets?.length && (
        <View style={{ marginTop: 9, gap: 5 }}>
          {f.bullets.slice(0, 3).map((b) => (
            <View key={b} style={{ flexDirection: "row", gap: 8 }}>
              <View style={s.ptaszek}><Icon name="ptaszek" size={12} color={C.gold} /></View>
              <Text style={s.punkt}>{b}</Text>
            </View>
          ))}
        </View>
      )}
      <MetalButton label="Zobacz szczegóły" tone="amber" size="sm" full
                   style={{ marginTop: 12 }} onPress={onPress} />
    </Card>
  );
}

/* ------------------------------------------------------------------ reszta */

/** Kwota z groszami po polsku — ta sama postać co na stronie sprzedażowej. */
function kwota(v: number, currency = "PLN") {
  const n = v.toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return currency === "PLN" ? `${n} zł` : `${n} ${currency}`;
}

function otworzAdres(adres: string) {
  if (Platform.OS === "web") {
    try {
      window.open(adres, "_blank", "noopener,noreferrer");
      return;
    } catch { /* zablokowane okno — spróbujemy zwykłym otwarciem */ }
  }
  Linking.openURL(adres).catch(() => {});
}

