/** Szlak decyzji — jak bot dochodzi do wniosku o wiadomości.
 *
 *  Przeniesione ze starego panelu webowego i przepisane pod obecny stan rzeczy:
 *  bot nie handluje, więc etapy opisują DROGĘ DO ANALIZY, a nie do zlecenia.
 *  Ostatni etap („Ty decydujesz") jest tu celowo — kończy ścieżkę tam, gdzie
 *  faktycznie się kończy: na człowieku z informacją, a nie na automacie.
 *
 *  Wartości nie są przepisane na sztywno: każdy etap czyta żywe params.json
 *  i konfigurację promptów, więc pokazuje to, co naprawdę obowiązuje.
 */
import React, { useState } from "react";
import { ScrollView, StyleSheet, Text, View } from "react-native";
import { Brain } from "../../api";
import { C, T } from "../../theme";
import { Card, FadeIn, Press } from "../../ui";
import Icon, { IconName } from "../../ui/Icon";

type Stage = {
  id: string;
  ico: IconName;
  title: string;
  sub: string;
  head: string;
  intro: string;
  rows: [string, string][];
  note?: string;
};

function buildStages(brain: Brain): Stage[] {
  const p = brain.params || {};
  const cfg = brain.config;
  const models = brain.models || { free: [], paid_fast: "—", verify: "—" };

  const sources: [string, boolean][] = [
    ["Truth Social", Boolean(p.truth_social_enabled)],
    ["SEC 8-K", Boolean(p.sec_edgar_enabled)],
    ["Squawk", Boolean(p.squawk_enabled)],
    ["Gov RSS", Boolean(p.gov_rss_enabled)],
    ["GPW ESPI", Boolean(p.gpw_espi_enabled)],
    ["KNF", Boolean(p.knf_enabled)],
  ];
  const onCount = sources.filter(([, on]) => on).length;

  const cats = Object.entries(cfg.categories || {}).filter(([, c]) => c.enabled !== false);
  const mults = cats.map(([, c]) => Number(c.mult) || 1);
  const multRange = mults.length
    ? `×${Math.min(...mults).toFixed(2)} – ×${Math.max(...mults).toFixed(2)}`
    : "—";

  return [
    {
      id: "sources", ico: "antena", title: "Źródła", sub: `${onCount}/${sources.length} aktywnych`,
      head: "Nasłuch źródeł",
      intro: "Bot odpytuje każde źródło własnym rytmem. Nowy materiał trafia do analizy "
           + "natychmiast, w osobnym wątku — liczy się każda sekunda.",
      rows: [
        ...sources.map(([n, on]) => [n, on ? "włączone" : "wyłączone"] as [string, string]),
        ["Świeżość postów", `max ${p.max_post_age_minutes ?? "—"} min`],
        ["Świeżość raportów SEC", `max ${p.max_filing_age_minutes ?? "—"} min`],
        ["Świeżość GPW", `max ${p.max_gpw_age_minutes ?? "—"} min`],
      ],
      note: "Liczniki i przełączniki źródeł znajdziesz w zakładce Źródła.",
    },
    {
      id: "prefilter", ico: "sito", title: "Pre-filtr", sub: "tanie odsianie szumu",
      head: "Pre-filtr — bez AI, zero kosztu",
      intro: "Zanim poleci choć jedno zapytanie do modelu, odpadają rzeczy oczywiście bezwartościowe.",
      rows: [
        ["Za krótki tekst", "poniżej 15 znaków (mem, emotka, pusty retruth)"],
        ["Sam odnośnik", "wpis będący wyłącznie adresem URL"],
      ],
      note: "Odrzucone wpisy widać w Analizach z dopiskiem [pre-filtr].",
    },
    {
      id: "summary", ico: "streszczenie", title: "Streszczenie", sub: "długie teksty",
      head: "Kompresja długich raportów",
      intro: "Raport SEC potrafi mieć dziesiątki stron. Tekst powyżej 1500 znaków najpierw "
           + "streszcza tańszy model, a dopiero streszczenie idzie do właściwej analizy.",
      rows: [
        ["Model streszczający", "pierwszy dostępny darmowy"],
        ["Limit czasu", "8 sekund"],
        ["Gdy streszczanie padnie", "pełny tekst leci dalej (limit 25 s)"],
      ],
    },
    {
      id: "ai1", ico: "ai", title: "Analiza AI", sub: "kogo dotyczy i jak mocno",
      head: "Etap 1 — szybka analiza",
      intro: "Model dostaje instrukcje (zakładka Prompty) oraz treść wiadomości i odpowiada "
           + "ustrukturyzowanie: czy rzecz dotyczy konkretnej spółki, jaka to kategoria "
           + "wiadomości, jaka ranga autora i jak mocny jest wydźwięk w skali 0–100.",
      rows: [
        ["Darmowe modele", models.free.length ? models.free.join("\n") : "—"],
        ["Płatny zapas", models.paid_fast || "—"],
        ["Próby", "2 rundy po darmowych, potem płatny"],
      ],
      note: "Pełną treść instrukcji podejrzysz w zakładce Prompty.",
    },
    {
      id: "gates", ico: "bramki", title: "Bramki", sub: "co odpada",
      head: "Bramki — kiedy odpuszczamy",
      intro: "Analiza musi przejść wszystkie bramki. Jeśli którejś nie przejdzie, ląduje "
           + "w Analizach jako pominięta, razem z powodem.",
      rows: [
        ["Rozpoznana spółka", "wiadomość musi wskazywać konkretny walor"],
        ["Siła wydźwięku", `min. ${p.min_signal_strength ?? "—"} / 100`],
        ["Tematyczne", p.thematic_enabled ? "przepuszczane" : "wyłączone"],
        ["Makro", p.macro_enabled ? "przepuszczane" : "wyłączone"],
        ["Sesja giełdy", "USA 15:30–22:00, GPW 9:00–17:00; krypto i makro zawsze"],
      ],
      note: "Wiadomość po sesji zostaje zapisana, ale bez pomiaru kursu — do otwarcia "
          + "rynek zdąży ją wycenić.",
    },
    {
      id: "weights", ico: "wagi", title: "Wagi", sub: "co wzmacnia wydźwięk",
      head: "Co wzmacnia, a co osłabia wymowę",
      intro: "Ta sama wiadomość znaczy co innego z ust prezesa, a co innego z anonimowego konta. "
           + "Wagi ustawiasz w zakładkach Kategorie i Autorytet.",
      rows: [
        ["Kategoria wiadomości", multRange],
        ["Aktywnych kategorii", String(cats.length)],
        ["Ranga autora", Object.entries(cfg.authority || {})
          .map(([k, a]) => `${k} ×${Number(a.mult).toFixed(2)}`).join("\n") || "—"],
        ["Powtórki", "kolejna wzmianka o tej samej spółce niesie mniej nowego"],
      ],
    },
    {
      id: "verify", ico: "lupa", title: "Druga opinia", sub: p.verify_enabled ? "włączona" : "wyłączona",
      head: "Etap 2 — sprawdzenie analizy",
      intro: "Mocniejszy model dostaje wiadomość razem z gotową analizą i szuka wyraźnych "
           + "błędów: pomylonej spółki, odwróconego wydźwięku, halucynacji, starej informacji.",
      rows: [
        ["Model", models.verify || "—"],
        ["Stan", p.verify_enabled ? "włączona" : "wyłączona"],
        ["Efekt zastrzeżenia", "analiza zostaje, ale z widoczną adnotacją"],
      ],
      note: "Niepewność sama w sobie nie jest błędem — opisujemy ją, zamiast ukrywać.",
    },
    {
      id: "measure", ico: "akcje", title: "Pomiar", sub: "co zrobił kurs",
      head: "Pomiar kursu po analizie",
      intro: "W chwili analizy zapisujemy kurs spółki i sprawdzamy go ponownie po godzinie "
           + "oraz po dniu. Z tego powstaje statystyka: jak często kurs poszedł w stronę "
           + "wskazanego wydźwięku.",
      rows: [
        ["Horyzonty", "1 godzina · 1 dzień"],
        ["Źródło kursów", "to samo co w portfelu (darmowe)"],
        ["„Zgodny”", "kurs ruszył w stronę wydźwięku wiadomości"],
      ],
      note: "To opis tego, co wydarzyło się na rynku. Nie ocena żadnej rekomendacji — "
          + "bot rekomendacji nie wydaje.",
    },
    {
      id: "you", ico: "ty", title: "Ty decydujesz", sub: "koniec ścieżki",
      head: "Decyzja należy do Ciebie",
      intro: "Tu bot się zatrzymuje. Dostajesz wiadomość, jej wydźwięk, uzasadnienie i to, "
           + "co kurs robił po podobnych wiadomościach wcześniej. Co z tym zrobisz, "
           + "zależy wyłącznie od Ciebie.",
      rows: [
        ["Co robi bot", "czyta, analizuje, mierzy, pokazuje"],
        ["Czego nie robi", "nie składa zleceń i nie łączy się z brokerem"],
      ],
      note: "Treści w aplikacji mają charakter informacyjny. Nie są poradą inwestycyjną "
          + "ani rekomendacją.",
    },
  ];
}

export default function DecisionPath({ brain }: { brain: Brain }) {
  const [open, setOpen] = useState<string | null>(null);
  const stages = buildStages(brain);
  const detail = stages.find((x) => x.id === open);

  return (
    <View style={{ marginTop: 4 }}>
      <Text style={s.hint}>
        Każda wiadomość idzie tą ścieżką od lewej do prawej. Dotknij etapu, żeby zobaczyć,
        co się w nim dzieje i jakie wartości tam teraz obowiązują.
      </Text>

      <ScrollView horizontal showsHorizontalScrollIndicator={false}
                  contentContainerStyle={s.rail}>
        {stages.map((st, i) => {
          const active = open === st.id;
          return (
            <React.Fragment key={st.id}>
              {i > 0 && <Text style={s.arrow}>›</Text>}
              <Press onPress={() => setOpen(active ? null : st.id)}
                     style={[s.node, active && s.nodeActive]}>
                <Text style={s.nodeNum}>{i + 1}</Text>
                <View style={s.nodeIco}><Icon name={st.ico} size={19} color={active ? C.green : C.muted} /></View>
                <Text style={[s.nodeTitle, active && { color: C.green }]}>{st.title}</Text>
                <Text style={s.nodeSub} numberOfLines={2}>{st.sub}</Text>
              </Press>
            </React.Fragment>
          );
        })}
      </ScrollView>

      {detail ? (
        <FadeIn key={detail.id} offset={8}>
          <Card style={s.detail}>
            <View style={s.detailHeadRow}>
              <Icon name={detail.ico} size={17} color={C.green} />
              <Text style={s.detailHead}>{detail.head}</Text>
            </View>
            <Text style={s.detailIntro}>{detail.intro}</Text>
            {detail.rows.map(([k, v]) => (
              <View key={k} style={s.row}>
                <Text style={s.rowK}>{k}</Text>
                <Text style={s.rowV}>{v}</Text>
              </View>
            ))}
            {!!detail.note && <Text style={s.note}>{detail.note}</Text>}
          </Card>
        </FadeIn>
      ) : (
        <Card style={s.empty}>
          <Text style={s.emptyTxt}>Dotknij etapu powyżej, żeby zobaczyć szczegóły.</Text>
        </Card>
      )}
    </View>
  );
}

const s = StyleSheet.create({
  hint: { color: C.muted, fontSize: 12, lineHeight: 17.5, marginTop: 12, marginBottom: 12 },
  rail: { paddingVertical: 2, paddingRight: 8, alignItems: "center" },
  arrow: { color: C.dim, fontSize: 18, marginHorizontal: 5 },
  node: {
    width: 128, padding: 11, borderRadius: 14, backgroundColor: C.card,
    borderWidth: 1, borderColor: C.border,
  },
  nodeActive: { borderColor: C.green, backgroundColor: "rgba(47,212,138,.07)" },
  nodeNum: { position: "absolute", top: 7, right: 9, color: C.dim, fontSize: 10, fontWeight: "700" },
  nodeIco: { marginBottom: 5 },
  nodeTitle: { color: C.text, fontSize: 13, fontWeight: "800" },
  nodeSub: { color: C.muted, fontSize: 10.5, lineHeight: 14, marginTop: 3 },

  detail: { padding: 15, marginTop: 12 },
  detailHeadRow: { flexDirection: "row", alignItems: "center", gap: 9, marginBottom: 8 },
  detailHead: { color: C.text, ...T.h2 },
  detailIntro: { color: C.muted, fontSize: 12.5, lineHeight: 18.5, marginBottom: 12 },
  row: {
    flexDirection: "row", paddingVertical: 8,
    borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },
  rowK: { color: C.muted, fontSize: 12, flex: 1, paddingRight: 12 },
  rowV: { color: C.text, fontSize: 12, flex: 1.15, textAlign: "right", lineHeight: 17 },
  note: {
    color: C.dim, fontSize: 11.5, lineHeight: 16.5, marginTop: 12,
    paddingTop: 10, borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },

  empty: { padding: 18, marginTop: 12, alignItems: "center" },
  emptyTxt: { color: C.dim, fontSize: 12 },
});
