/** Ustawienia nasłuchu live + stan techniczny komputera.
 *
 *  Trzymam tu razem dwie rzeczy, bo w praktyce zawsze schodzi się na jedno
 *  pytanie: „czemu nie ma transkrypcji?". Odpowiedź jest albo w brakującej
 *  zależności (ffmpeg, whisper), albo w wyłączonym dozorze, albo w progu
 *  pewności ustawionym tak wysoko, że nic go nie przechodzi.
 */
import React from "react";
import { StyleSheet, Switch, Text, View } from "react-native";
import { liveMonitorStart, liveMonitorStop, LiveState, setParams } from "../../../api";
import { C, T } from "../../../theme";
import { Card, FadeIn, MetalButton, Press, SectionTitle } from "../../../ui";

/** Modele rozpoznawania mowy: im większy, tym dokładniej i tym wolniej na CPU. */
const WHISPER = [
  { id: "tiny", label: "tiny", desc: "najszybszy, najwięcej pomyłek" },
  { id: "base", label: "base", desc: "rozsądny kompromis" },
  { id: "small", label: "small", desc: "dokładniejszy, obciąża procesor" },
  { id: "medium", label: "medium", desc: "najdokładniejszy, wymaga mocnego CPU" },
];

const NUMBERS: {
  key: string; label: string; desc: string; min: number; max: number; step: number; unit: string;
}[] = [
  { key: "live_analyze_seconds", label: "Analiza co", min: 6, max: 60, step: 2, unit: " s",
    desc: "Jak często model dostaje świeży kawałek transkrypcji do oceny." },
  { key: "live_analyze_seconds_hot", label: "Analiza co (priorytet)", min: 4, max: 30, step: 1, unit: " s",
    desc: "To samo dla wydarzeń oznaczonych błyskawicą — szybciej, ale drożej." },
  { key: "live_window_seconds", label: "Okno transkrypcji", min: 30, max: 240, step: 15, unit: " s",
    desc: "Ile ostatnich sekund wypowiedzi trafia do modelu jako kontekst." },
  { key: "live_chunk_seconds", label: "Porcja dźwięku", min: 4, max: 20, step: 1, unit: " s",
    desc: "Co ile sekund audio jest zamieniane na tekst. Mniej = szybciej na ekranie." },
  { key: "live_poll_seconds", label: "Sprawdzanie kanałów", min: 15, max: 300, step: 15, unit: " s",
    desc: "Jak często dozór pyta YouTube, czy kanał wszedł na antenę." },
  { key: "live_signal_cooldown_minutes", label: "Odstęp powtórek", min: 1, max: 30, step: 1, unit: " min",
    desc: "Nie powtarzaj tego samego wniosku o tej samej spółce częściej niż co tyle." },
];

export default function SettingsTab({
  st, busy, act,
}: {
  st: LiveState; busy: string;
  act: (label: string, fn: () => Promise<any>) => Promise<any>;
}) {
  const p = st.params || {};
  const deps = st.deps || ({} as any);
  const mon = st.monitor || ({} as any);
  const monitorOn = Boolean(mon.running);

  const patch = (updates: Record<string, any>) => act("param", () => setParams(updates));
  const ago = (ts?: number | null) =>
    ts ? `${Math.max(0, Math.round((st.server_time || 0) - ts))} s temu` : "—";

  return (
    <View>
      {/* ---------- dozór ---------- */}
      <Card style={s.card}>
        <View style={s.rowBetween}>
          <View style={{ flex: 1, paddingRight: 12 }}>
            <Text style={s.label}>Dozór automatyczny</Text>
            <Text style={s.desc}>
              Sprawdza kanały i kalendarz, a śledzone wydarzenia startuje sam, gdy wejdą
              na antenę. Bez niego wszystko odpalasz ręcznie.
            </Text>
          </View>
          <MetalButton size="sm" tone={monitorOn ? "red" : "green"}
                       label={busy === "monitor" ? "…" : monitorOn ? "Wyłącz" : "Włącz"}
                       onPress={() => act("monitor", () =>
                         monitorOn ? liveMonitorStop() : liveMonitorStart())} />
        </View>
        {monitorOn && (
          <View style={s.stats}>
            <Stat k="Ostatni obieg kanałów" v={ago(mon.last_poll)} />
            <Stat k="Ostatnie odświeżenie FDA" v={ago(mon.last_fda_refresh)} />
            <Stat k="Kanałów sprawdzanych" v={String(Object.keys(mon.channel_checks || {}).length)} />
            {!!mon.last_error && <Stat k="Ostatni błąd" v={String(mon.last_error)} bad />}
          </View>
        )}
      </Card>

      {/* ---------- co komputer ma zainstalowane ---------- */}
      <Card style={[s.card, !deps.ready && s.cardWarn]}>
        <Text style={s.label}>
          {deps.ready ? "Komputer gotowy" : "Brakuje narzędzi na komputerze"}
        </Text>
        <View style={s.stats}>
          {(["ffmpeg", "yt_dlp", "faster_whisper", "numpy"] as const).map((k) => (
            <Stat key={k} k={k.replace("_", "-")} v={deps[k] ? "jest" : "brak"} bad={!deps[k]} />
          ))}
        </View>
        {!deps.ready && (
          <Text style={s.desc}>
            Bez kompletu nie da się pobrać dźwięku ani zamienić go na tekst. Instalacja
            odbywa się na komputerze — telefon niczego tu nie naprawi.
          </Text>
        )}
      </Card>

      {/* ---------- pogłębiona analiza ---------- */}
      <SectionTitle>Analiza</SectionTitle>
      <Card style={s.card}>
        <View style={s.rowBetween}>
          <View style={{ flex: 1, paddingRight: 12 }}>
            <Text style={s.label}>Pogłębiona analiza mocnych fragmentów</Text>
            <Text style={s.desc}>
              Fragment, który przekroczy próg pewności, idzie do pełnej analizy razem
              z resztą wiadomości i trafia do zakładki Analizy. Wyłączone = same alerty.
            </Text>
          </View>
          <Switch value={Boolean(p.live_auto_analyze)}
                  onValueChange={(v) => patch({ live_auto_analyze: v })}
                  trackColor={{ false: "#2a3247", true: "rgba(47,212,138,.5)" }}
                  thumbColor={p.live_auto_analyze ? C.green : "#fff"} />
        </View>
      </Card>

      <Card style={s.card}>
        <View style={s.rowBetween}>
          <Text style={s.label}>Próg pewności</Text>
          <View style={s.stepper}>
            <MetalButton size="sm" round label="−" textStyle={{ fontSize: 17 }}
                         onPress={() => patch({
                           live_confidence_threshold:
                             Math.max(0.5, +(Number(p.live_confidence_threshold ?? 0.85) - 0.05).toFixed(2)),
                         })} />
            <Text style={s.val}>
              {Math.round(Number(p.live_confidence_threshold ?? 0.85) * 100)}%
            </Text>
            <MetalButton size="sm" round label="+" textStyle={{ fontSize: 17 }}
                         onPress={() => patch({
                           live_confidence_threshold:
                             Math.min(0.99, +(Number(p.live_confidence_threshold ?? 0.85) + 0.05).toFixed(2)),
                         })} />
          </View>
        </View>
        <Text style={s.desc}>
          Niżej = więcej wyłapanych fragmentów, ale i więcej fałszywych trafień.
        </Text>
      </Card>

      {/* ---------- tempo ---------- */}
      <SectionTitle hint="Zmiany działają od następnego cyklu — bez restartu sesji">
        Tempo nasłuchu
      </SectionTitle>
      {NUMBERS.map((n, i) => {
        const val = Number(p[n.key] ?? 0);
        return (
          <FadeIn key={n.key} delay={Math.min(i * 20, 180)} offset={8}>
            <Card style={s.card}>
              <View style={s.rowBetween}>
                <Text style={s.label}>{n.label}</Text>
                <View style={s.stepper}>
                  <MetalButton size="sm" round label="−" textStyle={{ fontSize: 17 }}
                               onPress={() => patch({ [n.key]: Math.max(n.min, val - n.step) })} />
                  <Text style={s.val}>{val}{n.unit}</Text>
                  <MetalButton size="sm" round label="+" textStyle={{ fontSize: 17 }}
                               onPress={() => patch({ [n.key]: Math.min(n.max, val + n.step) })} />
                </View>
              </View>
              <Text style={s.desc}>{n.desc}</Text>
            </Card>
          </FadeIn>
        );
      })}

      {/* ---------- model mowy ---------- */}
      <SectionTitle hint="Zmiana zadziała przy następnym starcie sesji">
        Rozpoznawanie mowy
      </SectionTitle>
      <Card style={s.card}>
        <View style={s.chips}>
          {WHISPER.map((w) => {
            const on = (p.live_whisper_model || "base") === w.id;
            return (
              <Press key={w.id} onPress={() => patch({ live_whisper_model: w.id })}
                     style={[s.chip, on && s.chipOn]}>
                <Text style={[s.chipTxt, on && { color: C.green }]}>{w.label}</Text>
              </Press>
            );
          })}
        </View>
        <Text style={s.desc}>
          {WHISPER.find((w) => w.id === (p.live_whisper_model || "base"))?.desc}
          {"  "}Model pobiera się raz i zajmuje miejsce na dysku komputera.
        </Text>
      </Card>
    </View>
  );
}

function Stat({ k, v, bad }: { k: string; v: string; bad?: boolean }) {
  return (
    <View style={s.stat}>
      <Text style={s.statK}>{k}</Text>
      <Text style={[s.statV, bad && { color: C.red }]} numberOfLines={2}>{v}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  card: { padding: 14, marginBottom: 9 },
  cardWarn: { borderWidth: 1, borderColor: "rgba(255,180,84,.4)" },
  rowBetween: { flexDirection: "row", alignItems: "center", justifyContent: "space-between" },
  label: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  desc: { color: C.dim, fontSize: 11.5, lineHeight: 16.5, marginTop: 6 },

  stats: { marginTop: 12 },
  stat: {
    flexDirection: "row", paddingVertical: 6,
    borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },
  statK: { color: C.muted, fontSize: 11.5, flex: 1 },
  statV: { color: C.text, fontSize: 11.5, flex: 1, textAlign: "right" },

  stepper: { flexDirection: "row", alignItems: "center", gap: 4 },
  val: { color: C.text, fontSize: 14, fontWeight: "800", minWidth: 56, textAlign: "center" },

  chips: { flexDirection: "row", flexWrap: "wrap", gap: 7 },
  chip: { paddingHorizontal: 13, paddingVertical: 7, borderRadius: 10, borderWidth: 1, borderColor: C.border2 },
  chipOn: { borderColor: C.green, backgroundColor: "rgba(47,212,138,.13)" },
  chipTxt: { color: C.muted, fontSize: 12, fontWeight: "700" },
});
