/** Logowanie i zakładanie konta.
 *
 *  Konto nie jest potrzebne do korzystania z aplikacji — służy do synchronizacji
 *  ustawień między urządzeniami i przypisania premium. Dlatego ekran da się zamknąć
 *  bez logowania i mówi wprost, po co to komu.
 *
 *  Układ od góry: logo z poświatą, przełącznik „Logowanie / Nowe konto" z
 *  przesuwanym wskaźnikiem, bilet z kodem twórcy (NAD przyciskiem Google, bo przy
 *  Google nie ma formularza), Google, e-mail i hasło. Na szerokim ekranie całość
 *  trzyma się kolumny 460 px — okno na webie rozlewa się na cały monitor.
 */
import { LinearGradient } from "expo-linear-gradient";
import React, { useEffect, useRef, useState } from "react";
import {
  ActivityIndicator, Animated, Easing, KeyboardAvoidingView, Modal, Platform, Pressable,
  ScrollView, StyleSheet, Text, TextInput, View,
} from "react-native";
import { useAuth } from "../auth/AuthContext";
import Svg, { Circle, Defs, RadialGradient, Stop } from "react-native-svg";
import { BrandLogo } from "../components/Brand";
import { useSvgId } from "../svgIds";
import ReferralCodeBox from "../components/ReferralCodeBox";
import { getPendingReferral } from "../referral";
import LegalScreen, { LegalSlug } from "./LegalScreen";
import { C, T } from "../theme";
import { Card, FadeIn, MetalButton } from "../ui";
import Icon from "../ui/Icon";

const ND = Platform.OS !== "web";

/** Miękka plama światła — gradient radialny w SVG, bo zwykły krąg z przezroczystością
 *  ma twardą krawędź, a rozmycia w React Native nie ma. */
function Plama({ size, color }: { size: number; color: string }) {
  const id = useSvgId("glow");
  return (
    <Svg width={size} height={size}>
      <Defs>
        <RadialGradient id={id} cx="50%" cy="50%" r="50%">
          <Stop offset="0" stopColor={color} stopOpacity={0.55} />
          <Stop offset="0.45" stopColor={color} stopOpacity={0.18} />
          <Stop offset="1" stopColor={color} stopOpacity={0} />
        </RadialGradient>
      </Defs>
      <Circle cx={size / 2} cy={size / 2} r={size / 2} fill={`url(#${id})`} />
    </Svg>
  );
}

/** Poświata za logo — dwie miękkie plamy w barwach marki, które powoli oddychają. */
function Glow() {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(a, { toValue: 1, duration: 2400, easing: Easing.inOut(Easing.sin), useNativeDriver: ND }),
      Animated.timing(a, { toValue: 0, duration: 2400, easing: Easing.inOut(Easing.sin), useNativeDriver: ND }),
    ]));
    loop.start();
    return () => loop.stop();
  }, []);
  return (
    <View pointerEvents="none" style={s.glowWrap}>
      <Animated.View style={[s.glowA, {
        opacity: a.interpolate({ inputRange: [0, 1], outputRange: [0.6, 1] }),
        transform: [{ scale: a.interpolate({ inputRange: [0, 1], outputRange: [0.95, 1.08] }) }],
      }]}>
        <Plama size={300} color={C.brandBlue} />
      </Animated.View>
      <Animated.View style={[s.glowB, {
        opacity: a.interpolate({ inputRange: [0, 1], outputRange: [0.9, 0.5] }),
        transform: [{ translateX: 40 }, { scale: a.interpolate({ inputRange: [0, 1], outputRange: [1.05, 0.95] }) }],
      }]}>
        <Plama size={180} color={C.brandOrange} />
      </Animated.View>
    </View>
  );
}

/** Przełącznik trybu z przesuwanym wskaźnikiem. */
function ModeSwitch({ up, onChange }: { up: boolean; onChange: (up: boolean) => void }) {
  const [w, setW] = useState(0);
  const x = useRef(new Animated.Value(up ? 1 : 0)).current;
  useEffect(() => {
    Animated.spring(x, { toValue: up ? 1 : 0, speed: 18, bounciness: 7, useNativeDriver: ND }).start();
  }, [up]);
  const half = Math.max(0, (w - 8) / 2);
  return (
    <View style={s.switch} onLayout={(e) => setW(e.nativeEvent.layout.width)}>
      {half > 0 && (
        <Animated.View style={[s.thumb, { width: half, transform: [{ translateX: x.interpolate({ inputRange: [0, 1], outputRange: [0, half], extrapolate: "clamp" }) }] }]}>
          <LinearGradient colors={["rgba(91,140,255,.35)", "rgba(91,140,255,.12)"]}
                          start={{ x: 0, y: 0 }} end={{ x: 0, y: 1 }} style={StyleSheet.absoluteFill} />
        </Animated.View>
      )}
      {[{ id: false, label: "Logowanie" }, { id: true, label: "Nowe konto" }].map((o) => (
        <Pressable key={o.label} style={s.switchBtn} onPress={() => onChange(o.id)}>
          <Text style={[s.switchTxt, up === o.id && s.switchOn]}>{o.label}</Text>
        </Pressable>
      ))}
    </View>
  );
}

/** Pole formularza z podświetleniem obwódki przy pisaniu. */
function Field({
  label, right, ...props
}: React.ComponentProps<typeof TextInput> & { label: string; right?: React.ReactNode }) {
  const [focus, setFocus] = useState(false);
  return (
    <>
      <Text style={[s.label, focus && { color: C.accent }]}>{label}</Text>
      <View style={[s.fieldWrap, focus && s.fieldFocus]}>
        <TextInput
          {...props}
          style={s.field}
          placeholderTextColor={C.dim}
          onFocus={(e) => { setFocus(true); props.onFocus?.(e); }}
          onBlur={(e) => { setFocus(false); props.onBlur?.(e); }}
        />
        {right}
      </View>
    </>
  );
}

const PERKS = ["Telefon i komputer na jednym koncie", "Portfel z raportu brokera", "Bez reklam"];

export default function AuthScreen({ onClose }: { onClose: () => void }) {
  const { signIn, signUp, signInGoogle, configured } = useAuth();
  const [mode, setMode] = useState<"in" | "up">("in");
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [info, setInfo] = useState("");
  const [legalSlug, setLegalSlug] = useState<LegalSlug | null>(null);

  const up = mode === "up";

  async function submit() {
    setErr(""); setInfo("");
    if (!email.trim() || !pass) { setErr("Podaj adres e-mail i hasło."); return; }
    setBusy(true);
    try {
      if (up) {
        const kod = await getPendingReferral();
        const logged = await signUp(email, pass, kod?.code);
        if (!logged) {
          setInfo("Konto założone. Potwierdź adres linkiem z maila i wróć tutaj się zalogować.");
          setMode("in");
          return;
        }
      } else {
        await signIn(email, pass);
      }
      onClose();
    } catch (e: any) {
      setErr(e?.message || "Nie udało się zalogować");
    } finally {
      setBusy(false);
    }
  }

  async function google() {
    setErr(""); setInfo("");
    setBusy(true);
    try {
      await signInGoogle();
      onClose();
    } catch (e: any) {
      setErr(e?.message || "Logowanie Google się nie powiodło");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}>
      <View style={s.root}>
        <View style={s.bar}>
          <Text style={s.barTitle}>KONTO PORTEVO</Text>
          <Pressable onPress={onClose} hitSlop={12} style={s.close}>
            <Icon name="zamknij" size={15} color={C.muted} />
          </Pressable>
        </View>

        <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined}>
          <ScrollView contentContainerStyle={s.wrap} keyboardShouldPersistTaps="handled"
                      showsVerticalScrollIndicator={false}>
            <View style={s.col}>
              {!configured ? (
                <FadeIn>
                  <Text style={s.h1}>Konta nie są jeszcze włączone</Text>
                  <Text style={s.sub}>
                    Ta wersja aplikacji nie ma wpisanych kluczy Supabase, więc logowanie jest
                    wyłączone. Wszystko poza kontem i premium działa normalnie.
                  </Text>
                  <Card style={{ marginTop: 20, padding: 16 }}>
                    <Text style={s.note}>
                      Do włączenia: uzupełnij <Text style={s.mono}>mobile/.env</Text> według
                      instrukcji w <Text style={s.mono}>keys/README.md</Text> i uruchom Expo
                      ponownie z <Text style={s.mono}>-c</Text>.
                    </Text>
                  </Card>
                </FadeIn>
              ) : (
                <>
                  <FadeIn>
                    <View style={s.hero}>
                      <Glow />
                      <BrandLogo width={150} />
                    </View>
                  </FadeIn>

                  {/* tytuł wjeżdża od nowa przy każdej zmianie trybu */}
                  <FadeIn key={mode} offset={8}>
                    <Text style={s.h1}>{up ? "Załóż darmowe konto" : "Witaj z powrotem"}</Text>
                    <Text style={s.sub}>
                      {up
                        ? "20 sekund i masz portfel, obserwowane i ustawienia na każdym urządzeniu."
                        : "Zaloguj się, żeby wrócić do swojego portfela i ustawień."}
                    </Text>
                  </FadeIn>

                  <FadeIn delay={60}>
                    <ModeSwitch up={up} onChange={(u) => { setMode(u ? "up" : "in"); setErr(""); setInfo(""); }} />

                    {up && (
                      <View style={s.perks}>
                        {PERKS.map((p) => (
                          <View key={p} style={s.perk}>
                            <Icon name="ptaszek" size={11} color={C.green} />
                            <Text style={s.perkTxt}>{p}</Text>
                          </View>
                        ))}
                      </View>
                    )}
                  </FadeIn>

                  <FadeIn delay={110}>
                    {/* Kod NAD przyciskiem Google: przy logowaniu przez Google nie ma
                        formularza, więc to jedyna chwila, żeby go podać. */}
                    <ReferralCodeBox place="signup" startOpen={up} />
                  </FadeIn>

                  <FadeIn delay={160}>
                    <MetalButton
                      label="Kontynuuj z Google" tone="blue" full liquid active
                      style={{ marginTop: 20 }} disabled={busy} onPress={google}
                    />

                    <View style={s.orRow}>
                      <View style={s.orLine} /><Text style={s.orTxt}>albo e-mailem</Text><View style={s.orLine} />
                    </View>

                    <Field
                      label="ADRES E-MAIL" value={email} onChangeText={setEmail}
                      placeholder="ty@example.com"
                      autoCapitalize="none" autoCorrect={false} keyboardType="email-address"
                      textContentType="emailAddress" editable={!busy}
                    />

                    <Field
                      label="HASŁO" value={pass} onChangeText={setPass}
                      placeholder={up ? "co najmniej 6 znaków" : "••••••••"}
                      secureTextEntry={!show} autoCapitalize="none"
                      textContentType={up ? "newPassword" : "password"} editable={!busy}
                      onSubmitEditing={submit} returnKeyType="go"
                      right={
                        <Pressable onPress={() => setShow((v) => !v)} hitSlop={8}>
                          <Text style={s.showTxt}>{show ? "Ukryj" : "Pokaż"}</Text>
                        </Pressable>
                      }
                    />

                    {!!err && <FadeIn offset={6}><Text style={s.err}>{err}</Text></FadeIn>}
                    {!!info && <FadeIn offset={6}><Text style={s.info}>{info}</Text></FadeIn>}

                    <MetalButton
                      label={up ? "Załóż konto" : "Zaloguj się"} tone="green" filled full
                      style={{ marginTop: 18 }} disabled={busy} onPress={submit}
                    />
                    {busy && <ActivityIndicator color={C.green} style={{ marginTop: 14 }} />}

                    {/* Zgody i Regulamin — wymóg App Store Review */}
                    <View style={{ marginTop: 20, alignItems: "center" }}>
                      <Text style={s.legalNote}>
                        {up ? "Zakładając konto" : "Logując się"}, akceptujesz{" "}
                        <Text style={s.legalLink} onPress={() => setLegalSlug("terms")}>Regulamin</Text>
                        {" "}oraz{" "}
                        <Text style={s.legalLink} onPress={() => setLegalSlug("privacy")}>Politykę prywatności</Text>.
                      </Text>
                    </View>
                  </FadeIn>
                </>
              )}

              <Pressable onPress={onClose} style={{ marginTop: 22 }} hitSlop={8}>
                <Text style={s.skip}>Później — korzystam bez konta</Text>
              </Pressable>
            </View>
          </ScrollView>
        </KeyboardAvoidingView>
      </View>
      {legalSlug && <LegalScreen slug={legalSlug} onClose={() => setLegalSlug(null)} />}
    </Modal>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg },
  bar: {
    flexDirection: "row", alignItems: "center", justifyContent: "space-between",
    paddingHorizontal: 18, paddingTop: 16, paddingBottom: 12,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  barTitle: { color: C.muted, ...T.micro },
  close: { width: 30, height: 30, alignItems: "center", justifyContent: "center" },

  wrap: { padding: 22, paddingBottom: 44 },
  col: { width: "100%", maxWidth: 460, alignSelf: "center" },

  hero: { alignItems: "center", justifyContent: "center", height: 120, marginBottom: 6 },
  glowWrap: { ...StyleSheet.absoluteFillObject, alignItems: "center", justifyContent: "center" },
  glowA: { position: "absolute", width: 300, height: 300 },
  glowB: { position: "absolute", width: 180, height: 180 },

  h1: { color: C.text, ...T.h1, fontSize: 25, textAlign: "center", marginTop: 6 },
  sub: { color: C.muted, ...T.small, lineHeight: 19, marginTop: 7, textAlign: "center" },

  switch: {
    flexDirection: "row", marginTop: 20, padding: 4, borderRadius: 14,
    backgroundColor: C.elev, borderWidth: 1, borderColor: C.border,
  },
  thumb: {
    position: "absolute", top: 4, bottom: 4, left: 4, borderRadius: 10, overflow: "hidden",
    borderWidth: 1, borderColor: "rgba(91,140,255,.55)",
  },
  switchBtn: { flex: 1, paddingVertical: 10, alignItems: "center" },
  switchTxt: { color: C.dim, fontSize: 13.5, fontWeight: "700" },
  switchOn: { color: C.text },

  perks: { flexDirection: "row", flexWrap: "wrap", justifyContent: "center", gap: 7, marginTop: 13 },
  perk: {
    flexDirection: "row", alignItems: "center", gap: 6, borderRadius: 999,
    paddingHorizontal: 10, paddingVertical: 5,
    backgroundColor: "rgba(47,212,138,.07)", borderWidth: 1, borderColor: "rgba(47,212,138,.25)",
  },
  perkTxt: { color: C.muted, fontSize: 11.3, fontWeight: "600" },

  orRow: { flexDirection: "row", alignItems: "center", gap: 12, marginTop: 22, marginBottom: 2 },
  orLine: { flex: 1, height: 1, backgroundColor: C.border },
  orTxt: { color: C.dim, fontSize: 11.5 },

  label: { color: C.dim, ...T.micro, marginTop: 16, marginBottom: 6 },
  fieldWrap: {
    flexDirection: "row", alignItems: "center", gap: 10,
    backgroundColor: C.elev, borderWidth: 1.5, borderColor: C.border, borderRadius: 13,
    paddingHorizontal: 14,
  },
  fieldFocus: { borderColor: "rgba(91,140,255,.75)", backgroundColor: "rgba(91,140,255,.05)" },
  field: {
    flex: 1, minWidth: 0, paddingVertical: 12, color: C.text, fontSize: 15,
    ...(Platform.OS === "web" ? { outlineStyle: "none" } as any : null),
  },
  showTxt: { color: C.accent, fontSize: 12.5, fontWeight: "700" },

  err: { color: C.red, ...T.small, marginTop: 14, lineHeight: 18 },
  info: { color: C.green, ...T.small, marginTop: 14, lineHeight: 18 },

  skip: { color: C.dim, ...T.small, textAlign: "center" },

  legalNote: { color: C.dim, fontSize: 11, textAlign: "center", lineHeight: 16 },
  legalLink: { color: C.accent, fontWeight: "600", textDecorationLine: "underline" },

  note: { color: C.muted, ...T.small, lineHeight: 20 },
  mono: { color: C.text, fontWeight: "700" },
});
