/** Wystąpienia na żywo — kafelek w Narzędziach otwierający pełny panel.
 *
 *  W Narzędziach zostaje sam podgląd stanu: czy dozór działa, czy coś leci
 *  teraz i co jest dziś w planie. Cała robota — kalendarz z akcjami, kanały,
 *  transkrypcja, ustawienia — mieszka w panelu na pełnym ekranie, bo w
 *  zwiniętej harmonijce nie da się tego sensownie obsłużyć.
 */
import React, { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { getLiveState, LiveState } from "../../api";
import { C, T } from "../../theme";
import { Card, FadeIn, LiquidButton } from "../../ui";
import { LivePanelModal } from "./live/LivePanel";

import Icon from "../../ui/Icon";
export default function LiveEvents() {
  const [st, setSt] = useState<LiveState | null>(null);
  const [err, setErr] = useState("");
  const [open, setOpen] = useState(false);

  const load = useCallback(async () => {
    try { setSt(await getLiveState()); setErr(""); }
    catch (e: any) { setErr(e?.message || "Nie udało się wczytać wydarzeń"); }
  }, []);

  useEffect(() => { load(); }, [load]);
  // po zamknięciu panelu stan mógł się zmienić (start sesji, nowe wydarzenia)
  useEffect(() => { if (!open) load(); }, [open, load]);

  if (err) {
    return (
      <Card style={s.msg}>
        <Text style={s.msgTxt}>{err}</Text>
        <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 200 }} onPress={load} />
      </Card>
    );
  }
  if (!st) return <View style={s.center}><ActivityIndicator color={C.green} /></View>;

  const monitorOn = Boolean(st.monitor?.running);
  const running = (st.sessions || []).filter((x) => x.running);
  const events = st.events || [];
  const liveNow = events.filter((e) => e.status === "live");
  const tracked = events.filter((e) => e.tracked).length;

  return (
    <View>
      <FadeIn>
        <Card style={s.card}>
          <View style={s.row}>
            <View style={[s.dot, { backgroundColor: monitorOn ? C.green : C.dim }]} />
            <Text style={s.status}>
              {monitorOn ? "Dozór włączony" : "Dozór wyłączony"}
            </Text>
            {!st.deps?.ready && (
              <View style={s.warnRow}>
                <Icon name="uwaga" size={11} color={C.amber} />
                <Text style={s.warn}>braki na komputerze</Text>
              </View>
            )}
          </View>

          <View style={s.stats}>
            <Stat v={String(events.length)} k="dziś w planie" />
            <Stat v={String(liveNow.length)} k="na antenie" color={liveNow.length ? C.red : undefined} />
            <Stat v={String(running.length)} k="słucham" color={running.length ? C.green : undefined} />
            <Stat v={String(tracked)} k="śledzonych" />
          </View>

          {running.length > 0 ? (
            <Text style={s.now} numberOfLines={2}>
              ● {running[0].event?.title || "trwa nasłuch"}
              {running.length > 1 ? `  (+${running.length - 1})` : ""}
            </Text>
          ) : liveNow.length > 0 ? (
            <Text style={s.now} numberOfLines={2}>
              Na antenie: {liveNow[0].title}
            </Text>
          ) : null}

          <LiquidButton label="Otwórz panel wystąpień" onPress={() => setOpen(true)}
                        style={{ marginTop: 14 }} />
        </Card>
      </FadeIn>

      <LivePanelModal visible={open} onClose={() => setOpen(false)} />
    </View>
  );
}

function Stat({ v, k, color }: { v: string; k: string; color?: string }) {
  return (
    <View style={s.stat}>
      <Text style={[s.statV, color ? { color } : null]}>{v}</Text>
      <Text style={s.statK}>{k}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  center: { paddingVertical: 30, alignItems: "center" },
  msg: { padding: 20, alignItems: "center" },
  msgTxt: { color: C.muted, fontSize: 13, marginBottom: 14, textAlign: "center" },

  card: { padding: 15 },
  row: { flexDirection: "row", alignItems: "center", gap: 8 },
  dot: { width: 8, height: 8, borderRadius: 4 },
  status: { color: C.text, fontSize: 13.5, fontWeight: "700" },
  warnRow: { flexDirection: "row", alignItems: "center", gap: 5, marginLeft: "auto" },
  warn: { color: C.amber, fontSize: 11 },

  stats: { flexDirection: "row", marginTop: 16 },
  stat: { flex: 1, alignItems: "center" },
  statV: { color: C.text, fontSize: 19, fontWeight: "800" },
  statK: { color: C.dim, fontSize: 10, marginTop: 3 },

  now: { color: C.muted, fontSize: 12, lineHeight: 17, marginTop: 14 },
});
