/** Twoje dywidendy — ile realnie płynie z wgranego portfela i czego mu brakuje.
 *
 *  Najbardziej osobista część narzędzia i jedyna, która nie ma sensu bez konta:
 *  liczy na pozycjach z raportu maklerskiego. Yield on cost porównuje wypłatę
 *  z tym, co REALNIE wydałeś, a nie z dzisiejszą wyceną — i to jest liczba,
 *  której nie pokaże żadna tabela w internecie, bo nikt poza Tobą nie zna
 *  Twojej ceny zakupu.
 */
import React, { useEffect, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from "react-native";
import {
  DywDopasowanie, DywPortfel, getDywDopasowanie, getDywPortfel,
} from "../../../api";
import { C, T } from "../../../theme";
import { Card } from "../../../ui";
import {
  Akapit, Kafel, OdznakaOceny, pln, proc, Wyjasnienie, zaIleDni, Znak, ZnacznikRynku,
} from "./shared";

export default function Portfel({ naAktywo }: { naAktywo: (symbol: string) => void }) {
  const [dane, setDane] = useState<DywPortfel | null>(null);
  const [fit, setFit] = useState<DywDopasowanie | null>(null);
  const [laduje, setLaduje] = useState(true);
  const [blad, setBlad] = useState("");

  useEffect(() => {
    let zywy = true;
    Promise.all([getDywPortfel(), getDywDopasowanie(8).catch(() => null)])
      .then(([p, d]) => { if (zywy) { setDane(p); setFit(d); } })
      .catch((e) => { if (zywy) setBlad(e?.message || "Nie udało się policzyć portfela"); })
      .finally(() => { if (zywy) setLaduje(false); });
    return () => { zywy = false; };
  }, []);

  if (laduje) return <ActivityIndicator color={C.green} style={{ marginVertical: 24 }} />;
  if (blad) return <Text style={st.blad}>{blad}</Text>;

  if (!dane || dane.empty) {
    return (
      <Card>
        <Text style={st.tytul}>Najpierw wgraj raport maklerski</Text>
        <Akapit>
          Ta zakładka liczy na Twoich realnych pozycjach — bez nich nie ma czego
          liczyć. Wgraj raport z biura maklerskiego na Przeglądzie, a wrócisz tu
          po komplet: ile dywidend rocznie płynie z tego, co masz, ile z tego
          zostaje po podatku i ile procent Twoich własnych pieniędzy to daje.
        </Akapit>
      </Card>
    );
  }

  const p = dane.podsumowanie;

  return (
    <View style={{ gap: 12 }}>
      <View style={st.kafle}>
        <Kafel etykieta="Rocznie po podatku" wartosc={pln(p.rocznie_netto)}
               nota={`brutto ${pln(p.rocznie_brutto)}`} kolor={C.green} />
        <Kafel etykieta="Miesięcznie" wartosc={pln(p.miesiecznie_netto)}
               nota="średnio, po podatku" />
        <Kafel etykieta="Yield on cost" wartosc={proc(p.yield_on_cost)}
               nota="względem tego, co wydałeś" kolor={C.accent} />
        <Kafel etykieta="Stopa portfela" wartosc={proc(p.stopa_portfela)}
               nota={`${p.udzial_placacych_pct}% portfela płaci`} />
      </View>

      {p.pozycji_bez > 0 && (
        <Card>
          <Text style={st.podtytul}>
            {p.pozycji_placacych} z {p.pozycji_placacych + p.pozycji_bez} pozycji
            płaci dywidendę. Pozostałe{" "}
            {p.pozycji_bez === 1 ? "nie wypłaca" : "nie wypłacają"} jej wcale —
            to nie jest wada, wiele dobrych spółek woli reinwestować cały zysk
            w siebie zamiast oddawać go akcjonariuszom.
          </Text>
        </Card>
      )}

      {dane.najblizsze_wyplaty.length > 0 && (
        <Card>
          <Text style={st.tytul}>Najbliższe dni bez dywidendy w Twoim portfelu</Text>
          <Text style={st.podtytul}>
            Akcje trzeba mieć na koniec sesji poprzedzającej tę datę
          </Text>
          <View style={{ gap: 8, marginTop: 10 }}>
            {dane.najblizsze_wyplaty.map((x) => (
              <View key={x.symbol} style={st.mini}>
                <Text style={st.miniNazwa} numberOfLines={1}>{x.nazwa}</Text>
                <Text style={st.miniData}>{zaIleDni(x.dni_do_ex)}</Text>
                <Text style={st.miniKwota}>{pln(x.rocznie_netto)}/rok</Text>
              </View>
            ))}
          </View>
        </Card>
      )}

      <Card>
        <Text style={st.tytul}>Skąd płyną Twoje dywidendy</Text>
        <View style={{ gap: 9, marginTop: 11 }}>
          {dane.pozycje.map((x) => {
            const udzial = p.rocznie_brutto
              ? (x.rocznie_brutto / p.rocznie_brutto) * 100 : 0;
            return (
              <Pressable key={x.symbol} onPress={() => naAktywo(x.symbol)} style={st.poz}>
                  <Znak symbol={x.symbol} nazwa={x.nazwa} rozmiar={32} />
                  <View style={{ flex: 1, gap: 4 }}>
                  <View style={{ flexDirection: "row", alignItems: "center", gap: 7 }}>
                    <Text style={st.nazwa} numberOfLines={1}>{x.nazwa}</Text>
                    <ZnacznikRynku rynek={x.rynek} />
                  </View>
                  <Text style={st.pod}>
                    {pln(x.wartosc)} · {proc(x.stopa)} · {x.czestotliwosc_pl}
                  </Text>
                  <View style={st.pasekTlo}>
                    <View style={[st.pasek, { width: `${Math.min(100, udzial)}%` }]} />
                  </View>
                </View>
                <View style={{ alignItems: "flex-end", gap: 3 }}>
                  <Text style={st.kwotaRok}>{pln(x.rocznie_netto)}</Text>
                  <Text style={st.pod}>rocznie netto</Text>
                  {x.yield_on_cost !== null && (
                    <Text style={st.yoc}>YoC {proc(x.yield_on_cost)}</Text>
                  )}
                  <OdznakaOceny ocena={x.ocena} poziom={x.poziom} male />
                </View>
              </Pressable>
            );
          })}
        </View>

        <Wyjasnienie tytul="Dlaczego yield on cost różni się od stopy w tabeli">
          <Akapit>
            Stopa dywidendy w każdej tabeli liczy się od dzisiejszego kursu.
            Yield on cost liczymy od tego, co realnie zapłaciłeś — czyli od
            kwoty z Twojego raportu maklerskiego. Jeśli spółka od czasu zakupu
            urosła i podnosiła wypłatę, Twoja liczba będzie wyższa niż ta
            publiczna. Jeśli dokupywałeś drożej, będzie niższa.
          </Akapit>
        </Wyjasnienie>
      </Card>

      {fit && !fit.empty && (
        <>
          {fit.ostrzezenia.length > 0 && (
            <Card>
              <Text style={st.tytul}>Na co uważać</Text>
              <View style={{ gap: 9, marginTop: 9 }}>
                {fit.ostrzezenia.map((o, i) => (
                  <View key={i} style={st.ostrz}>
                    <Text style={st.ostrzTxt}>{o}</Text>
                  </View>
                ))}
              </View>
            </Card>
          )}

          <Card>
            <Text style={st.tytul}>Z czego składa się Twój dochód</Text>
            <View style={{ gap: 7, marginTop: 10 }}>
              {fit.udzial_branz.slice(0, 7).map((b) => (
                <View key={b.branza} style={st.branza}>
                  <Text style={st.branzaNazwa} numberOfLines={1}>{b.branza || "inne"}</Text>
                  <View style={st.pasekTlo}>
                    <View style={[st.pasek, { width: `${Math.min(100, b.udzial)}%`,
                                              backgroundColor: C.accent }]} />
                  </View>
                  <Text style={st.branzaProc}>{b.udzial.toFixed(0)}%</Text>
                </View>
              ))}
            </View>
          </Card>

          <Card>
            <Text style={st.tytul}>Czego brakuje</Text>
            <Text style={st.podtytul}>{fit.metoda}</Text>
            <View style={{ gap: 9, marginTop: 11 }}>
              {fit.propozycje.map((x) => (
                <Pressable key={x.symbol} onPress={() => naAktywo(x.symbol)} style={st.poz}>
                  <Znak symbol={x.symbol} nazwa={x.nazwa} rozmiar={32} />
                  <View style={{ flex: 1, gap: 3 }}>
                    <View style={{ flexDirection: "row", alignItems: "center", gap: 7 }}>
                      <Text style={st.nazwa} numberOfLines={1}>{x.nazwa}</Text>
                      <ZnacznikRynku rynek={x.rynek} />
                    </View>
                    <Text style={st.pod} numberOfLines={2}>{x.powod}</Text>
                  </View>
                  <View style={{ alignItems: "flex-end", gap: 4 }}>
                    <Text style={st.kwotaRok}>{proc(x.stopa)}</Text>
                    <OdznakaOceny ocena={x.ocena} poziom={x.poziom} male />
                  </View>
                </Pressable>
              ))}
            </View>

            <Wyjasnienie tytul="Dlaczego jedna branża to za mało, nawet przy dziesięciu spółkach">
              <Akapit>
                Dywidendy z jednej branży wysychają razem. W 2020 roku polskie
                banki obcięły je jednocześnie, bo tak zdecydował nadzór — nie
                każdy bank z osobna po analizie własnych wyników. Portfel złożony
                z pięciu banków zachował się wtedy jak portfel złożony z jednego.
              </Akapit>
              <Akapit>
                Dlatego przy dochodzie z dywidend rozrzut po branżach znaczy
                więcej niż sama liczba pozycji. Zmierzoną korelację tego, co już
                masz, pokazuje osobne narzędzie: Mapa korelacji.
              </Akapit>
            </Wyjasnienie>
          </Card>
        </>
      )}
    </View>
  );
}

const st = StyleSheet.create({
  blad: { ...T.small, color: C.red },
  tytul: { ...T.body, color: C.text, fontWeight: "700" },
  podtytul: { ...T.micro, color: C.dim, marginTop: 3, lineHeight: 16 },
  kafle: { flexDirection: "row", flexWrap: "wrap", gap: 9 },
  poz: {
    flexDirection: "row", gap: 11, alignItems: "center",
    borderTopWidth: 1, borderTopColor: C.border, paddingTop: 10,
  },
  nazwa: { ...T.small, color: C.text, fontWeight: "700", flexShrink: 1 },
  pod: { ...T.micro, color: C.dim, lineHeight: 15 },
  kwotaRok: { ...T.body, color: C.green, fontSize: 15, fontWeight: "800" },
  yoc: { ...T.micro, color: C.accent, fontSize: 10 },
  pasekTlo: { height: 4, backgroundColor: C.border, borderRadius: 2, overflow: "hidden", flex: 1 },
  pasek: { height: 4, backgroundColor: C.green, borderRadius: 2 },
  mini: { flexDirection: "row", alignItems: "center", gap: 10 },
  miniNazwa: { ...T.small, color: C.text, flex: 1 },
  miniData: { ...T.micro, color: C.accent },
  miniKwota: { ...T.body, color: C.green, fontSize: 12 },
  ostrz: {
    backgroundColor: "rgba(255,180,84,.09)", borderLeftWidth: 3,
    borderLeftColor: C.amber, borderRadius: 8, padding: 11,
  },
  ostrzTxt: { ...T.small, color: C.muted, lineHeight: 19 },
  branza: { flexDirection: "row", alignItems: "center", gap: 10 },
  branzaNazwa: { ...T.micro, color: C.muted, width: 96 },
  branzaProc: { ...T.body, color: C.text, fontSize: 12, width: 38, textAlign: "right" },
});
