/** Wystąpienia na żywo — pełnoekranowy panel.
 *
 *  Zastępuje dawną stronę /live z panelu webowego i ma wszystko, co ona miała:
 *  kalendarz wydarzeń z akcjami, monitorowane kanały YouTube, aktywne sesje
 *  z transkrypcją oraz ustawienia nasłuchu.
 *
 *  Podział pracy: cały ciężar (pobieranie audio, whisper, model) leży na
 *  komputerze. Panel jest pilotem — pokazuje stan i wysyła polecenia.
 *
 *  Odświeżanie jest dwutorowe, bo dane mają różne tempo: stan ogólny co 15 s,
 *  a transkrypcja aktywnych sesji co 3 s (inaczej tekst „doganiałby" mówcę
 *  z kilkunastosekundowym opóźnieniem).
 */
import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  ActivityIndicator, Alert, Modal, Platform, Pressable, ScrollView,
  StyleSheet, Text, View,
} from "react-native";
import { getLiveState, LiveState } from "../../../api";
import { C, T } from "../../../theme";
import { LiquidButton, Segmented } from "../../../ui";
import ChannelsTab from "./ChannelsTab";
import { todayISO } from "./dates";
import EventsTab from "./EventsTab";
import SessionsTab from "./SessionsTab";
import SettingsTab from "./SettingsTab";

import Icon from "../../../ui/Icon";
const TABS = [
  { id: "events", label: "Kalendarz" },
  { id: "sessions", label: "Na żywo" },
  { id: "channels", label: "Kanały" },
  { id: "settings", label: "Ustawienia" },
];

export default function LivePanel({ onClose }: { onClose: () => void }) {
  const [tab, setTab] = useState("events");
  const [date, setDate] = useState(todayISO());
  const [st, setSt] = useState<LiveState | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState("");

  const load = useCallback(async (d?: string) => {
    try { setSt(await getLiveState(d ?? date)); setErr(""); }
    catch (e: any) { setErr(e?.message || "Nie udało się wczytać danych"); }
  }, [date]);

  useEffect(() => { load(); }, [load]);

  // stan ogólny odświeżamy rzadko; transkrypcję ciągnie SessionsTab własnym rytmem
  useEffect(() => {
    const t = setInterval(() => load(), 15000);
    return () => clearInterval(t);
  }, [load]);

  /** Wspólne opakowanie akcji: blokada przycisku, odświeżenie, czytelny błąd. */
  const act = useCallback(async (label: string, fn: () => Promise<any>) => {
    setBusy(label);
    try {
      const r = await fn();
      await load();
      return r;
    } catch (e: any) {
      Alert.alert("Nie udało się", e?.message || "Błąd połączenia");
      return null;
    } finally { setBusy(""); }
  }, [load]);

  const liveNow = (st?.sessions || []).filter((s) => s.running).length;
  const monitorOn = Boolean(st?.monitor?.running);

  return (
    <View style={s.wrap}>
      {/* ---------------- nagłówek ---------------- */}
      <View style={s.head}>
        <Pressable onPress={onClose} hitSlop={14} style={s.closeBtn}>
          <Icon name="zamknij" size={15} color={C.muted} />
        </Pressable>
        <View style={{ flex: 1 }}>
          <Text style={s.title}>Wystąpienia na żywo</Text>
          <View style={s.headMeta}>
            <View style={[s.dot, { backgroundColor: monitorOn ? C.green : C.dim }]} />
            <Text style={s.headMetaTxt}>
              {monitorOn ? "dozór włączony" : "dozór wyłączony"}
              {liveNow > 0 ? `  ·  ${liveNow} na żywo` : ""}
            </Text>
          </View>
        </View>
      </View>

      <View style={s.tabs}>
        <Segmented options={TABS} value={tab} onChange={setTab} tone="green" />
      </View>

      {err && !st ? (
        <View style={s.center}>
          <Text style={s.err}>{err}</Text>
          <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 200 }}
                        onPress={() => load()} />
        </View>
      ) : !st ? (
        <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>
      ) : (
        <ScrollView style={{ flex: 1 }} contentContainerStyle={s.body}
                    keyboardShouldPersistTaps="handled">
          {tab === "events" && (
            <EventsTab st={st} date={date} busy={busy} act={act}
                       onDate={(d) => { setDate(d); load(d); }} />
          )}
          {tab === "sessions" && <SessionsTab st={st} busy={busy} act={act} />}
          {tab === "channels" && <ChannelsTab st={st} busy={busy} act={act} />}
          {tab === "settings" && <SettingsTab st={st} busy={busy} act={act} />}
        </ScrollView>
      )}

      <Text style={s.disclaimer}>
        Transkrypcja powstaje automatycznie i bywa niedokładna. Materiał informacyjny —
        nie stanowi porady inwestycyjnej.
      </Text>
    </View>
  );
}

/** Otwiera panel na pełnym ekranie. */
export function LivePanelModal({
  visible, onClose,
}: { visible: boolean; onClose: () => void }) {
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}
           presentationStyle={Platform.OS === "ios" ? "fullScreen" : undefined}>
      <LivePanel onClose={onClose} />
    </Modal>
  );
}

const s = StyleSheet.create({
  wrap: { flex: 1, backgroundColor: C.bg },
  head: {
    flexDirection: "row", alignItems: "center", gap: 12,
    paddingTop: Platform.OS === "web" ? 18 : 54, paddingHorizontal: 16, paddingBottom: 10,
  },
  closeBtn: { padding: 4 },
  close: { color: C.muted, fontSize: 20 },
  title: { color: C.text, ...T.h1 },
  headMeta: { flexDirection: "row", alignItems: "center", gap: 7, marginTop: 4 },
  dot: { width: 7, height: 7, borderRadius: 4 },
  headMetaTxt: { color: C.muted, fontSize: 11.5 },

  tabs: { paddingHorizontal: 16, paddingBottom: 6 },
  body: { padding: 16, paddingBottom: 40 },
  center: { flex: 1, alignItems: "center", justifyContent: "center", padding: 24, gap: 14 },
  err: { color: C.red, fontSize: 13, textAlign: "center" },
  disclaimer: {
    color: C.dim, fontSize: 10, lineHeight: 14, paddingHorizontal: 16, paddingVertical: 8,
    borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: C.border,
  },
});
