/** Zakładka Bot / Earnings — jeden przycisk na pasku, dwie niezależne sekcje.
 *
 *  Bot newsowy i kalendarz wyników robią zupełnie co innego, ale oba dotyczą
 *  „co się dzisiaj wydarzy na rynku", więc dzielą miejsce na dolnym pasku.
 *  Przełącznik u góry decyduje, którą sekcję widać; wybór zapamiętujemy na telefonie,
 *  a domyślnie otwiera się **Earnings** — z bota korzysta się rzadziej i świadomie.
 *
 *  Ekrany zostają zamontowane po pierwszym wejściu (`Pane`), więc przeskakiwanie
 *  między nimi nie kasuje pobranych danych ani pozycji przewinięcia.
 */
import React, { useEffect, useState } from "react";
import { StyleSheet, View } from "react-native";
import { C } from "../theme";
import { ErrorBoundary, Segmented } from "../ui";
import BotScreen from "./BotScreen";
import EarningsScreen from "./earnings/EarningsScreen";

export type HubSection = "bot" | "earnings";

export const HUB_SECTIONS = [
  { id: "bot", label: "Bot" },
  { id: "earnings", label: "Earnings" },
];

export default function HubScreen({
  section, onSection, visible,
}: { section: HubSection; onSection: (s: HubSection) => void; visible: boolean }) {
  return (
    <View style={{ flex: 1 }}>
      <View style={s.switch}>
        <Segmented options={HUB_SECTIONS} value={section}
                   onChange={(v) => onSection(v as HubSection)} tone="green" liquid />
      </View>
      <View style={{ flex: 1 }}>
        {/* osobne bezpieczniki: gdy padnie kalendarz, przełącznik i bot nadal działają */}
        <Pane visible={section === "earnings"}>
          <ErrorBoundary name="Earnings">
            <EarningsScreen visible={visible && section === "earnings"} />
          </ErrorBoundary>
        </Pane>
        <Pane visible={section === "bot"}>
          <ErrorBoundary name="Bot newsów">
            <BotScreen />
          </ErrorBoundary>
        </Pane>
      </View>
    </View>
  );
}

function Pane({ visible, children }: { visible: boolean; children: React.ReactNode }) {
  const [everShown, setEverShown] = useState(visible);
  useEffect(() => { if (visible) setEverShown(true); }, [visible]);
  if (!everShown) return null;
  return (
    <View style={[StyleSheet.absoluteFill, !visible && s.hidden]}
          pointerEvents={visible ? "auto" : "none"}>
      {children}
    </View>
  );
}

const s = StyleSheet.create({
  switch: {
    paddingHorizontal: 18, paddingTop: 10, paddingBottom: 8,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  hidden: { opacity: 0, zIndex: -1 },
});
