/** Pierścieniowy wykres alokacji — rysuje się animowanym „zamachem" i reaguje na dotyk. */
import React, { useEffect, useRef, useState } from "react";
import { Animated, Easing, StyleSheet, Text, View } from "react-native";
import Svg, { Circle, G, Path } from "react-native-svg";
import { C, chartColor, fmtPLN } from "../theme";

export type Slice = { label: string; value: number; pct: number };

const polar = (cx: number, cy: number, r: number, deg: number) => {
  const rad = ((deg - 90) * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
};

/** Wycinek pierścienia jako ścieżka SVG (łuk zewnętrzny + wewnętrzny). */
function arc(cx: number, cy: number, rOut: number, rIn: number, from: number, to: number) {
  const sweep = to - from;
  if (sweep <= 0.01) return "";
  if (sweep >= 359.99) {
    // pełne koło trzeba złożyć z dwóch półłuków — inaczej SVG nic nie narysuje
    return `M${cx - rOut},${cy}A${rOut},${rOut} 0 1 1 ${cx + rOut},${cy}A${rOut},${rOut} 0 1 1 ${cx - rOut},${cy}` +
           `M${cx - rIn},${cy}A${rIn},${rIn} 0 1 0 ${cx + rIn},${cy}A${rIn},${rIn} 0 1 0 ${cx - rIn},${cy}`;
  }
  const p1 = polar(cx, cy, rOut, to);
  const p2 = polar(cx, cy, rOut, from);
  const p3 = polar(cx, cy, rIn, from);
  const p4 = polar(cx, cy, rIn, to);
  const big = sweep > 180 ? 1 : 0;
  return `M${p1.x},${p1.y}A${rOut},${rOut} 0 ${big} 0 ${p2.x},${p2.y}` +
         `L${p3.x},${p3.y}A${rIn},${rIn} 0 ${big} 1 ${p4.x},${p4.y}Z`;
}

export default function Donut({
  slices, size = 200, thickness = 26, selected, onSelect, centerLabel, centerValue,
  fmt = fmtPLN, pctOf = "portfela",
}: {
  slices: Slice[];
  size?: number;
  thickness?: number;
  selected?: number | null;
  onSelect?: (i: number | null) => void;
  centerLabel?: string;
  centerValue?: string;
  /** format kwot — domyślnie złotówki; zakupy insiderów są w dolarach */
  fmt?: (v: number) => string;
  /** „12% portfela" — czego ułamkiem jest zaznaczony wycinek */
  pctOf?: string;
}) {
  const [t, setT] = useState(0);
  const anim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    anim.setValue(0);
    const id = anim.addListener(({ value }) => setT(value));
    Animated.timing(anim, {
      toValue: 1, duration: 900, easing: Easing.bezier(0.22, 1, 0.36, 1), useNativeDriver: false,
    }).start();
    return () => anim.removeListener(id);
  }, [slices.map((s) => s.label + s.value).join("|")]);

  const cx = size / 2;
  const cy = size / 2;
  const total = slices.reduce((a, b) => a + b.value, 0) || 1;

  let acc = 0;
  const paths = slices.map((sl, i) => {
    const from = (acc / total) * 360;
    acc += sl.value;
    const to = (acc / total) * 360;
    const isSel = selected === i;
    const grow = isSel ? 3 : 0;
    const gap = slices.length > 1 ? 1.1 : 0;    // delikatna przerwa między wycinkami
    return {
      d: arc(cx, cy, (size / 2 - 2) + grow, (size / 2 - 2 - thickness) + grow,
             Math.min(from + gap, to), to * t + from * (1 - t)),
      color: chartColor(i),
      dim: selected != null && !isSel,
    };
  });

  const sel = selected != null ? slices[selected] : null;

  return (
    <View style={{ width: size, height: size, alignSelf: "center" }}>
      <Svg width={size} height={size}>
        <Circle cx={cx} cy={cy} r={size / 2 - 2 - thickness / 2} stroke="rgba(255,255,255,.035)"
                strokeWidth={thickness} fill="none" />
        <G>
          {paths.map((p, i) => (
            <Path key={i} d={p.d} fill={p.color} opacity={p.dim ? 0.28 : 1}
                  onPress={() => onSelect?.(selected === i ? null : i)} />
          ))}
        </G>
      </Svg>

      <View style={[StyleSheet.absoluteFill, st.center]} pointerEvents="none">
        <Text style={st.centerLabel} numberOfLines={1}>
          {sel ? sel.label : centerLabel || "Razem"}
        </Text>
        <Text style={st.centerValue} numberOfLines={1}>
          {sel ? fmt(sel.value) : centerValue || fmt(total)}
        </Text>
        {!!sel && (
          <Text style={st.centerPct}>
            {sel.pct.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}% {pctOf}
          </Text>
        )}
      </View>
    </View>
  );
}

const st = StyleSheet.create({
  center: {
    alignItems: "center", justifyContent: "center",
    paddingHorizontal: 42,
  },
  centerLabel: {
    color: C.muted, fontSize: 11, fontWeight: "700", letterSpacing: 0.7,
    textTransform: "uppercase", textAlign: "center",
  },
  centerValue: {
    color: C.text, fontSize: 19, fontWeight: "800", marginTop: 3, textAlign: "center",
    letterSpacing: -0.4,
  },
  centerPct: { color: C.dim, fontSize: 11.5, marginTop: 2 },
});
