/** Nawigacja główna — animowana kropka pod aktywną zakładką i płynne przejście koloru.
 *
 *  Dwa układy z jednego kodu. Na telefonie pasek jest zaokrągloną wyspą unoszącą
 *  się nad treścią przy dolnej krawędzi, w zasięgu kciuka — przewijana zawartość
 *  przechodzi pod nim, więc widać, że ekran się nie kończy.
 *  Na komputerze kciuka nie ma, za to jest mnóstwo szerokości i mało wysokości —
 *  tam zakładki rozciągnięte na metr wyglądają jak błąd, więc pasek staje
 *  pionowo przy lewej krawędzi i wreszcie mieści pełne podpisy.
 *
 *  Dwie zakładki są WYŁĄCZNIE dla przeglądarki („Artykuły" i „Aplikacja") i na
 *  telefonie nie pojawiają się w ogóle. Powód jest ten sam dla obu: mówią
 *  o rzeczach, które istnieją tylko poza aplikacją mobilną. Spis podstron
 *  pozycjonowanych jest treścią dla Google, a zaproszenie do pobrania aplikacji
 *  na telefon czytane NA telefonie byłoby zaproszeniem do miejsca, w którym
 *  użytkownik już stoi.
 *
 *  Odwrotnie działa „Premium": WYŁĄCZNIE na telefonie. W przeglądarce sprzedaż
 *  premium prowadzi złota zakładka „Aplikacja" (jest tam segment z cennikiem),
 *  więc druga zakładka o tym samym była dublem i dwiema złotymi poświatami
 *  walczącymi o wzrok w jednym pasku.
 */
import * as Haptics from "expo-haptics";
import { LinearGradient } from "expo-linear-gradient";
import React, { useEffect, useRef } from "react";
import { Animated, Easing, Platform, Pressable, StyleSheet, Text, View } from "react-native";
import { SIDEBAR_W } from "../layout";
import { C } from "../theme";
import Icon, { IconName } from "../ui/Icon";

export type TabId =
  | "overview" | "allocation" | "history" | "bot" | "tools" | "premium" | "more" | "pages" | "app";

type Zakladka = {
  id: TabId;
  label: string;
  /** krótszy podpis na dolny pasek, gdzie na zakładkę wypada kilkadziesiąt pikseli */
  short?: string;
  icon: IconName;
  /** nie pokazuj na telefonie */
  webOnly?: boolean;
  /** nie pokazuj w przeglądarce (na webie sprzedaje zakładka „Aplikacja") */
  mobileOnly?: boolean;
  /** złota poświata przyciągająca wzrok — dokładnie jedna zakładka w apce */
  glow?: boolean;
  /** własny kolor zakładki, niezależny od tego, czy jest aktywna */
  tint?: string;
};

export const TABS: Zakladka[] = [
  { id: "overview", label: "Przegląd", icon: "przeglad" },
  { id: "allocation", label: "Alokacja", icon: "alokacja" },
  { id: "history", label: "Zamknięte", icon: "zamkniete" },
  { id: "bot", label: "Earnings", icon: "earnings" },
  { id: "tools", label: "Narzędzia", icon: "narzedzia" },
  { id: "premium", label: "Premium", icon: "premium", glow: true, mobileOnly: true },
  { id: "pages", label: "Artykuły", icon: "artykuly", webOnly: true },
  { id: "more", label: "Więcej", icon: "wiecej" },
  { id: "app", label: "Aplikacja", short: "Apka", icon: "aplikacja", webOnly: true, glow: true },
];

/** Zakładki widoczne na tym urządzeniu. */
export const widoczneTabs = (): Zakladka[] =>
  TABS.filter((t) => (!t.webOnly || Platform.OS === "web")
                     && (!t.mobileOnly || Platform.OS !== "web"));

export default function TabBar({
  active, onChange, labels, vertical = false,
}: {
  active: TabId; onChange: (t: TabId) => void;
  /** nadpisanie podpisu — zakładka Bot/Earnings pokazuje aktywną sekcję */
  labels?: Partial<Record<TabId, string>>;
  /** układ komputerowy: pionowy pasek przy lewej krawędzi */
  vertical?: boolean;
}) {
  const tabs = widoczneTabs();
  return (
    <View style={vertical ? s.side : s.bar}>
      {tabs.map((t) => (
        <Tab key={t.id} tab={{ ...t, label: labels?.[t.id] || t.label }} vertical={vertical}
             active={active === t.id} onPress={() => onChange(t.id)} />
      ))}
    </View>
  );
}

/** Pulsowanie złotej poświaty — wolne i nieprzerwane, żeby zwracało uwagę bez
 *  szarpania wzrokiem przy każdym spojrzeniu na pasek.
 *
 *  Zwracana wartość jedzie 0 → 1 w kółko, a odbicie („rozjaśnij i przygaś")
 *  robi się dopiero w interpolacji, przez punkt pośredni 0,5 — jedno `timing`
 *  w pętli zamiast sekwencji dwóch.
 *
 *  Uwaga przy sprawdzaniu tego na oko: w przeglądarce animacje `Animated` jadą
 *  na `requestAnimationFrame` (na webie nie ma sterownika natywnego, o czym
 *  konsola uprzejmie informuje). W karcie, która nie jest na wierzchu,
 *  `requestAnimationFrame` w ogóle nie tyka, więc poświata stoi zamrożona na
 *  wartości początkowej. To nie jest usterka tego kodu — wystarczy spojrzeć na
 *  widoczną kartę.
 */
function usePuls(wlaczony: boolean) {
  const puls = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (!wlaczony) return;
    const petla = Animated.loop(
      Animated.timing(puls, {
        toValue: 1, duration: 2800, easing: Easing.inOut(Easing.quad), useNativeDriver: true,
      }),
    );
    petla.start();
    // Pętla żyje dalej po odmontowaniu i dobija się do zdjętego widoku —
    // na webie kończy się to ostrzeżeniami w konsoli przy każdym przeładowaniu.
    return () => petla.stop();
  }, [wlaczony]);
  return puls;
}

/** Wartość pulsu odbita: 0 → maks → 0, żeby poświata gasła i wracała. */
const odbij = (puls: Animated.Value, min: number, maks: number) =>
  puls.interpolate({ inputRange: [0, 0.5, 1], outputRange: [min, maks, min] });

function Tab({
  tab, active, onPress, vertical,
}: { tab: Zakladka; active: boolean; onPress: () => void; vertical: boolean }) {
  const a = useRef(new Animated.Value(active ? 1 : 0)).current;
  const puls = usePuls(Boolean(tab.glow));

  useEffect(() => {
    Animated.spring(a, {
      toValue: active ? 1 : 0, useNativeDriver: true, speed: 18, bounciness: 8,
    }).start();
  }, [active]);

  const press = () => {
    if (Platform.OS !== "web") Haptics.selectionAsync().catch(() => {});
    onPress();
  };

  const zloty = Boolean(tab.glow);
  const kolorIkony = tab.tint || (zloty ? C.gold : active ? C.green : C.dim);
  const kolorPodpisu = tab.tint || (zloty ? C.gold : active ? C.text : C.dim);

  // Poświata: miękka plama pod ikoną, oddychająca skalą i przezroczystością.
  const poswiata = zloty ? (
    <Animated.View
      pointerEvents="none"
      style={[
        s.glow,
        {
          opacity: odbij(puls, 0.28, 0.85),
          transform: [{ scale: odbij(puls, 0.85, 1.15) }],
        },
      ]}
    >
      <LinearGradient
        colors={["rgba(255,210,74,.55)", "rgba(255,210,74,.16)", "rgba(255,210,74,0)"]}
        start={{ x: 0.5, y: 0 }} end={{ x: 0.5, y: 1 }}
        style={StyleSheet.absoluteFill as any}
      />
    </Animated.View>
  ) : null;

  // pozioma pozycja na liście: ikona po lewej, podpis obok, aktywną pozycję
  // podkreśla belka przy krawędzi — kropka pod podpisem nie miałaby tu sensu
  if (vertical) {
    return (
      <Pressable style={[s.sideTab, active && s.sideTabOn, zloty && s.sideTabGold]} onPress={press}>
        {zloty && (
          <Animated.View
            pointerEvents="none"
            style={[
              StyleSheet.absoluteFill,
              s.sideGlow,
              { opacity: odbij(puls, 0.25, 0.75) },
            ]}
          >
            <LinearGradient
              colors={["rgba(255,210,74,.22)", "rgba(200,137,32,.06)"]}
              start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
              style={StyleSheet.absoluteFill as any}
            />
          </Animated.View>
        )}
        {/* Złota belka tylko przygasa, nigdy nie znika — migotanie do zera
            czytałoby się jak usterka, a nie jak zaproszenie. */}
        <Animated.View style={[s.sideMark, zloty ? s.sideMarkGold : null,
                               tab.tint ? { backgroundColor: tab.tint } : null,
                               { opacity: zloty ? odbij(puls, 0.45, 1) : a,
                                 transform: [{ scaleY: zloty ? 1 : a }] }]} />
        <View style={s.sideIcon}>
          <Icon name={tab.icon} size={19} color={kolorIkony} />
        </View>
        <Text style={[s.sideLabel, { color: kolorPodpisu }, zloty && s.goldLabel]} numberOfLines={1}>
          {tab.label}
        </Text>
      </Pressable>
    );
  }

  return (
    <Pressable style={s.tab} hitSlop={6} onPress={press}>
      <Animated.View style={{ transform: [{ scale: a.interpolate({ inputRange: [0, 1], outputRange: [1, 1.12] }) }] }}>
        {poswiata}
        {/* metaliczna obwódka pod aktywną ikoną — ten sam język co przyciski */}
        <Animated.View style={[s.ring, { opacity: a }]}>
          <LinearGradient colors={tab.tint
            ? [tab.tint, tab.tint + "22"]
            : zloty
              ? ["rgba(255,210,74,.85)", "rgba(200,137,32,.15)"]
              : ["rgba(47,212,138,.75)", "rgba(47,212,138,.12)"]}
                          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={s.ringEdge}>
            <View style={[s.ringFace, zloty && s.ringFaceGold,
                          tab.tint ? { backgroundColor: tab.tint + "1c" } : null]} />
          </LinearGradient>
        </Animated.View>
        <View style={s.icon}><Icon name={tab.icon} size={19} color={kolorIkony} /></View>
      </Animated.View>
      <Text style={[s.label, { color: kolorPodpisu }, zloty && s.goldLabel]}
            numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.8}>
        {tab.short || tab.label}
      </Text>
      <Animated.View
        style={[
          s.dot,
          zloty && { backgroundColor: C.gold },
          tab.tint ? { backgroundColor: tab.tint } : null,
          { opacity: zloty ? odbij(puls, 0.45, 1) : a, transform: [{ scale: zloty ? 1 : a }] },
        ]}
      />
    </Pressable>
  );
}

const s = StyleSheet.create({
  // Wyspa, nie listwa: pasek nie dotyka żadnej krawędzi ekranu, ma zaokrąglone
  // rogi i jest półprzezroczysty, więc treść przewijana pod spodem prześwituje
  // i widać, że aplikacja idzie dalej. Odsunięcie od dołu robi `TABBAR_GAP`
  // w `App.tsx` — tutaj zostaje sam wygląd wyspy.
  bar: {
    flexDirection: "row", backgroundColor: "rgba(13,17,25,.86)",
    borderWidth: 1, borderColor: "rgba(255,255,255,.10)",
    borderRadius: 26, paddingTop: 10, paddingBottom: 10, paddingHorizontal: 3,
    // cień oddziela wyspę od treści pod nią — bez niego zlewa się z tłem
    shadowColor: "#000", shadowOpacity: 0.45, shadowRadius: 18,
    shadowOffset: { width: 0, height: 8 }, elevation: 12,
    // rozmycie tła działa tylko w przeglądarce; na telefonie zostaje sama
    // półprzezroczystość, bo `expo-blur` nie jest w zależnościach
    ...(Platform.OS === "web"
      ? ({ backdropFilter: "blur(18px)", WebkitBackdropFilter: "blur(18px)" } as any)
      : null),
  },
  // osiem zakładek na wąskim ekranie — margines boczny musi zejść prawie do zera,
  // żeby najdłuższy podpis („Narzędzia") nie łamał się na dwie linie
  tab: { flex: 1, alignItems: "center", gap: 3, paddingHorizontal: 1 },

  side: {
    width: SIDEBAR_W, backgroundColor: "rgba(15,19,28,.97)",
    borderRightWidth: 1, borderRightColor: C.border,
    paddingTop: 18, paddingHorizontal: 10, gap: 4,
  },
  sideTab: {
    flexDirection: "row", alignItems: "center", gap: 11,
    paddingVertical: 11, paddingLeft: 12, paddingRight: 10, borderRadius: 11,
    overflow: "hidden",
  },
  sideTabOn: { backgroundColor: "rgba(47,212,138,.10)" },
  sideTabGold: { borderWidth: 1, borderColor: "rgba(255,210,74,.32)" },
  sideGlow: { borderRadius: 11 },
  sideMark: {
    position: "absolute", left: 0, top: 9, bottom: 9, width: 3,
    borderRadius: 2, backgroundColor: C.green,
  },
  sideMarkGold: { backgroundColor: C.gold },
  sideLabel: { fontSize: 13, fontWeight: "700", flexShrink: 1 },
  goldLabel: {
    textShadowColor: "rgba(255,210,74,.45)", textShadowRadius: 7,
    textShadowOffset: { width: 0, height: 0 },
  },

  glow: { position: "absolute", left: -18, right: -18, top: -14, bottom: -14, borderRadius: 999 },
  ring: { position: "absolute", left: -9, right: -9, top: -5, bottom: -5 },
  ringEdge: { flex: 1, borderRadius: 999, padding: 1 },
  ringFace: { flex: 1, borderRadius: 999, backgroundColor: "rgba(47,212,138,.10)" },
  ringFaceGold: { backgroundColor: "rgba(255,210,74,.12)" },
  // Ikona jest rysunkiem, nie glifem, więc nie ma linii bazowej ani światła
  // wokół liter — pudełko o stałej wysokości trzyma podpis w tym samym miejscu
  // niezależnie od tego, jak wysoki jest sam rysunek.
  icon: { height: 19, alignItems: "center", justifyContent: "center" },
  sideIcon: { width: 22, alignItems: "center", justifyContent: "center" },
  label: { fontSize: 9.5, fontWeight: "700" },
  dot: { width: 4, height: 4, borderRadius: 2, backgroundColor: C.green, marginTop: 1 },
});
