/** Zakup subskrypcji na iPhonie — StoreKit zamiast Stripe.
 *
 *  Na iOS Apple nie zostawia wyboru: treści cyfrowe sprzedaje się przez zakup
 *  w aplikacji (wytyczna 3.1.1), a przycisk prowadzący do własnej kasy w
 *  przeglądarce kończy się odrzuceniem wydania. Web i Android zostają przy
 *  Stripe — tam prowizji sklepu nie ma.
 *
 *  Podział odpowiedzialności jest ten sam, co w całej aplikacji: telefon
 *  przeprowadza płatność, ale o premium NIE decyduje. Po udanym zakupie wysyła
 *  serwerowi sam identyfikator transakcji, a ten pyta o niego App Store Server
 *  API (`bot/apple_iap.py`). Dopiero odpowiedź Apple nadaje uprawnienie.
 *
 *  `expo-iap` wymaga modułu natywnego, więc w Expo Go i w przeglądarce go nie
 *  ma — dlatego `require` siedzi w try/catch, a `APPLE_STORE` mówi reszcie
 *  aplikacji, czy tę drogę w ogóle pokazywać.
 */
import React, { useCallback, useEffect, useRef, useState } from "react";
import { ActivityIndicator, Alert, Platform, Pressable, StyleSheet, Text, View } from "react-native";
import { PremiumPlan, verifyApplePurchase } from "../api";
import { C } from "../theme";
import { CheckoutButton } from "../ui";
import SubscriptionTerms, { money } from "./SubscriptionTerms";

let IAP: any = null;
try {
  if (Platform.OS === "ios") IAP = require("expo-iap");
} catch {
  IAP = null;                        // Expo Go albo web — zostaje droga przez Stripe
}

/** Czy na tym urządzeniu sprzedaje Apple (iOS). */
export const APPLE_STORE = Platform.OS === "ios";

export default function AppleBuyBox({
  plans, selected, loggedIn, userId, onLogin, onPrices, onGranted,
}: {
  plans: PremiumPlan[];
  selected: string;
  loggedIn: boolean;
  /** identyfikator konta Portevo — wędruje do transakcji jako `appAccountToken`,
   *  żeby powiadomienia o odnowieniu trafiały do właściwego konta */
  userId: string;
  onLogin: () => void;
  /** ceny prosto ze StoreKit — karty planów mają pokazywać kwotę Apple, nie naszą */
  onPrices: (byPlan: Record<string, string>) => void;
  /** premium właśnie przyznane — czas odświeżyć stan konta */
  onGranted: () => void;
}) {
  if (!IAP || !IAP.useIAP) {
    // Tu trafia Expo Go i przeglądarka. Warunek 3.1.2(c) obowiązuje CAŁY ekran
    // zakupu, więc informacja o subskrypcji i odnośniki prawne muszą stać także
    // w tej gałęzi — inaczej wystarczy jedno urządzenie bez StoreKit, żeby
    // recenzent zobaczył paywall bez wymaganych treści.
    const plan = plans.find((p) => p.id === selected) || plans[0];
    return (
      <View style={{ paddingVertical: 14, gap: 10 }}>
        <Text style={{ color: C.muted, fontSize: 13, textAlign: "center", lineHeight: 19 }}>
          Subskrypcje są obsługiwane bezpośrednio przez Apple In-App Purchase w wydaniu App Store / TestFlight.
        </Text>
        <SubscriptionTerms
          planLabel={plan?.label}
          period={plan?.period}
          price={plan ? money(plan.price, plan.currency) : ""}
          store="apple"
        />
      </View>
    );
  }

  const skus = plans.map((p) => p.apple_id).filter(Boolean) as string[];
  const planBySku = new Map(plans.filter((p) => p.apple_id).map((p) => [p.apple_id!, p]));
  const chosen = plans.find((p) => p.id === selected) || plans[0];

  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState("");
  // zakup potrafi wrócić po zamknięciu ekranu — trzymamy to poza stanem Reacta,
  // żeby nie próbować ustawiać stanu odmontowanego komponentu
  const alive = useRef(true);
  useEffect(() => () => { alive.current = false; }, []);

  const settle = useCallback(async (purchase: any) => {
    // `id` to identyfikator transakcji StoreKit — jedyne, czego potrzebuje serwer
    try {
      const res = await verifyApplePurchase(String(purchase?.id || ""));
      if (!res.ok) {
        Alert.alert("Zakup czeka na potwierdzenie", res.message
          || "Apple jeszcze nie potwierdził tej płatności. Spróbuj za chwilę „Przywróć zakupy”.");
        return;                      // NIE domykamy transakcji — StoreKit poda ją ponownie
      }
      await IAP.finishTransaction({ purchase, isConsumable: false });
      onGranted();
      Alert.alert("Premium włączone", "Wszystko jest już odblokowane — także w panelu na komputerze.");
    } catch {
      Alert.alert("Brak połączenia", "Zakup jest bezpieczny u Apple. Otwórz aplikację ponownie, "
        + "gdy wróci internet — premium włączy się samo.");
    } finally {
      if (alive.current) setBusy(false);
    }
  }, [onGranted]);

  const {
    connected, subscriptions, fetchProducts, requestPurchase, restorePurchases,
  } = IAP.useIAP({
    onPurchaseSuccess: (p: any) => { void settle(p); },
    onPurchaseError: (e: any) => {
      if (alive.current) setBusy(false);
      // rezygnacja to nie awaria — nie zasypujemy okienkiem kogoś, kto się rozmyślił
      if (String(e?.code || "") === "user-cancelled") return;
      Alert.alert("Nie udało się kupić", e?.message || "Spróbuj ponownie za chwilę.");
    },
    onError: () => {},
  });

  useEffect(() => {
    if (connected && skus.length) fetchProducts({ skus, type: "subs" });
  }, [connected, skus.join(",")]);

  // ceny ze sklepu w górę: Apple ma własne progi cenowe i walutę kraju konta,
  // więc kwota z naszego cennika mogłaby się rozjechać z tym, co realnie zapłaci
  useEffect(() => {
    const map: Record<string, string> = {};
    for (const sub of subscriptions || []) {
      const plan = planBySku.get(sub.id);
      if (plan && sub.displayPrice) map[plan.id] = sub.displayPrice;
    }
    if (Object.keys(map).length) onPrices(map);
  }, [subscriptions]);

  async function buy() {
    if (!chosen?.apple_id) return;
    if (!loggedIn) {
      Alert.alert(
        "Najpierw konto",
        "Premium przypisuje się do konta, żeby działało też w panelu na komputerze.",
        [{ text: "Później" }, { text: "Zaloguj się", onPress: onLogin }],
      );
      return;
    }
    setBusy(true);
    setNote("");
    try {
      await requestPurchase({
        type: "subs",
        request: {
          apple: { sku: chosen.apple_id, appAccountToken: userId || undefined },
          google: { skus: [chosen.apple_id] },
        },
      });
      // dalszy ciąg dzieje się w onPurchaseSuccess / onPurchaseError
    } catch {
      setBusy(false);
    }
  }

  async function restore() {
    setBusy(true);
    setNote("Szukam wcześniejszych zakupów…");
    try {
      await restorePurchases();
      // Lista MUSI przyjść z wywołania wprost, a nie ze stanu haka: ten
      // zaktualizuje się dopiero przy kolejnym renderze, więc tutaj byłby pusty.
      const list = await IAP.getAvailablePurchases();
      const mine = (list || []).filter((p: any) => planBySku.has(p.productId));
      if (!mine.length) {
        setNote("Na tym koncie Apple nie ma aktywnej subskrypcji Portevo.");
        return;
      }
      await settle(mine[0]);
      setNote("");
    } catch {
      setNote("Nie udało się połączyć z App Store.");
    } finally {
      if (alive.current) setBusy(false);
    }
  }

  const price = chosen ? (chosen.id && subPrice(subscriptions, planBySku, chosen.id)) : "";
  const label = chosen
    ? `Wykup ${chosen.label.toLowerCase()}${price ? ` — ${price}` : ""}`
    : "Wykup subskrypcję";

  return (
    <View>
      <CheckoutButton label={label} busy={busy} onPress={buy} />

      <Pressable onPress={busy ? undefined : restore} hitSlop={10} style={s.restore}>
        {busy && note ? <ActivityIndicator size="small" color={C.dim} /> : null}
        <Text style={s.restoreTxt}>Przywróć zakupy</Text>
      </Pressable>
      {!!note && <Text style={s.note}>{note}</Text>}

      {/* Apple wymaga, żeby przy przycisku zakupu stało wprost: co, na jak długo,
          za ile i że odnawia się samo — razem z odnośnikami do regulaminu (EULA)
          i polityki prywatności. Cena: ta ze StoreKit, a gdyby App Store nie
          odpowiedział — nasza z cennika, żeby pole nigdy nie zostało puste. */}
      <SubscriptionTerms
        planLabel={chosen?.label}
        period={chosen?.period}
        price={price || (chosen ? money(chosen.price, chosen.currency) : "")}
        store="apple"
      />
    </View>
  );
}

/** Cena ze StoreKit dla naszego planu — pusta, dopóki App Store nie odpowie. */
function subPrice(subs: any[], bySku: Map<string, PremiumPlan>, planId: string): string {
  for (const sub of subs || []) {
    if (bySku.get(sub.id)?.id === planId) return sub.displayPrice || "";
  }
  return "";
}

const s = StyleSheet.create({
  restore: {
    flexDirection: "row", alignItems: "center", justifyContent: "center",
    gap: 8, marginTop: 14, paddingVertical: 6,
  },
  restoreTxt: { color: C.accent, fontSize: 13, fontWeight: "700" },
  note: { color: C.dim, fontSize: 12, textAlign: "center", marginTop: 4 },
});
