/** Ilustracje formularza majątku — obracająca się moneta i domek.
 *
 *  Po co w ogóle rysunek w formularzu? Bo „dodaj aktywo" to najbardziej suchy
 *  ekran w całej apce: kilka pól i przycisk. Moneta, która zaczyna się kręcić
 *  w chwili wyboru złota, mówi bez słów, że apka rozpoznała, o co chodzi —
 *  i że dalej będzie już łatwo. To jedyne zadanie tej animacji.
 *
 *  Rysowane w SVG, a nie obrazkiem, z trzech powodów: waży kilka kilobajtów
 *  zamiast kilkuset, jest ostre na każdym ekranie i ta sama moneta obsługuje
 *  złoto, srebro i platynę — zmienia się wyłącznie gradient.
 *
 *  Obrót idzie przez `rotateY` z perspektywą. Na telefonie robi to natywnie
 *  warstwa animacji, w przeglądarce ta sama własność ląduje w CSS `transform` —
 *  jeden kod, dwa światy, zero rozgałęzień.
 */
import React, { useEffect, useRef } from "react";
import { Animated, Easing, Platform, View } from "react-native";
import Svg, {
  Circle, Defs, Ellipse, G, Line, LinearGradient as SvgGradient, Path, Rect, Stop, Text as SvgText,
} from "react-native-svg";
import { useSvgId } from "../svgIds";
import { C } from "../theme";

/* =========================================================== moneta */

export type Metal = "zloto" | "srebro" | "platyna";

/** Twarz monety: jasny brzeg, ciemniejszy środek, jeszcze ciemniejszy rant.
 *  Trzy przystanki wystarczają, żeby płaskie koło czytało się jak metal. */
const METALE: Record<Metal, { jasny: string; sredni: string; ciemny: string; opis: string }> = {
  zloto:    { jasny: "#ffe9a8", sredni: "#e8b62c", ciemny: "#8a5f0d", opis: "999.9" },
  srebro:   { jasny: "#f2f5f9", sredni: "#b9c3cf", ciemny: "#6b7482", opis: "999" },
  platyna:  { jasny: "#eef3f8", sredni: "#c3ccd6", ciemny: "#79838f", opis: "9995" },
};

/** Liść klonu — motyw z monety bulionowej, uproszczony do jednej ścieżki.
 *  Symetryczny względem osi pionowej, bo tak wygląda każdy bity liść. */
const LISC =
  "M50 14 L55 31 L66 25 L62 39 L77 36 L73 46 L88 52 L73 58 L77 68 L62 65 L66 79 "
  + "L55 73 L53 88 L47 88 L45 73 L34 79 L38 65 L23 68 L27 58 L12 52 L27 46 L23 36 "
  + "L38 39 L34 25 L45 31 Z";

export function Moneta({ metal = "zloto", rozmiar = 116, kreci = true }: {
  metal?: Metal; rozmiar?: number; kreci?: boolean;
}) {
  const m = METALE[metal] || METALE.zloto;
  const obrot = useRef(new Animated.Value(0)).current;
  const twarz = useSvgId("mon");
  const rant = useSvgId("rant");

  useEffect(() => {
    if (!kreci) return;
    // Bez `setValue(0)` moneta po zmianie metalu podskakiwałaby o kawałek obrotu.
    obrot.setValue(0);
    const anim = Animated.loop(Animated.timing(obrot, {
      toValue: 1, duration: 4600, easing: Easing.linear, useNativeDriver: true,
    }));
    anim.start();
    return () => anim.stop();
  }, [kreci, metal]);

  const kat = obrot.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "360deg"] });
  // Rant ma szerokość, więc moneta ustawiona bokiem nie może zniknąć do zera —
  // ściśnięcie do ośmiu procent zostawia kreskę, która wygląda jak jej krawędź.
  const scaleX = obrot.interpolate({
    inputRange: [0, 0.25, 0.5, 0.75, 1],
    outputRange: [1, 0.08, 1, 0.08, 1],
  });

  // Na telefonie obracamy w trzech wymiarach, w przeglądarce ściskamy w poziomie.
  // Efekt jest ten sam, a `rotateY` na webie łapie się na różnice w obsłudze
  // `perspective` między silnikami i potrafi zostawić monetę odwróconą tyłem.
  const transform: any = Platform.OS === "web"
    ? [{ scaleX }]
    : [{ perspective: 900 }, { rotateY: kat }];

  const r = rozmiar;
  return (
    <View style={{ alignItems: "center", justifyContent: "center", height: r + 18 }}>
      <Animated.View style={{ width: r, height: r, transform }}>
        <Svg width={r} height={r} viewBox="0 0 100 100">
          <Defs>
            <SvgGradient id={twarz} x1="0.15" y1="0" x2="0.85" y2="1">
              <Stop offset="0" stopColor={m.jasny} />
              <Stop offset="0.45" stopColor={m.sredni} />
              <Stop offset="1" stopColor={m.ciemny} />
            </SvgGradient>
            <SvgGradient id={rant} x1="0" y1="0" x2="1" y2="1">
              <Stop offset="0" stopColor={m.ciemny} />
              <Stop offset="0.5" stopColor={m.jasny} />
              <Stop offset="1" stopColor={m.ciemny} />
            </SvgGradient>
          </Defs>

          <Circle cx="50" cy="50" r="49" fill={`url(#${rant})`} />
          {/* karbowany rant — 60 kresek, tak jak na biciu menniczym */}
          <G opacity="0.55">
            {Array.from({ length: 60 }, (_, i) => {
              const a = (i / 60) * Math.PI * 2;
              return (
                <Line key={i}
                      x1={50 + Math.cos(a) * 44} y1={50 + Math.sin(a) * 44}
                      x2={50 + Math.cos(a) * 49} y2={50 + Math.sin(a) * 49}
                      stroke={m.ciemny} strokeWidth="1.1" />
              );
            })}
          </G>
          <Circle cx="50" cy="50" r="44" fill={`url(#${twarz})`} />
          <Circle cx="50" cy="50" r="41" fill="none" stroke={m.jasny} strokeWidth="0.8"
                  opacity="0.5" />
          <Path d={LISC} fill={m.ciemny} opacity="0.42" />
          <Path d={LISC} fill="none" stroke={m.jasny} strokeWidth="0.9" opacity="0.7" />
          <SvgText x="50" y="97" fontSize="6.4" fontWeight="bold" fill={m.ciemny}
                   textAnchor="middle" opacity="0.85">{m.opis}</SvgText>
        </Svg>
      </Animated.View>
      {/* cień pod monetą — bez niego wisi w próżni */}
      <Svg width={r} height={16} style={{ marginTop: -6 }}>
        <Ellipse cx={r / 2} cy="8" rx={r * 0.3} ry="4" fill="#000" opacity="0.35" />
      </Svg>
    </View>
  );
}

/* =========================================================== domek */

export type TypNieruchomosci = "mieszkanie" | "dom" | "dzialka" | "lokal";

/** Domek do formularza nieruchomości — okna zapalają się i gasną.
 *
 *  Cztery kształty zamiast jednego, bo działka z kominem byłaby po prostu
 *  nieprawdą, a to jedyna rzecz, jaką ten rysunek ma do powiedzenia: „wiem,
 *  co dodajesz".
 */
export function Domek({ typ = "mieszkanie", rozmiar = 116 }: {
  typ?: TypNieruchomosci; rozmiar?: number;
}) {
  const blask = useRef(new Animated.Value(0.35)).current;
  const unos = useRef(new Animated.Value(0)).current;
  const dach = useSvgId("dach");

  useEffect(() => {
    const anim = Animated.loop(Animated.sequence([
      Animated.parallel([
        Animated.timing(blask, { toValue: 1, duration: 1700, easing: Easing.inOut(Easing.quad),
                                 useNativeDriver: true }),
        Animated.timing(unos, { toValue: -3, duration: 1700, easing: Easing.inOut(Easing.quad),
                                useNativeDriver: true }),
      ]),
      Animated.parallel([
        Animated.timing(blask, { toValue: 0.35, duration: 1700, easing: Easing.inOut(Easing.quad),
                                 useNativeDriver: true }),
        Animated.timing(unos, { toValue: 0, duration: 1700, easing: Easing.inOut(Easing.quad),
                                useNativeDriver: true }),
      ]),
    ]));
    anim.start();
    return () => anim.stop();
  }, []);

  const r = rozmiar;
  return (
    <View style={{ alignItems: "center", justifyContent: "center", height: r + 18 }}>
      <Animated.View style={{ width: r, height: r, transform: [{ translateY: unos }] }}>
        <Svg width={r} height={r} viewBox="0 0 100 100">
          <Defs>
            <SvgGradient id={dach} x1="0" y1="0" x2="1" y2="1">
              <Stop offset="0" stopColor={C.amber} />
              <Stop offset="1" stopColor="#b06d1e" />
            </SvgGradient>
          </Defs>

          {typ === "dzialka" ? (
            <G>
              {/* działka: sam grunt i płot — żadnego dachu, bo go nie ma */}
              <Path d="M8 66 L50 48 L92 66 L50 84 Z" fill="#22402f" stroke={C.green}
                    strokeWidth="1.6" />
              <Path d="M8 66 L50 48 L92 66 L50 84 Z" fill="none" stroke={C.green}
                    strokeWidth="1.6" opacity="0.5" />
              {[0, 1, 2, 3, 4].map((i) => (
                <Line key={i} x1={16 + i * 17} y1={70 - i * 0.5} x2={16 + i * 17} y2={54 - i * 0.5}
                      stroke={C.dim} strokeWidth="2" strokeLinecap="round" />
              ))}
              <Line x1="14" y1="60" x2="90" y2="60" stroke={C.dim} strokeWidth="1.6"
                    opacity="0.7" />
            </G>
          ) : typ === "lokal" ? (
            <G>
              {/* lokal usługowy: parter z markizą i witryną */}
              <Rect x="18" y="34" width="64" height="50" rx="3" fill={C.cardHi}
                    stroke={C.border2} strokeWidth="1.6" />
              <Path d="M14 40 L86 40 L80 50 L20 50 Z" fill={`url(#${dach})`} />
              <Rect x="26" y="56" width="22" height="20" rx="2" fill={C.amber} opacity="0.9" />
              <Rect x="54" y="56" width="20" height="28" rx="2" fill={C.elev}
                    stroke={C.border2} strokeWidth="1.2" />
            </G>
          ) : (
            <G>
              {/* dom i mieszkanie różnią się szerokością bryły i liczbą pięter */}
              <Path d={typ === "dom" ? "M50 14 L92 46 L8 46 Z" : "M50 18 L86 44 L14 44 Z"}
                    fill={`url(#${dach})`} />
              <Rect x={typ === "dom" ? 16 : 22} y="46" width={typ === "dom" ? 68 : 56}
                    height={typ === "dom" ? 38 : 40} rx="2.5" fill={C.cardHi}
                    stroke={C.border2} strokeWidth="1.6" />
              {typ === "dom" && (
                <Rect x="66" y="20" width="9" height="14" rx="1.5" fill="#8a5f0d" />
              )}
              <Rect x={typ === "dom" ? 44 : 46} y="64" width="12" height="20" rx="1.5"
                    fill={C.elev} stroke={C.border2} strokeWidth="1.2" />
              <Circle cx={typ === "dom" ? 53 : 55} cy="74" r="1.3" fill={C.gold} />
            </G>
          )}
        </Svg>
        {/* okna nakładane osobno, bo tylko one pulsują — reszta bryły stoi */}
        {typ !== "dzialka" && (
          <Animated.View style={{
            position: "absolute", top: 0, left: 0, right: 0, bottom: 0, opacity: blask,
          }}>
            <Svg width={r} height={r} viewBox="0 0 100 100">
              {typ === "lokal" ? (
                <Rect x="26" y="56" width="22" height="20" rx="2" fill={C.gold} opacity="0.75" />
              ) : (
                <G>
                  <Rect x={typ === "dom" ? 24 : 29} y="54" width="13" height="12" rx="1.5"
                        fill={C.gold} opacity="0.85" />
                  <Rect x={typ === "dom" ? 63 : 58} y="54" width="13" height="12" rx="1.5"
                        fill={C.gold} opacity="0.85" />
                </G>
              )}
            </Svg>
          </Animated.View>
        )}
      </Animated.View>
      <Svg width={r} height={16} style={{ marginTop: -6 }}>
        <Ellipse cx={r / 2} cy="8" rx={r * 0.32} ry="4" fill="#000" opacity="0.3" />
      </Svg>
    </View>
  );
}
