/** Skrzynka powiadomień — to, co serwer wysłał, nawet gdy telefon był wyłączony.
 *
 *  Po co skrzynka, skoro jest powiadomienie systemowe: powiadomienie znika po
 *  przesunięciu palcem i nie ma go już nigdzie. Przy wiadomości „przejęcie
 *  spółki z Twojego portfela" to za mało. Skrzynka jest jedynym miejscem,
 *  w którym ta informacja przetrwa — i dlatego zapis do niej idzie PRZED
 *  wysyłką kanałami (patrz `bot/notify/engine.py`).
 */
import React, { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, Modal, ScrollView, StyleSheet, Text, View } from "react-native";
import { getSkrzynka, oznaczPrzeczytane, Powiadomienie } from "../../api";
import { openCompany } from "../../companyRouter";
import * as powiadomienia from "../../notifications";
import { C, T } from "../../theme";
import { Card, FadeIn, MetalButton, Press } from "../../ui";
import Icon from "../../ui/Icon";

const ETYKIETY: Record<string, string> = {
  news: "News",
  earnings_today: "Wyniki dziś",
  earnings_week: "Tydzień",
  insider: "Insajder",
};

/** „przed chwilą", „3 h temu", „12 września" — data w formie, w jakiej się o niej myśli. */
function kiedy(iso: string): string {
  if (!iso) return "";
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return "";
  const min = Math.round((Date.now() - t) / 60000);
  if (min < 2) return "przed chwilą";
  if (min < 60) return `${min} min temu`;
  const h = Math.round(min / 60);
  if (h < 24) return `${h} h temu`;
  return new Date(t).toLocaleDateString("pl-PL", { day: "numeric", month: "long" });
}

export default function NotifyInbox({ onZamknij }: { onZamknij: () => void }) {
  const [items, setItems] = useState<Powiadomienie[]>([]);
  const [ladowanie, setLadowanie] = useState(true);
  const [blad, setBlad] = useState("");

  const wczytaj = useCallback(async () => {
    try {
      const r = await getSkrzynka(60);
      setItems(r.items);
      setBlad("");
      // Otwarcie skrzynki JEST przeczytaniem — osobny przycisk „oznacz jako
      // przeczytane" kazałby robić drugi raz to, co się właśnie zrobiło.
      if (r.unread > 0) {
        oznaczPrzeczytane().catch(() => { /* licznik zgaśnie przy następnym wejściu */ });
        powiadomienia.wyczyscOdznake();
      }
    } catch (e: any) {
      setBlad(e?.message || "Nie udało się pobrać skrzynki");
    } finally {
      setLadowanie(false);
    }
  }, []);

  useEffect(() => { wczytaj(); }, [wczytaj]);

  return (
    <Modal transparent animationType="slide" visible onRequestClose={onZamknij}>
      <View style={s.tlo}>
        <View style={s.panel}>
          <View style={s.naglowek}>
            <View style={{ flex: 1 }}>
              <Text style={s.tytul}>Powiadomienia</Text>
              <Text style={s.podtytul}>Wszystko, co do Ciebie wysłaliśmy</Text>
            </View>
            <Press style={s.zamknij} onPress={onZamknij}>
              <Icon name="zamknij" size={16} color={C.muted} />
            </Press>
          </View>

          {ladowanie ? (
            <View style={s.srodek}><ActivityIndicator color={C.green} size="large" /></View>
          ) : blad ? (
            <View style={s.srodek}>
              <Text style={s.bladTxt}>{blad}</Text>
              <MetalButton label="Spróbuj ponownie" tone="steel" onPress={wczytaj} />
            </View>
          ) : items.length === 0 ? (
            <View style={s.srodek}>
              <Icon name="dzwonek" size={28} color={C.dim} />
              <Text style={s.pustoTytul}>Jeszcze nic tu nie ma</Text>
              <Text style={s.pustoTxt}>
                Gdy pojawi się news o spółce z Twojego portfela albo któraś z nich
                będzie publikować wyniki, wiadomość wyląduje tutaj — i zostanie,
                nawet jeśli powiadomienie na telefonie zdążysz zdjąć.
              </Text>
            </View>
          ) : (
            <ScrollView contentContainerStyle={s.lista} showsVerticalScrollIndicator={false}>
              {items.map((p, i) => (
                <FadeIn key={p.id} delay={Math.min(i * 18, 220)} offset={8}>
                  <Press
                    disabled={!p.symbol}
                    onPress={() => { if (p.symbol && openCompany(p.symbol)) onZamknij(); }}
                  >
                    <Card style={[s.wpis, !p.read && s.wpisNowy]}>
                      <View style={s.gora}>
                        <View style={s.znacznik}>
                          <Text style={s.znacznikTxt}>{ETYKIETY[p.kind] || "Info"}</Text>
                        </View>
                        <Text style={s.czas}>{kiedy(p.created_at)}</Text>
                      </View>
                      <Text style={s.wpisTytul}>{p.title}</Text>
                      {!!p.body && <Text style={s.wpisTresc}>{p.body}</Text>}
                      {!!p.symbol && (
                        <Text style={s.link}>Otwórz kartę {p.symbol} ›</Text>
                      )}
                    </Card>
                  </Press>
                </FadeIn>
              ))}
              <Text style={s.stopka}>
                Materiał informacyjny — to nie jest porada inwestycyjna ani rekomendacja.
              </Text>
            </ScrollView>
          )}
        </View>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  tlo: { flex: 1, backgroundColor: "rgba(4,6,11,.8)", justifyContent: "flex-end" },
  panel: {
    backgroundColor: C.bg, borderTopLeftRadius: 22, borderTopRightRadius: 22,
    borderTopWidth: 1, borderColor: C.border2, maxHeight: "88%", paddingBottom: 8,
  },
  naglowek: {
    flexDirection: "row", alignItems: "center", gap: 10,
    paddingHorizontal: 18, paddingTop: 18, paddingBottom: 12,
  },
  tytul: { color: C.text, ...T.h1 },
  podtytul: { color: C.muted, ...T.small, marginTop: 3 },
  zamknij: {
    width: 34, height: 34, borderRadius: 12, backgroundColor: C.elev,
    borderWidth: 1, borderColor: C.border2, alignItems: "center", justifyContent: "center",
  },

  srodek: { alignItems: "center", justifyContent: "center", padding: 34, gap: 11 },
  bladTxt: { color: C.text, ...T.body, textAlign: "center" },
  pustoTytul: { color: C.text, ...T.h2 },
  pustoTxt: { color: C.muted, ...T.small, lineHeight: 19, textAlign: "center" },

  lista: { paddingHorizontal: 18, paddingBottom: 26 },
  wpis: { padding: 14, marginBottom: 9 },
  wpisNowy: { borderColor: "rgba(47,212,138,.3)" },
  gora: { flexDirection: "row", alignItems: "center", justifyContent: "space-between" },
  znacznik: {
    backgroundColor: C.elev, borderRadius: 7, paddingHorizontal: 8, paddingVertical: 3,
    borderWidth: 1, borderColor: C.border2,
  },
  znacznikTxt: { color: C.muted, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.6 },
  czas: { color: C.dim, fontSize: 11, fontWeight: "600" },
  wpisTytul: { color: C.text, fontSize: 14.5, fontWeight: "800", marginTop: 9 },
  wpisTresc: { color: C.muted, fontSize: 12.5, lineHeight: 18.5, marginTop: 5 },
  link: { color: C.green, fontSize: 12, fontWeight: "700", marginTop: 9 },
  stopka: { color: C.dim, fontSize: 11, lineHeight: 16, marginTop: 8, textAlign: "center" },
});
